@dataclass(frozen=True, slots=True)
class ScanDsaExtExternalDebtNominal1Result:
    """Complete named results of one recurrence group evaluation."""
    dsa_ext_external_debt_nominal_1: data.DsaExtExternalDebtNominal1
    dsa_ext_change_in_external_debt: data.DsaExtChangeInExternalDebt
    dsa_ext_identified_net_debt_creating_flows: data.DsaExtIdentifiedNetDebtCreatingFlows
    dsa_ext_endogenous_debt_dynamics_2: data.DsaExtEndogenousDebtDynamics2
    dsa_ext_contribution_from_nominal_interest_rate: data.DsaExtContributionFromNominalInterestRate
    dsa_ext_contribution_from_real_gdp_growth: data.DsaExtContributionFromRealGdpGrowth
    dsa_ext_contribution_from_price_and_exchange_rate_changes: data.DsaExtContributionFromPriceAndExchangeRateChanges
    dsa_ext_residual_3: data.DsaExtResidual3
