@publish(data.DSA_EXT_REVENUE_GDP_STRESS_STRESS_SCHEMA, cells=data.DSA_EXT_REVENUE_GDP_STRESS_STRESS_CELLS)
def dsa_ext_revenue_gdp_stress_stress(*, dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp, leftover_us_gdp_deflator: data.LeftoverUsGdpDeflator, c3_commodity_ext_ii_key_macroeconomic_assumptions: int | str) -> data.DsaExtRevenueGdpStressStress:
    """Compute the external revenue-to-GDP stress series for the LIC-DSF template.

    Derive stressed government revenue as a percent of GDP under the C3 commodity-price macroeconomic assumptions.

    Args:
        dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: Baseline government revenues excluding grants as a percent of GDP, as a data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp series.
        leftover_us_gdp_deflator: U.S. GDP deflator residual series used in the stress calculation, as a data.LeftoverUsGdpDeflator.
        c3_commodity_ext_ii_key_macroeconomic_assumptions: Scalar integer or string macroeconomic assumptions key for the C3 commodity external II scenario.

    Returns:
        A data.DsaExtRevenueGdpStressStress series of stressed revenue-to-GDP ratios, keyed by scenario and years from row 8.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2028:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 3)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2029:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 4)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        elif time_period == 2030:
            return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], xl_div(xl_mul(leftover_us_gdp_deflator[scenario], xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 5)), xl_sub(c3_commodity_ext_ii_key_macroeconomic_assumptions, 2))))
        return as_measure(xl_sub(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], leftover_us_gdp_deflator[scenario]))

    return data.DsaExtRevenueGdpStressStress.collect(evaluate(formula, data.DSA_EXT_REVENUE_GDP_STRESS_STRESS_REQUIRED))

@publish(data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG_SCHEMA, cells=data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG_CELLS)
def dsa_ext_of_which_public_and_publicly_guaranteed_ppg(*, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc, macro_debt_total_public_ext_debt: data.MacroDebtTotalPublicExtDebt) -> data.DsaExtOfWhichPublicAndPubliclyGuaranteedPpg:
    """Compute the baseline external PPG share of public debt.

    Derives the 'of which: public and publicly guaranteed (PPG)' indicator by dividing total public external debt by GDP expressed in national currency.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars named-axis tensor over catalog coordinates holding GDP at current prices in U.S. dollars.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc named-axis tensor over catalog coordinates holding the exchange rate in national currency per U.S. dollar.
        macro_debt_total_public_ext_debt: data.MacroDebtTotalPublicExtDebt named-axis tensor over catalog coordinates holding total public external debt.

    Returns:
        data.DsaExtOfWhichPublicAndPubliclyGuaranteedPpg named-axis series keyed by scenario and years, containing the baseline external public and publicly guaranteed (PPG) share in percent.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_mul(100, macro_debt_total_public_ext_debt[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_isnumber_lazy(lambda: xl_div(macro_debt_total_public_ext_debt[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))) else '…'))

    return data.DsaExtOfWhichPublicAndPubliclyGuaranteedPpg.collect(evaluate(formula, data.DSA_EXT_OF_WHICH_PUBLIC_AND_PUBLICLY_GUARANTEED_PPG_REQUIRED))

@publish(data.DSA_EXT_OF_WHICH_PRIVATE_SCHEMA, cells=data.DSA_EXT_OF_WHICH_PRIVATE_CELLS)
def dsa_ext_of_which_private(*, macro_debt_private_debt_pct_gdp: data.MacroDebtPrivateDebtPctGdp) -> data.DsaExtOfWhichPrivate:
    """Extract the external DSA 'of which: Private' baseline series from private debt-to-GDP.

    Build the private-debt portion of external debt, keyed by scenario and projection year, using authored coordinate identities.

    Args:
        macro_debt_private_debt_pct_gdp: Private debt as a percentage of GDP, a named-axis series over catalog coordinates, read per projection period and scenario.

    Returns:
        A data.DsaExtOfWhichPrivate series keyed by scenario and years from row 8, containing the baseline external 'of which: Private' measure.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(macro_debt_private_debt_pct_gdp[time_period])

    return data.DsaExtOfWhichPrivate.collect(evaluate(formula, data.DSA_EXT_OF_WHICH_PRIVATE_REQUIRED))

@publish(data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO_SCHEMA, cells=data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO_CELLS)
def dsa_ext_total_external_debt_service_to_exports_ratio(*, macro_debt_private_sector_short_term: data.MacroDebtPrivateSectorShortTerm, macro_debt_total_ext_debt_interest_due_include_interest: data.MacroDebtTotalExtDebtInterestDueIncludeInterest, macro_debt_total_external_amortization_due_include: data.MacroDebtTotalExternalAmortizationDueInclude, macro_debt_exports_of_goods_services: data.MacroDebtExportsOfGoodsServices) -> data.DsaExtTotalExternalDebtServiceToExportsRatio:
    """Compute the total external debt service-to-exports ratio for the LIC-DSF external baseline.

    Derive the external debt service burden relative to exports, expressed as a percentage, for DSA charts and risk analysis.

    Args:
        macro_debt_private_sector_short_term: Private-sector short-term external debt stock series, indexed by catalog coordinates; its prior-period value contributes to the debt-service numerator.
        macro_debt_total_ext_debt_interest_due_include_interest: Total external debt interest due, including interest, as a coordinate-indexed data series contributing to the current-period debt-service numerator.
        macro_debt_total_external_amortization_due_include: Total external amortization due, as a coordinate-indexed data series contributing to the current-period debt-service numerator.
        macro_debt_exports_of_goods_services: Exports of goods and services as a coordinate-indexed data series, used as the denominator for the ratio.

    Returns:
        A data.DsaExtTotalExternalDebtServiceToExportsRatio coordinate-indexed series containing the total external debt service-to-exports ratio, keyed by scenario and projection year from Chart Data row 8; non-numeric export denominators produce a string sentinel.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_mul(xl_add(xl_add(macro_debt_private_sector_short_term[time_period - 1], macro_debt_total_ext_debt_interest_due_include_interest[time_period]), macro_debt_total_external_amortization_due_include[time_period]), 100), macro_debt_exports_of_goods_services[time_period]) if xl_isnumber_lazy(lambda: xl_div(xl_add(xl_add(macro_debt_private_sector_short_term[time_period - 1], macro_debt_total_ext_debt_interest_due_include_interest[time_period]), macro_debt_total_external_amortization_due_include[time_period]), macro_debt_exports_of_goods_services[time_period])) else '...'))

    return data.DsaExtTotalExternalDebtServiceToExportsRatio.collect(evaluate(formula, data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO_REQUIRED))

@publish(data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP_SCHEMA, cells=data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP_CELLS)
def dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp(*, macro_debt_revenues_pct_gdp: data.MacroDebtRevenuesPctGdp) -> data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp:
    """Extract external-DSA government revenues excluding grants as a percent of GDP, keyed by scenario and year.

    Projects the Chart Data row 8 external baseline series of government revenues excluding grants (percent of GDP) onto the DSA coordinate space so downstream debt-ratio charts and revenue-based indicators can consume it.

    Args:
        macro_debt_revenues_pct_gdp: data.MacroDebtRevenuesPctGdp series supplying the macro-debt government revenues (percent of GDP) values read at each year of the series; non-numeric cells fall back to a blank placeholder.

    Returns:
        data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp series holding government revenues excluding grants (Baseline - external) in percent of GDP, keyed by scenario and year, with missing or non-numeric cells left blank.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((macro_debt_revenues_pct_gdp[time_period] if xl_isnumber_lazy(lambda: macro_debt_revenues_pct_gdp[time_period]) else '...'))

    return data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp.collect(evaluate(formula, data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP_REQUIRED))

@dataclass(frozen=True, slots=True)
class ScanDsaPubPublicSectorDebt1Result:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_public_sector_debt_1: data.DsaPubPublicSectorDebt1
    dsa_pub_change_in_public_sector_debt: data.DsaPubChangeInPublicSectorDebt
    dsa_pub_identified_debt_creating_flows: data.DsaPubIdentifiedDebtCreatingFlows
    dsa_pub_automatic_debt_dynamics: data.DsaPubAutomaticDebtDynamics
    dsa_pub_contribution_from_interest_rate_growth_differential: data.DsaPubContributionFromInterestRateGrowthDifferential
    dsa_pub_of_which_contribution_from_average_real_interest_rate: data.DsaPubOfWhichContributionFromAverageRealInterestRate
    dsa_pub_of_which_contribution_from_real_gdp_growth: data.DsaPubOfWhichContributionFromRealGdpGrowth
    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent: data.DsaPubAverageNominalInterestRateOnDomesticDebtInPercent
    dsa_pub_average_real_interest_rate_in_percent: data.DsaPubAverageRealInterestRateInPercent
    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent: data.DsaPubAverageRealInterestRateOnDomesticDebtInPercent
    dsa_pub_nominal_debt: data.DsaPubNominalDebt
    dsa_pub_total_public_domestic_debt: data.DsaPubTotalPublicDomesticDebt

def scan_dsa_pub_public_sector_debt_1(*, dsa_pub_of_which_external_debt: data.DsaPubOfWhichExternalDebt, dsa_pub_primary_deficit: data.DsaPubPrimaryDeficit, dsa_pub_contribution_from_real_exchange_rate_depreciation: data.DsaPubContributionFromRealExchangeRateDepreciation, dsa_pub_denominator_1_g: data.DsaPubDenominator1G, dsa_pub_other_identified_debt_creating_flows: data.DsaPubOtherIdentifiedDebtCreatingFlows, dsa_pub_residual: data.DsaPubResidual, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, dsa_pub_real_gdp_growth_in_percent: data.DsaPubRealGdpGrowthInPercent, dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.DsaPubAverageRealInterestRateOnExternalDebtInPercent, dsa_pub_inflation_rate_gdp_deflator_in_percent: data.DsaPubInflationRateGdpDeflatorInPercent, dsa_pub_total_public_external_debt: data.DsaPubTotalPublicExternalDebt, dsa_pub_domestic_debt: data.DsaPubDomesticDebt, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc, macro_debt_total_public_debt_outstanding_year_end: data.MacroDebtTotalPublicDebtOutstandingYearEnd, pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt: data.PvResfinPubAssumptionsAverageInterestRateOnDomesticDebt) -> ScanDsaPubPublicSectorDebt1Result:
    """Evaluate the recurrence group `dsa_pub_public_sector_debt_1`, `dsa_pub_change_in_public_sector_debt`, `dsa_pub_identified_debt_creating_flows`, `dsa_pub_automatic_debt_dynamics`, `dsa_pub_contribution_from_interest_rate_growth_differential`, `dsa_pub_of_which_contribution_from_average_real_interest_rate`, `dsa_pub_of_which_contribution_from_real_gdp_growth`, `dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_average_real_interest_rate_in_percent`, `dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_nominal_debt`, `dsa_pub_total_public_domestic_debt` and publish complete tensors."""
    def dsa_pub_public_sector_debt_1_formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_total_public_debt_outstanding_year_end[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_isnumber_lazy(lambda: xl_div(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))) else '.'))
        return as_measure(xl_add(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_change_in_public_sector_debt[scenario, time_period]))

    dsa_pub_public_sector_debt_1 = CoordinateReader('dsa_pub_public_sector_debt_1', data.DSA_PUB_PUBLIC_SECTOR_DEBT_1_REQUIRED, dsa_pub_public_sector_debt_1_formula)
    def dsa_pub_change_in_public_sector_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_identified_debt_creating_flows[scenario, time_period], dsa_pub_residual[scenario, time_period]))

    dsa_pub_change_in_public_sector_debt = CoordinateReader('dsa_pub_change_in_public_sector_debt', data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT_REQUIRED, dsa_pub_change_in_public_sector_debt_formula)
    def dsa_pub_identified_debt_creating_flows_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(dsa_pub_primary_deficit[scenario, time_period], dsa_pub_automatic_debt_dynamics[scenario, time_period]), dsa_pub_other_identified_debt_creating_flows[scenario, time_period]))

    dsa_pub_identified_debt_creating_flows = CoordinateReader('dsa_pub_identified_debt_creating_flows', data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS_REQUIRED, dsa_pub_identified_debt_creating_flows_formula)
    def dsa_pub_automatic_debt_dynamics_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_contribution_from_interest_rate_growth_differential[scenario, time_period], dsa_pub_contribution_from_real_exchange_rate_depreciation[scenario, time_period]))

    dsa_pub_automatic_debt_dynamics = CoordinateReader('dsa_pub_automatic_debt_dynamics', data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS_REQUIRED, dsa_pub_automatic_debt_dynamics_formula)
    def dsa_pub_contribution_from_interest_rate_growth_differential_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_of_which_contribution_from_average_real_interest_rate[scenario, time_period], dsa_pub_of_which_contribution_from_real_gdp_growth[scenario, time_period]))

    dsa_pub_contribution_from_interest_rate_growth_differential = CoordinateReader('dsa_pub_contribution_from_interest_rate_growth_differential', data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL_REQUIRED, dsa_pub_contribution_from_interest_rate_growth_differential_formula)
    def dsa_pub_of_which_contribution_from_average_real_interest_rate_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_div(dsa_pub_average_real_interest_rate_in_percent[scenario, time_period], 100), dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_denominator_1_g[scenario, time_period]))

    dsa_pub_of_which_contribution_from_average_real_interest_rate = CoordinateReader('dsa_pub_of_which_contribution_from_average_real_interest_rate', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE_REQUIRED, dsa_pub_of_which_contribution_from_average_real_interest_rate_formula)
    def dsa_pub_of_which_contribution_from_real_gdp_growth_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_neg(xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)), xl_div(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_denominator_1_g[scenario, time_period])))

    dsa_pub_of_which_contribution_from_real_gdp_growth = CoordinateReader('dsa_pub_of_which_contribution_from_real_gdp_growth', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH_REQUIRED, dsa_pub_of_which_contribution_from_real_gdp_growth_formula)
    def dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt[time_period], 100) if xl_eq(dsa_pub_total_public_domestic_debt[scenario, time_period - 1], 0) else xl_mul(xl_div(dsa_pub_domestic_debt[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period - 1]), 100)))

    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT_REQUIRED, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_average_real_interest_rate_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_mul(xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period]), xl_mul(xl_sub(1, xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1])), dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[scenario, time_period])))

    dsa_pub_average_real_interest_rate_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT_REQUIRED, dsa_pub_average_real_interest_rate_in_percent_formula)
    def dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[scenario, time_period], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT_REQUIRED, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_nominal_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_public_sector_debt_1[scenario, time_period], 100), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    dsa_pub_nominal_debt = CoordinateReader('dsa_pub_nominal_debt', data.DSA_PUB_NOMINAL_DEBT_REQUIRED, dsa_pub_nominal_debt_formula)
    def dsa_pub_total_public_domestic_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_pub_nominal_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, time_period]))

    dsa_pub_total_public_domestic_debt = CoordinateReader('dsa_pub_total_public_domestic_debt', data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT_REQUIRED, dsa_pub_total_public_domestic_debt_formula)
    return ScanDsaPubPublicSectorDebt1Result(
        dsa_pub_public_sector_debt_1=data.DsaPubPublicSectorDebt1.collect((coord, dsa_pub_public_sector_debt_1[coord]) for coord in data.DSA_PUB_PUBLIC_SECTOR_DEBT_1_REQUIRED),
        dsa_pub_change_in_public_sector_debt=data.DsaPubChangeInPublicSectorDebt.collect((coord, dsa_pub_change_in_public_sector_debt[coord]) for coord in data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT_REQUIRED),
        dsa_pub_identified_debt_creating_flows=data.DsaPubIdentifiedDebtCreatingFlows.collect((coord, dsa_pub_identified_debt_creating_flows[coord]) for coord in data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS_REQUIRED),
        dsa_pub_automatic_debt_dynamics=data.DsaPubAutomaticDebtDynamics.collect((coord, dsa_pub_automatic_debt_dynamics[coord]) for coord in data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS_REQUIRED),
        dsa_pub_contribution_from_interest_rate_growth_differential=data.DsaPubContributionFromInterestRateGrowthDifferential.collect((coord, dsa_pub_contribution_from_interest_rate_growth_differential[coord]) for coord in data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL_REQUIRED),
        dsa_pub_of_which_contribution_from_average_real_interest_rate=data.DsaPubOfWhichContributionFromAverageRealInterestRate.collect((coord, dsa_pub_of_which_contribution_from_average_real_interest_rate[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE_REQUIRED),
        dsa_pub_of_which_contribution_from_real_gdp_growth=data.DsaPubOfWhichContributionFromRealGdpGrowth.collect((coord, dsa_pub_of_which_contribution_from_real_gdp_growth[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH_REQUIRED),
        dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent=data.DsaPubAverageNominalInterestRateOnDomesticDebtInPercent.collect((coord, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT_REQUIRED),
        dsa_pub_average_real_interest_rate_in_percent=data.DsaPubAverageRealInterestRateInPercent.collect((coord, dsa_pub_average_real_interest_rate_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT_REQUIRED),
        dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent=data.DsaPubAverageRealInterestRateOnDomesticDebtInPercent.collect((coord, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT_REQUIRED),
        dsa_pub_nominal_debt=data.DsaPubNominalDebt.collect((coord, dsa_pub_nominal_debt[coord]) for coord in data.DSA_PUB_NOMINAL_DEBT_REQUIRED),
        dsa_pub_total_public_domestic_debt=data.DsaPubTotalPublicDomesticDebt.collect((coord, dsa_pub_total_public_domestic_debt[coord]) for coord in data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT_REQUIRED),
    )

@publish(data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT_SCHEMA, cells=data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT_CELLS)
def dsa_pub_of_which_external_debt(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, dsa_pub_total_public_external_debt: data.DsaPubTotalPublicExternalDebt) -> data.DsaPubOfWhichExternalDebt:
    """Compute the public external-debt-to-GDP ratio for the of-which external debt indicator.

    Derives total public external debt as a percentage of nominal GDP in local currency across scenario and projection-year coordinates.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a typed data series keyed by scenario and year.
        dsa_pub_total_public_external_debt: Total public external debt as a typed data series keyed by scenario and year.

    Returns:
        A data.DsaPubOfWhichExternalDebt series keyed by scenario and year, giving total public external debt as a percentage of nominal GDP in local currency (B1_GDP_pub).
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_total_public_external_debt[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DsaPubOfWhichExternalDebt.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT_REQUIRED))

@publish(data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT_SCHEMA, cells=data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT_CELLS)
def dsa_pub_pv_of_total_public_debt(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, dsa_pub_total_public_domestic_debt: data.DsaPubTotalPublicDomesticDebt, dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.DsaPubPvOfPublicSectorExternalDebtEndOfPeriod) -> data.DsaPubPvOfTotalPublicDebt:
    """Compute PV of total public debt (B1_GDP_pub) as a percentage of nominal GDP.

    Combines public-sector external debt PV and total public domestic debt, scaled by local-currency nominal GDP, to produce the fiscal DSA metric series.

    Args:
        dsa_pub_nominal_gdp_local_currency: Local-currency nominal GDP as a scenario- and time-keyed data.DsaPubNominalGdpLocalCurrency series.
        dsa_pub_total_public_domestic_debt: Total public domestic debt as a scenario- and time-keyed data.DsaPubTotalPublicDomesticDebt series.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: End-of-period PV of public-sector external debt as a scenario- and time-keyed data.DsaPubPvOfPublicSectorExternalDebtEndOfPeriod series.

    Returns:
        A data.DsaPubPvOfTotalPublicDebt series of PV of total public debt (B1_GDP_pub) keyed by scenario and years, with negative values clamped to zero for the A1 scenario.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure((0 if xl_lt(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100), 0) else xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100)))
        return as_measure(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DsaPubPvOfTotalPublicDebt.collect(evaluate(formula, data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT_REQUIRED))

@publish(data.DSA_PUB_PRIMARY_DEFICIT_SCHEMA, cells=data.DSA_PUB_PRIMARY_DEFICIT_CELLS)
def dsa_pub_primary_deficit(*, b6_combo_non_mkt_pub_gdp_shock_label: str, input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_pub_revenue_and_grants: data.DsaPubRevenueAndGrants, dsa_pub_primary_noninterest_expenditure: data.DsaPubPrimaryNoninterestExpenditure, dsa_pub_standard_test_parameter: data.DsaPubStandardTestParameter, dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: str, dsa_pub_standard_test_pb_rule: str, dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: str, a1_hist_pub_historical_statistics: data.A1HistPubHistoricalStatistics, baseline_pub_primary_deficit: data.BaselinePubPrimaryDeficit, leftover_primary_deficit: data.LeftoverPrimaryDeficit, leftover_revenue_gdp: data.LeftoverRevenueGdp, b2_pb_mkt_pub_i_baseline_medium_term_projections: int | str, b2_pb_nonmkt_pub_i_baseline_medium_term_projections: int | str) -> data.DsaPubPrimaryDeficit:
    """Compute the public-sector primary deficit path across DSA scenarios and projection years.

    Apply baseline, historical-average, and standardized stress-test identities to produce the public primary deficit series used in LIC-DSF fiscal outputs.

    Args:
        b6_combo_non_mkt_pub_gdp_shock_label: Label identifying the combined non-market public-sector GDP shock scenario used by the B6 stress path.
        input6_standard_size_threshold_option_historical_average_only: Threshold option label selecting historical-average-only sizing for standardized stress tests.
        input6_standard_size_threshold_option_whichever_is_lower: Threshold option label selecting the lower of historical-average and baseline sizing for standardized stress tests.
        dsa_pub_revenue_and_grants: Public revenue and grants series over scenario and time-period coordinates.
        dsa_pub_primary_noninterest_expenditure: Public primary non-interest expenditure series over scenario and time-period coordinates.
        dsa_pub_standard_test_parameter: Standardized stress-test parameter series over scenario coordinates, selecting the B2 market-access threshold rule.
        dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: Standardized stress-test parameter label selecting the B2 non-market public-debt threshold rule.
        dsa_pub_standard_test_pb_rule: Standardized primary-balance rule label applied to the B6 market-access public-debt stress path.
        dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: Standardized primary-balance rule label applied to the B6 combined non-market public-debt stress path.
        a1_hist_pub_historical_statistics: Public historical statistics series over metric and statistic coordinates, supplying the A1 historical-average primary deficit.
        baseline_pub_primary_deficit: Baseline public primary deficit series over projection years.
        leftover_primary_deficit: Residual public primary deficit series over scenario and time-period coordinates.
        leftover_revenue_gdp: Residual public revenue-to-GDP series over scenario coordinates, used to scale B6 shock paths.
        b2_pb_mkt_pub_i_baseline_medium_term_projections: Scalar or label providing the baseline medium-term projection factor for the B2 market-access public-debt path.
        b2_pb_nonmkt_pub_i_baseline_medium_term_projections: Scalar or label providing the baseline medium-term projection factor for the B2 non-market public-debt path.

    Returns:
        A `data.DsaPubPrimaryDeficit` typed series of the public primary deficit (`B1_GDP_pub`), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_mkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_whichever_is_lower) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_historical_average_only) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b6_combo_non_mkt_pub_gdp_shock_label, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Primary deficit', 'Historical average'])
        elif scenario in ('B6_mkt', 'B6_nonmkt') and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1])) if xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1]))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_primary_deficit[scenario, time_period - 1])
        return as_measure(xl_sub(dsa_pub_primary_noninterest_expenditure[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]))

    dsa_pub_primary_deficit = CoordinateReader('dsa_pub_primary_deficit', data.DSA_PUB_PRIMARY_DEFICIT_REQUIRED, formula)
    return data.DsaPubPrimaryDeficit.collect((coord, dsa_pub_primary_deficit[coord]) for coord in data.DSA_PUB_PRIMARY_DEFICIT_REQUIRED)

@publish(data.DSA_PUB_REVENUE_AND_GRANTS_SCHEMA, cells=data.DSA_PUB_REVENUE_AND_GRANTS_CELLS)
def dsa_pub_revenue_and_grants(*, dsa_pub_of_which_grants: data.DsaPubOfWhichGrants, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_revenue_grants: data.BaselinePubRevenueGrants, baseline_pub_of_which_grants: data.BaselinePubOfWhichGrants, macro_debt_public_sector_revenues_including_grants: data.MacroDebtPublicSectorRevenuesIncludingGrants, leftover_real_interest_rate: data.LeftoverRealInterestRate, c3_commodity_pub_historical_statistics_key_variables_past_10: int | str) -> data.DsaPubRevenueAndGrants:
    """Build the public DSA revenue-and-grants series (B1_GDP_pub) across scenarios and projection years.

    Derive each scenario-year value of public sector revenue and grants by adjusting the baseline series and applying the C3 commodity-shock interest-rate correction.

    Args:
        dsa_pub_of_which_grants: Public DSA grants component (data.DsaPubOfWhichGrants), keyed by scenario and time period, added back to the baseline to reach total revenue and grants.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the public DSA (data.DsaPubNominalGdpLocalCurrency), keyed by scenario and time period, scaling the historical 2024 revenue total to a percent-of-GDP ratio.
        baseline_pub_revenue_grants: Baseline public revenue-and-grants series (data.BaselinePubRevenueGrants) indexed by time period, supplying the unshocked revenue level.
        baseline_pub_of_which_grants: Baseline grants component (data.BaselinePubOfWhichGrants) indexed by time period, removed from the baseline total before the DSA grants figure is re-added.
        macro_debt_public_sector_revenues_including_grants: Public sector revenues including grants from the Macro-Debt sheet (data.MacroDebtPublicSectorRevenuesIncludingGrants), keyed by time period, used for the 2024 historical ratio.
        leftover_real_interest_rate: Residual real interest rate (data.LeftoverRealInterestRate), held per scenario, subtracted in 2025-2027 and scaled in the C3 commodity-shock years 2028-2030.
        c3_commodity_pub_historical_statistics_key_variables_past_10: Integer or string count of past-10-year historical-statistics key variables for the C3 commodity scenario, driving the lag offsets in the 2028-2030 interest-rate ratios.

    Returns:
        data.DsaPubRevenueAndGrants series holding revenue and grants (B1_GDP_pub), keyed by scenario and projection years from row 7, with '.' for non-numeric historical values.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3' and time_period == 2028:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2029:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2030:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and 2025 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), leftover_real_interest_rate[scenario]))
        elif time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_isnumber_lazy(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])) else '.'))
        return as_measure(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]))

    return data.DsaPubRevenueAndGrants.collect(evaluate(formula, data.DSA_PUB_REVENUE_AND_GRANTS_REQUIRED))

@publish(data.DSA_PUB_OF_WHICH_GRANTS_SCHEMA, cells=data.DSA_PUB_OF_WHICH_GRANTS_CELLS)
def dsa_pub_of_which_grants(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, macro_debt_public_sector_grants: data.MacroDebtPublicSectorGrants) -> data.DsaPubOfWhichGrants:
    """Compute public-sector grants as a share of nominal GDP in local currency.

    Derive the DSA public "of which: grants" ratio by dividing macro-debt public-sector grants by nominal GDP and scaling to percent.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, a data series keyed by scenario and year, used as the denominator.
        macro_debt_public_sector_grants: Public-sector grants, a macro-debt data series keyed by year, used as the numerator.

    Returns:
        A data.DsaPubOfWhichGrants series of grants-to-GDP percentages keyed by scenario and projection years, carrying nonnumeric grant cells through as "...".
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_public_sector_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100) if xl_isnumber_lazy(lambda: macro_debt_public_sector_grants[time_period]) else '...'))

    return data.DsaPubOfWhichGrants.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_GRANTS_REQUIRED))

@publish(data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE_SCHEMA, cells=data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE_CELLS)
def dsa_pub_primary_noninterest_expenditure(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_primary_noninterest_expenditure: data.BaselinePubPrimaryNoninterestExpenditure, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc) -> data.DsaPubPrimaryNoninterestExpenditure:
    """Compute scenario-specific public primary noninterest expenditure-to-GDP paths.

    Rebase baseline primary noninterest expenditure to each public DSA scenario using nominal GDP in local currency.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and time-period-indexed nominal GDP series in local currency; supplies the scenario GDP denominator.
        baseline_pub_primary_noninterest_expenditure: Time-period-indexed baseline primary noninterest expenditure series; provides the baseline expenditure numerator to rescale.
        baseline_pub_nominal_gdp_lc: Time-period-indexed baseline nominal GDP series in local currency; supplies the baseline GDP scaling factor.

    Returns:
        A scenario- and time-period-indexed public primary noninterest expenditure series (B1_GDP_pub) with the same coordinate structure as the output catalog.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3':
            return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency['B1', time_period]))
        return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DsaPubPrimaryNoninterestExpenditure.collect(evaluate(formula, data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE_REQUIRED))

@publish(data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION_SCHEMA, cells=data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION_CELLS)
def dsa_pub_contribution_from_real_exchange_rate_depreciation(*, dsa_pub_of_which_external_debt: data.DsaPubOfWhichExternalDebt, dsa_pub_denominator_1_g: data.DsaPubDenominator1G, dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.DsaPubAverageRealInterestRateOnExternalDebtInPercent, dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: data.DsaPubRealExchangeRateDepreciationInPercentIndicatesDepreciation) -> data.DsaPubContributionFromRealExchangeRateDepreciation:
    """Compute the public DSA contribution from real exchange rate depreciation.

    Derive the B1_GDP_pub contribution series from real exchange rate depreciation using prior-period external debt and the real interest rate.

    Args:
        dsa_pub_of_which_external_debt: data.DsaPubOfWhichExternalDebt series over scenario and time_period; supplies the external debt stock from the prior period.
        dsa_pub_denominator_1_g: data.DsaPubDenominator1G series over scenario and time_period; supplies the GDP denominator for the contribution ratio.
        dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.DsaPubAverageRealInterestRateOnExternalDebtInPercent series over scenario and time_period; real interest rate on external debt in percent.
        dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: data.DsaPubRealExchangeRateDepreciationInPercentIndicatesDepreciation series over scenario and time_period; real exchange rate depreciation in percent, with positive values indicating depreciation.

    Returns:
        data.DsaPubContributionFromRealExchangeRateDepreciation series keyed by scenario and years, containing the B1_GDP_pub contribution from real exchange rate depreciation.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation[scenario, time_period], 100), dsa_pub_of_which_external_debt[scenario, time_period - 1]), xl_add(1, xl_div(dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period], 100))), dsa_pub_denominator_1_g[scenario, time_period]))

    return data.DsaPubContributionFromRealExchangeRateDepreciation.collect(evaluate(formula, data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION_REQUIRED))

@publish(data.DSA_PUB_DENOMINATOR_1_G_SCHEMA, cells=data.DSA_PUB_DENOMINATOR_1_G_CELLS)
def dsa_pub_denominator_1_g(*, dsa_pub_real_gdp_growth_in_percent: data.DsaPubRealGdpGrowthInPercent) -> data.DsaPubDenominator1G:
    """Compute the public DSA denominator 1+g from real GDP growth.

    Provide the scenario- and year-keyed denominator used in public debt dynamics.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth in percent as a typed series over scenario and year coordinates.

    Returns:
        A data.DsaPubDenominator1G typed series containing 1 plus real GDP growth divided by 100, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)))

    return data.DsaPubDenominator1G.collect(evaluate(formula, data.DSA_PUB_DENOMINATOR_1_G_REQUIRED))

@publish(data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS_SCHEMA, cells=data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS_CELLS)
def dsa_pub_other_identified_debt_creating_flows(*, dsa_pub_privatization_receipts_negative: data.DsaPubPrivatizationReceiptsNegative, dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: data.DsaPubRecognitionOfContingentLiabilitiesEGBankRecapitalization, dsa_pub_debt_relief_hipc_and_other: data.DsaPubDebtReliefHipcAndOther, dsa_pub_other_debt_creating_or_reducing_flow_please_specify: data.DsaPubOtherDebtCreatingOrReducingFlowPleaseSpecify) -> data.DsaPubOtherIdentifiedDebtCreatingFlows:
    """Sum the four public other-identified debt-creating flow components into one aggregate series.

    Compute the LIC-DSF public other-identified debt-creating flows (B1_GDP_pub) by scenario and year.

    Args:
        dsa_pub_privatization_receipts_negative: Privatization receipts (negative sign convention) as a data.DsaPubPrivatizationReceiptsNegative series keyed by scenario and year.
        dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: Recognition of contingent liabilities, e.g. bank recapitalization, as a data.DsaPubRecognitionOfContingentLiabilitiesEGBankRecapitalization series keyed by scenario and year.
        dsa_pub_debt_relief_hipc_and_other: HIPC and other debt relief as a data.DsaPubDebtReliefHipcAndOther series keyed by scenario and year.
        dsa_pub_other_debt_creating_or_reducing_flow_please_specify: Other debt-creating or debt-reducing flows (please specify) as a data.DsaPubOtherDebtCreatingOrReducingFlowPleaseSpecify series keyed by scenario and year.

    Returns:
        Aggregate other identified debt-creating flows as a data.DsaPubOtherIdentifiedDebtCreatingFlows series keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sum((dsa_pub_privatization_receipts_negative[scenario, time_period], dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization[scenario, time_period], dsa_pub_debt_relief_hipc_and_other[scenario, time_period], dsa_pub_other_debt_creating_or_reducing_flow_please_specify[scenario, time_period])))

    return data.DsaPubOtherIdentifiedDebtCreatingFlows.collect(evaluate(formula, data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS_REQUIRED))

@publish(data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE_SCHEMA, cells=data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE_CELLS)
def dsa_pub_privatization_receipts_negative(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_privatization_receipts_negative: data.BaselinePubPrivatizationReceiptsNegative, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc) -> data.DsaPubPrivatizationReceiptsNegative:
    """Rescale baseline privatization receipts (negative) by the ratio of baseline to scenario nominal GDP in local currency.

    Derive the public DSA privatization receipts (negative) series on a scenario-consistent GDP basis.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed nominal GDP in local currency for the public DSA, supplying the denominator applied to each scenario's receipt values.
        baseline_pub_privatization_receipts_negative: Baseline privatization receipts (negative), a year-keyed series over the catalog coordinates that provides the numerator before rescaling.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency, a year-keyed series over the catalog coordinates used to convert baseline receipts onto the selected scenario's GDP level.

    Returns:
        A data.DsaPubPrivatizationReceiptsNegative series of privatization receipts (negative) keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_privatization_receipts_negative[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DsaPubPrivatizationReceiptsNegative.collect(evaluate(formula, data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE_REQUIRED))

@publish(data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION_SCHEMA, cells=data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION_CELLS)
def dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_recognition_of_contingent_liab_e_g_bank: data.BaselinePubRecognitionOfContingentLiabEGBank, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc) -> data.DsaPubRecognitionOfContingentLiabilitiesEGBankRecapitalization:
    """Compute public-DSA recognition of contingent liabilities (e.g., bank recapitalization) as a share of GDP.

    Rescale baseline contingent-liability recognition into a GDP ratio using the applicable scenario's public nominal GDP path.

    Args:
        dsa_pub_nominal_gdp_local_currency: Typed nominal GDP in local currency for the public DSA, as a data series indexed by scenario and projection year.
        baseline_pub_recognition_of_contingent_liab_e_g_bank: Typed baseline recognition of contingent liabilities (e.g., bank recapitalization) amounts, as a data series indexed by projection year.
        baseline_pub_nominal_gdp_lc: Typed baseline nominal GDP in local currency, as a data series indexed by projection year.

    Returns:
        Typed data series of recognition of contingent liabilities (e.g., bank recapitalization) expressed as a percent of GDP, indexed by scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_isnumber_lazy(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period]) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_isnumber_lazy(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period]) else 0))

    return data.DsaPubRecognitionOfContingentLiabilitiesEGBankRecapitalization.collect(evaluate(formula, data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION_REQUIRED))

@publish(data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER_SCHEMA, cells=data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER_CELLS)
def dsa_pub_debt_relief_hipc_and_other(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_debt_relief_hipc_other: data.BaselinePubDebtReliefHipcOther, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc) -> data.DsaPubDebtReliefHipcAndOther:
    """Compute public debt relief (HIPC and other) as a share of GDP.

    Rescale baseline HIPC and other public debt relief by nominal GDP to produce the scenario-keyed DSA public debt relief ratio.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed data.DsaPubNominalGdpLocalCurrency series providing public nominal GDP in local currency as the denominator.
        baseline_pub_debt_relief_hipc_other: Baseline year-keyed data.BaselinePubDebtReliefHipcOther series of public debt relief from HIPC and other sources.
        baseline_pub_nominal_gdp_lc: Baseline year-keyed data.BaselinePubNominalGdpLc series used to express HIPC and other debt relief relative to local-currency GDP.

    Returns:
        data.DsaPubDebtReliefHipcAndOther series of debt relief (HIPC and other) (B1_GDP_pub), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_debt_relief_hipc_other[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DsaPubDebtReliefHipcAndOther.collect(evaluate(formula, data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER_REQUIRED))

@publish(data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY_SCHEMA, cells=data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY_CELLS)
def dsa_pub_other_debt_creating_or_reducing_flow_please_specify(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, dsa_pub_old_new_scenario_total: float | str, baseline_pub_other_debt_creating_reducing_flow_please_specify: data.BaselinePubOtherDebtCreatingReducingFlowPleaseSpecify, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc, c2_natdisaster_historical_statistics_key_variables_past_10: int | str) -> data.DsaPubOtherDebtCreatingOrReducingFlowPleaseSpecify:
    """Compute the public other debt-creating or reducing flow (please specify) series from baseline and scenario inputs.

    Derive the scenario- and year-keyed B1_GDP_pub series used by the LIC-DSF public debt projections.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed nominal GDP in local currency used to rescale baseline flows across scenarios.
        dsa_pub_old_new_scenario_total: Scalar factor or scenario label applied to the C1 2025 flow adjustment.
        baseline_pub_other_debt_creating_reducing_flow_please_specify: Baseline other debt-creating or reducing flow (please specify) series, indexed by year.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency series, indexed by year, providing the baseline scaling denominator.
        c2_natdisaster_historical_statistics_key_variables_past_10: Scalar or label supplying the C2 natural-disaster historical key-variable addend for 2025.

    Returns:
        A data.DsaPubOtherDebtCreatingOrReducingFlowPleaseSpecify series keyed by scenario and year, starting at row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C1' and time_period == 2025:
            return as_measure(xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), dsa_pub_old_new_scenario_total))
        elif scenario == 'C2' and time_period == 2025:
            return as_measure((xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10) if xl_isnumber_lazy(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period]) else xl_add(xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10)))
        elif scenario == 'C1' and time_period >= 2026:
            return as_measure(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))
        elif scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_isnumber_lazy(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period]) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_isnumber_lazy(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period]) else 0))

    return data.DsaPubOtherDebtCreatingOrReducingFlowPleaseSpecify.collect(evaluate(formula, data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY_REQUIRED))

@publish(data.DSA_PUB_RESIDUAL_SCHEMA, cells=data.DSA_PUB_RESIDUAL_CELLS)
def dsa_pub_residual(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, baseline_pub_residual: data.BaselinePubResidual, baseline_pub_nominal_gdp_lc: data.BaselinePubNominalGdpLc) -> data.DsaPubResidual:
    """Compute the public DSA residual from baseline public residual and nominal GDP series.

    Derive the public residual (B1_GDP_pub) used in the public-debt DSA.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the public DSA, as a data.DsaPubNominalGdpLocalCurrency series keyed by scenario and time-period coordinates.
        baseline_pub_residual: Baseline public residual, as a data.BaselinePubResidual series over time-period coordinates.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local currency, as a data.BaselinePubNominalGdpLc series over time-period coordinates.

    Returns:
        A data.DsaPubResidual series containing the public residual (B1_GDP_pub), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_residual[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DsaPubResidual.collect(evaluate(formula, data.DSA_PUB_RESIDUAL_REQUIRED))

@publish(data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY_SCHEMA, cells=data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY_CELLS)
def dsa_pub_nominal_gdp_local_currency(*, dsa_pub_real_gdp_growth_in_percent: data.DsaPubRealGdpGrowthInPercent, dsa_pub_inflation_rate_gdp_deflator_in_percent: data.DsaPubInflationRateGdpDeflatorInPercent, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.DsaPubNominalGdpLocalCurrency:
    """Compute nominal GDP in local currency from base-year USD GDP and exchange rate, then compound by real growth and GDP deflator inflation.

    Derive the public DSA nominal GDP path in local currency for local-currency debt ratio calculations.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth rate in percent, keyed by scenario and projection year.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: Inflation rate measured by the GDP deflator in percent, keyed by scenario and projection year.
        macro_debt_gdp_current_prices_u_s_dollars: GDP at current prices in US dollars for the base year, keyed by time period.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National currency per US dollar exchange rate, keyed by time period, used to convert the base-year GDP into local currency.

    Returns:
        Nominal GDP in local currency (B1_GDP_pub) as a typed series keyed by scenario and time period, anchored at 2024 by USD GDP converted at the exchange rate and compounded thereafter by real growth and inflation.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))
        return as_measure(xl_mul(xl_mul(dsa_pub_nominal_gdp_local_currency[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_nominal_gdp_local_currency = CoordinateReader('dsa_pub_nominal_gdp_local_currency', data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY_REQUIRED, formula)
    return data.DsaPubNominalGdpLocalCurrency.collect((coord, dsa_pub_nominal_gdp_local_currency[coord]) for coord in data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY_REQUIRED)

@publish(data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT_SCHEMA, cells=data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT_CELLS)
def dsa_pub_real_gdp_growth_in_percent(*, a1_hist_pub_historical_statistics: data.A1HistPubHistoricalStatistics, input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_ext_real_gdp_growth_in_percent: data.DsaExtRealGdpGrowthInPercent, dsa_pub_standard_test_parameter: data.DsaPubStandardTestParameter, dsa_pub_standard_test_gdp_growth_rule: str, dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: str, baseline_pub_real_gdp_growth: data.BaselinePubRealGdpGrowth, leftover_real_gdp_growth: data.LeftoverRealGdpGrowth, b1_gdp_pub_key_macroeconomic_fiscal_assumptions: int | str, b6_combo_mkt_pub_i_baseline_medium_term_projections: float | str, b6_combo_nonmkt_pub_i_baseline_medium_term_projections: float | str, leftover_nominal_interest_rate: float | str) -> data.DsaPubRealGdpGrowthInPercent:
    """Builds the public DSA real GDP growth (in percent) path by selecting, per scenario and projection year, among baseline, A1 historical-average, B1/B6 threshold, C2, and C3 rules.

    Produces the `B1_GDP_pub` public real GDP growth series consumed by the LIC-DSF public-debt stress and baseline engines.

    Args:
        a1_hist_pub_historical_statistics: Historical public statistics series over catalog coordinates; supplies the `Real GDP growth (in percent)` / `Historical average` cell used for scenario A1 in 2025.
        input6_standard_size_threshold_option_historical_average_only: Scalar string holding the Input 6 standard-size threshold option label meaning the historical average alone is used as the threshold.
        input6_standard_size_threshold_option_whichever_is_lower: Scalar string holding the Input 6 standard-size threshold option label meaning whichever candidate value is lower is used as the threshold.
        dsa_ext_real_gdp_growth_in_percent: Public external DSA real GDP growth series keyed by scenario and year; supplies the scenario C3 values through 2030.
        dsa_pub_standard_test_parameter: Public standard-test parameter series holding, per scenario, the threshold selector compared against the Input 6 option labels.
        dsa_pub_standard_test_gdp_growth_rule: Scalar string selecting the public standard-test GDP growth rule that governs the B6 market scenario branch.
        dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: Scalar string selecting the B6 combination non-market public standard-test GDP growth rule that governs the B6 non-market scenario branch.
        baseline_pub_real_gdp_growth: Baseline public real GDP growth series by year, providing the fallback and threshold-comparison growth values.
        leftover_real_gdp_growth: Leftover real GDP growth series keyed by scenario and year, holding the residual growth used in the B1/B6 threshold arithmetic and lag references.
        b1_gdp_pub_key_macroeconomic_fiscal_assumptions: Scalar integer or string holding the B1 key macroeconomic and fiscal assumption factor applied to leftover real GDP growth.
        b6_combo_mkt_pub_i_baseline_medium_term_projections: Scalar float or string holding the B6 market baseline medium-term projection factor applied to leftover real GDP growth.
        b6_combo_nonmkt_pub_i_baseline_medium_term_projections: Scalar float or string holding the B6 non-market baseline medium-term projection factor applied to leftover real GDP growth.
        leftover_nominal_interest_rate: Scalar float or string nominal interest rate subtracted from baseline real GDP growth for scenario C2 in 2025.

    Returns:
        A `data.DsaPubRealGdpGrowthInPercent` series of real GDP growth in percent (B1_GDP_pub), keyed by scenario and by years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B1' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period]))) if xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])) if xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B1' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1]))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_mkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_nonmkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'C2' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_real_gdp_growth[time_period], leftover_nominal_interest_rate))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Real GDP growth (in percent)', 'Historical average'])
        elif scenario == 'C3' and time_period <= 2030:
            return as_measure(dsa_ext_real_gdp_growth_in_percent[scenario, time_period])
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1])
        return as_measure(baseline_pub_real_gdp_growth[time_period])

    dsa_pub_real_gdp_growth_in_percent = CoordinateReader('dsa_pub_real_gdp_growth_in_percent', data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT_REQUIRED, formula)
    return data.DsaPubRealGdpGrowthInPercent.collect((coord, dsa_pub_real_gdp_growth_in_percent[coord]) for coord in data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT_REQUIRED)

@publish(data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_SCHEMA, cells=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_CELLS)
def dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar, dsa_pub_total_public_external_debt: data.DsaPubTotalPublicExternalDebt, dsa_pub_external_debt: data.DsaPubExternalDebt, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.DsaPubAverageNominalInterestRateOnExternalDebtInPercent:
    """Compute the average nominal interest rate on external debt in percent.

    Derives the B1_GDP_pub series from external debt stocks and exchange-rate scaling.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Typed macro-debt exchange-rate series in national currency per U.S. dollar, indexed by period and used at the prior projection step.
        dsa_pub_total_public_external_debt: Typed public external debt stock series providing the lagged denominator for the interest-rate ratio.
        dsa_pub_external_debt: Typed external debt stock series providing the current-period numerator.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Typed national-currency exchange-rate series used as the current-period scaling factor.

    Returns:
        A typed data.DsaPubAverageNominalInterestRateOnExternalDebtInPercent series (B1_GDP_pub), keyed by scenario and year, giving the average nominal interest rate on external debt in percent.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_external_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, time_period - 1]), 100), macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.DsaPubAverageNominalInterestRateOnExternalDebtInPercent.collect(evaluate(formula, data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_REQUIRED))

@publish(data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_SCHEMA, cells=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_CELLS)
def dsa_pub_average_real_interest_rate_on_external_debt_in_percent(*, dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: data.DsaPubAverageNominalInterestRateOnExternalDebtInPercent, dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.DsaPubUsInflationRateGdpDeflatorInPercent) -> data.DsaPubAverageRealInterestRateOnExternalDebtInPercent:
    """Compute the average real interest rate on external debt in percent from nominal external-debt interest-rate and US inflation series.

    Derive the DSA external-debt real interest rate by deflating the average nominal rate with US GDP-deflator inflation.

    Args:
        dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: A data.DsaPubAverageNominalInterestRateOnExternalDebtInPercent series of average nominal interest rates on external debt, in percent, keyed by scenario and time period.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: A data.DsaPubUsInflationRateGdpDeflatorInPercent series of US inflation rates measured by the GDP deflator, in percent, keyed by scenario and time period.

    Returns:
        A data.DsaPubAverageRealInterestRateOnExternalDebtInPercent series of average real interest rates on external debt, in percent, keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period], dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))) if xl_isnumber_lazy(lambda: dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period]) else '...'))

    return data.DsaPubAverageRealInterestRateOnExternalDebtInPercent.collect(evaluate(formula, data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT_REQUIRED))

@dataclass(frozen=True, slots=True)
class ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_exchange_rate_lc_per_us_dollar: data.DsaPubExchangeRateLcPerUsDollar
    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc: data.DsaPubB5DepreciationPubExchangeRateUsDollarPerLc

def scan_dsa_pub_exchange_rate_lc_per_us_dollar(*, dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.DsaPubB5DepreciationPubNominalAppreciationIncreaseInUsDollarValueOfLocalCurrencyInPercent, baseline_pub_exchange_rate_lc_per_us_dollar: data.BaselinePubExchangeRateLcPerUsDollar, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar) -> ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Evaluate the recurrence group `dsa_pub_exchange_rate_lc_per_us_dollar`, `dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc` and publish complete tensors."""
    def dsa_pub_exchange_rate_lc_per_us_dollar_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B5' and time_period >= 2025:
            return as_measure(xl_div(1, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(baseline_pub_exchange_rate_lc_per_us_dollar[time_period])

    dsa_pub_exchange_rate_lc_per_us_dollar = CoordinateReader('dsa_pub_exchange_rate_lc_per_us_dollar', data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR_REQUIRED, dsa_pub_exchange_rate_lc_per_us_dollar_formula)
    def dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_div(1, dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period], 100))))

    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc = CoordinateReader('dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc', data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC_REQUIRED, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula)
    return ScanDsaPubExchangeRateLcPerUsDollarResult(
        dsa_pub_exchange_rate_lc_per_us_dollar=data.DsaPubExchangeRateLcPerUsDollar.collect((coord, dsa_pub_exchange_rate_lc_per_us_dollar[coord]) for coord in data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR_REQUIRED),
        dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc=data.DsaPubB5DepreciationPubExchangeRateUsDollarPerLc.collect((coord, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[coord]) for coord in data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC_REQUIRED),
    )

@publish(data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR_SCHEMA, cells=data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR_CELLS)
def dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.DsaPubExchangeRateLcPerUsDollar) -> data.DsaPubNominalDepreciationOfLocalCurrencyPercentageChangeInLcPerDollar:
    """Compute nominal depreciation of the local currency as the percentage change in local currency per US dollar.

    Derive the period-over-period depreciation signal from the exchange-rate series for DSA chart use.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Local currency per US dollar exchange-rate series, keyed by scenario and year.

    Returns:
        Nominal depreciation of local currency (percentage change in LC per dollar) as a data.DsaPubNominalDepreciationOfLocalCurrencyPercentageChangeInLcPerDollar series, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_sub(xl_div(dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period - 1]), 1), 100))

    return data.DsaPubNominalDepreciationOfLocalCurrencyPercentageChangeInLcPerDollar.collect(evaluate(formula, data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR_REQUIRED))

@publish(data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION_SCHEMA, cells=data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION_CELLS)
def dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation(*, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: data.DsaPubNominalDepreciationOfLocalCurrencyPercentageChangeInLcPerDollar, dsa_pub_inflation_rate_gdp_deflator_in_percent: data.DsaPubInflationRateGdpDeflatorInPercent, dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.DsaPubUsInflationRateGdpDeflatorInPercent) -> data.DsaPubRealExchangeRateDepreciationInPercentIndicatesDepreciation:
    """Compute real exchange rate depreciation in percent, where a positive value indicates depreciation.

    Derive the LIC-DSF real exchange rate depreciation series by deflating nominal local-currency depreciation with domestic and US GDP-deflator inflation.

    Args:
        dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: Nominal depreciation of the local currency per US dollar, in percent, as a data.DsaPubNominalDepreciationOfLocalCurrencyPercentageChangeInLcPerDollar series over scenario and years.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: Domestic inflation rate based on the GDP deflator, in percent, as a data.DsaPubInflationRateGdpDeflatorInPercent series over scenario and years.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: US inflation rate based on the GDP deflator, in percent, as a data.DsaPubUsInflationRateGdpDeflatorInPercent series over scenario and years.

    Returns:
        A data.DsaPubRealExchangeRateDepreciationInPercentIndicatesDepreciation series of real exchange rate depreciation in percent, keyed by scenario and years, where positive values indicate depreciation.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(xl_div(xl_mul(xl_add(100, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), 100))

    return data.DsaPubRealExchangeRateDepreciationInPercentIndicatesDepreciation.collect(evaluate(formula, data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION_REQUIRED))

@publish(data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_SCHEMA, cells=data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_CELLS)
def dsa_pub_inflation_rate_gdp_deflator_in_percent(*, a1_hist_pub_historical_statistics: data.A1HistPubHistoricalStatistics, dsa_ext_exports: data.DsaExtExports, dsa_pub_real_gdp_growth_in_percent: data.DsaPubRealGdpGrowthInPercent, dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.DsaPubB5DepreciationPubNominalAppreciationIncreaseInUsDollarValueOfLocalCurrencyInPercent, dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.DsaPubNominalAppreciationIncreaseInUsDollarValueOfLocalCurrencyInPercent, dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.DsaPubB6ComboNonMktPubNominalAppreciationIncreaseInUsDollarValueOfLocalCurrencyInPercent, dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: float | str, baseline_pub_real_gdp_growth: data.BaselinePubRealGdpGrowth, baseline_pub_inflation_rate_gdp_deflator_pct: data.BaselinePubInflationRateGdpDeflatorPct, leftover_real_interest_rate: data.LeftoverRealInterestRate, b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: float | str, b6_combo_nonmkt_pub_in_billions_of_lc: float | str, c3_commodity_pub_historical_statistics_key_variables_past_10: int | str) -> data.DsaPubInflationRateGdpDeflatorInPercent:
    """Compute the public DSA inflation rate (GDP deflator, in percent) series across scenarios and projection years.

    Derive scenario-specific public inflation paths from baseline deflator assumptions and tailored-shock adjustments.

    Args:
        a1_hist_pub_historical_statistics: Historical-statistics series providing the A1 benchmark average inflation rate (GDP deflator, in percent) used for the 2025 A1 scenario point.
        dsa_ext_exports: External exports series used by the C3 commodity-price shock to scale the export-base effect in the 2025 projection.
        dsa_pub_real_gdp_growth_in_percent: Public DSA real GDP growth in percent series used by the B1 scenario adjustment for 2025 and 2026.
        dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: Public B5 depreciation/nominal appreciation series, measuring the increase in U.S. dollar value of the local currency in percent, used by the B5 2025 adjustment.
        dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: Public nominal appreciation series, measuring the increase in U.S. dollar value of the local currency in percent, used by the B6 market-financing 2025 adjustment.
        dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: Public B6 combined non-market nominal appreciation series, measuring the increase in U.S. dollar value of the local currency in percent, used by the B6 non-market 2025 adjustment.
        dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: Scalar or string commodity-price decline in the GDP deflator for the C3 scenario, used to scale the 2025 C3 inflation adjustment.
        baseline_pub_real_gdp_growth: Baseline public real GDP growth series used by the B1 scenario to compute the growth differential for 2025 and 2026.
        baseline_pub_inflation_rate_gdp_deflator_pct: Baseline public inflation rate (GDP deflator, in percent) series used as the starting point for nearly all scenario conversions.
        leftover_real_interest_rate: Leftover real interest rate series used by the B1 and B5 scenarios to convert nominal depreciation/appreciation effects into inflation adjustments.
        b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: Scalar or string medium-term nominal public debt for the B6 market-financing scenario, used as the 2025 adjustment multiplier.
        b6_combo_nonmkt_pub_in_billions_of_lc: Scalar or string non-market public debt in billions of local currency, used as the B6 non-market 2025 adjustment multiplier.
        c3_commodity_pub_historical_statistics_key_variables_past_10: Integer or string count of historical statistics key variables over the past 10 periods, used to amortize the C3 inflation adjustment across 2026–2030.

    Returns:
        A data.DsaPubInflationRateGdpDeflatorInPercent series of inflation rate (GDP deflator, in percent) (B1_GDP_pub) keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B6_mkt' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt, dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B5' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(leftover_real_interest_rate[scenario], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_nonmkt_pub_in_billions_of_lc, dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'C3' and time_period == 2025:
            return as_measure(xl_mul(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_add(1, xl_div(xl_mul(dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator, dsa_ext_exports[scenario, time_period - 1]), 100))))
        elif scenario == 'C3' and time_period == 2026:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 1)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2027:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2028:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2029:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2030:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Inflation rate (GDP deflator, in percent)', 'Historical average'])
        elif scenario == 'B1' and time_period <= 2026:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(xl_sub(baseline_pub_real_gdp_growth[time_period], dsa_pub_real_gdp_growth_in_percent[scenario, time_period]), leftover_real_interest_rate[scenario])))
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period - 1])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct[time_period])

    dsa_pub_inflation_rate_gdp_deflator_in_percent = CoordinateReader('dsa_pub_inflation_rate_gdp_deflator_in_percent', data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_REQUIRED, formula)
    return data.DsaPubInflationRateGdpDeflatorInPercent.collect((coord, dsa_pub_inflation_rate_gdp_deflator_in_percent[coord]) for coord in data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_REQUIRED)

@publish(data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_SCHEMA, cells=data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_CELLS)
def dsa_pub_us_inflation_rate_gdp_deflator_in_percent(*, baseline_pub_us_inflation_rate_gdp_deflator_pct: data.BaselinePubUsInflationRateGdpDeflatorPct, macro_debt_us_gdp_deflator_percent_change: data.MacroDebtUsGdpDeflatorPercentChange) -> data.DsaPubUsInflationRateGdpDeflatorInPercent:
    """Selects the US inflation rate (GDP deflator, in percent) per scenario, using the historical-average deflator change for the A1 scenario and the baseline deflator percentage row otherwise.

    Assembles the published US-inflation-rate GDP-deflator series on the scenario-by-year grid required for external debt DSA charts and tables.

    Args:
        baseline_pub_us_inflation_rate_gdp_deflator_pct: A `data.BaselinePubUsInflationRateGdpDeflatorPct` series: the baseline US inflation rate from the GDP deflator, expressed in percent and keyed along the catalog scenario and year coordinates; supplied as the default value for every scenario other than A1.
        macro_debt_us_gdp_deflator_percent_change: A `data.MacroDebtUsGdpDeflatorPercentChange` series: the macro-debt workbook percent-change of the US GDP deflator, a named-axis tensor over the same catalog scenario and year coordinates, contributed as the value used for the A1 (historical average) scenario.

    Returns:
        A `data.DsaPubUsInflationRateGdpDeflatorInPercent` series holding the US inflation rate (GDP deflator, in percent) — B1_GDP_pub — with one value per scenario and year, evaluated at the required coordinate pairs.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure(macro_debt_us_gdp_deflator_percent_change[time_period])
        return as_measure(baseline_pub_us_inflation_rate_gdp_deflator_pct[time_period])

    return data.DsaPubUsInflationRateGdpDeflatorInPercent.collect(evaluate(formula, data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT_REQUIRED))

