@publish(key=('SCENARIO',), domain=None, cells=data.DSA_PUB_OLD_NEW_SCENARIO_TOTAL_CELLS)
def dsa_pub_old_new_scenario_total(*, dsa_pub_input2_coverage: data.DsaPubInput2Coverage, in6opt_standard_scenario: int | str) -> float | str:
    """Compute the old/new-scenario contingent-liability coverage total from the Input 2 coverage series.

    Produces the combined C1_Combined CL!AA60 total for DSA publication.

    Args:
        dsa_pub_input2_coverage: Typed `data.DsaPubInput2Coverage` named-axis series over catalog coordinates supplying Input 2 coverage indicators and scenario columns.
        in6opt_standard_scenario: Scalar standard-scenario selector; integer zero yields the fixed fallback total, while any other int or str selects the scenario-sum path.

    Returns:
        Numeric total as `float`, or an XL error code `str` when computation raises.
    """
    _dsa_pub_old_new_scenario_total_table_0 = view(dsa_pub_input2_coverage, rows=data.INDICATOR_AXIS_6.keys, cols=data.SCENARIO_AXIS_19.keys, cols_first=True)
    try:
        return as_measure((10 if xl_eq(in6opt_standard_scenario, 0) else xl_sum(_dsa_pub_old_new_scenario_total_table_0)))
    except XlError as error:
        return error.code

@publish(data.DSA_PUB_INPUT2_COVERAGE_SCHEMA, cells=data.DSA_PUB_INPUT2_COVERAGE_CELLS)
def dsa_pub_input2_coverage(*, contingent_liability_financial_market_pct_gdp: float | str, in2_coverage_ppp: float | str, in2_coverage_other_elements_of_govt_not_captured_in_1: int | str, in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government: int | str) -> data.DsaPubInput2Coverage:
    """Compute Input 2 contingent-liability coverage components for the public DSA template.

    Populate the Input 2 coverage table used in LIC-DSF public debt analysis.

    Args:
        contingent_liability_financial_market_pct_gdp: Contingent liability financial market percentage of GDP (scalar or string).
        in2_coverage_ppp: Purchasing power parity coverage component (scalar or string).
        in2_coverage_other_elements_of_govt_not_captured_in_1: Other general government elements not captured in Input 1 (integer or string).
        in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government: State-owned enterprise debt guaranteed and not guaranteed by government (integer or string).

    Returns:
        A `data.DsaPubInput2Coverage` series of Input 2 contingent-liability coverage components, keyed by column Z labels.
    """
    def formula(scenario: str, indicator: str) -> float | str | None:
        if indicator == 'Other general government':
            return as_measure(in2_coverage_other_elements_of_govt_not_captured_in_1)
        elif indicator == 'SoEs':
            return as_measure(in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government)
        elif indicator == 'PPP':
            return as_measure(in2_coverage_ppp)
        return as_measure(contingent_liability_financial_market_pct_gdp)

    return data.DsaPubInput2Coverage.collect(evaluate(formula, data.DSA_PUB_INPUT2_COVERAGE_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP_CELLS)
def dsa_pub_c2_natural_disaster_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, dsa_pub_exchange_rate_lc_per_us_dollar: data.DsaPubExchangeRateLcPerUsDollar, dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.DsaPubPvOfPublicSectorExternalDebtEndOfPeriod, leftover_exchange_rate_pa: data.LeftoverExchangeRatePa) -> data.DsaPubC2NaturalDisasterPvOfDebtGdp:
    """Compute the PV-of-public-external-debt-to-GDP ratio for the C2 natural disaster scenario.

    Derive the tailored natural-disaster stress path of the PV of debt-to-GDP ratio used in the public DSA stress charts.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, keyed by scenario and by year, used as the denominator after conversion to US dollars.
        dsa_pub_exchange_rate_lc_per_us_dollar: End-of-period exchange rate in local currency per US dollar, keyed by scenario and by year, used to convert the end-of-period debt stock.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Present value of public-sector external debt at end of period, keyed by scenario and by year, used as the numerator.
        leftover_exchange_rate_pa: Residual period-average exchange rate in local currency per US dollar, keyed by scenario and by year, applied to nominal GDP in local currency.

    Returns:
        PV of debt-to-GDP ratio, expressed in percent for the C2 natural disaster scenario, as a scenario- and year-keyed series aligned to the row 7 year headers.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DsaPubC2NaturalDisasterPvOfDebtGdp.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_GDP_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS_CELLS)
def dsa_pub_c2_natural_disaster_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.DsaPubExchangeRateLcPerUsDollar, dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.DsaPubPvOfPublicSectorExternalDebtEndOfPeriod, dsa_pub_c2_natural_disaster_exports_us_baseline: data.DsaPubC2NaturalDisasterExportsUsBaseline) -> data.DsaPubC2NaturalDisasterPvOfDebtExports:
    """Derive the C2 natural disaster PV of debt-to-exports series from external debt, exchange rate, and export baselines.

    Supplies the natural-disaster-scenario PV of debt-to-exports indicator used in the LIC-DSF external DSA charts.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Local-currency per US dollar exchange rate series indexed over scenario and projection years.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: End-of-period present value of public sector external debt series indexed over scenario and projection years.
        dsa_pub_c2_natural_disaster_exports_us_baseline: Baseline exports in US dollars under the C2 natural disaster scenario, indexed over scenario and projection years.

    Returns:
        A data.DsaPubC2NaturalDisasterPvOfDebtExports series of PV of debt-to-exports values keyed by scenario and years starting from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))

    return data.DsaPubC2NaturalDisasterPvOfDebtExports.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_PV_OF_DEBT_EXPORTS_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_EXPORTS_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_EXPORTS_CELLS)
def dsa_pub_c2_natural_disaster_debt_service_exports(*, dsa_pub_c2_natural_disaster_exports_us_baseline: data.DsaPubC2NaturalDisasterExportsUsBaseline, macro_debt_ppg_interest_due: data.MacroDebtPpgInterestDue, macro_debt_main_assumptions_us_dollars_by_year_6: data.MacroDebtMainAssumptionsUsDollarsByYear6, pv_resfin_pub_output_total_debt_service_in_usd: data.PvResfinPubOutputTotalDebtServiceInUsd) -> data.DsaPubC2NaturalDisasterDebtServiceExports:
    """Compute the C2 natural disaster debt service-to-exports ratio series.

    Derive the debt service-to-exports indicator under the C2 natural disaster scenario for the LIC-DSF chart output.

    Args:
        dsa_pub_c2_natural_disaster_exports_us_baseline: Baseline exports in USD for the C2 natural disaster scenario, keyed by scenario and projection year.
        macro_debt_ppg_interest_due: PPG debt interest due, keyed by projection year.
        macro_debt_main_assumptions_us_dollars_by_year_6: Macro-debt main assumptions in US dollars by year, keyed by projection year.
        pv_resfin_pub_output_total_debt_service_in_usd: Total public debt service in USD from the PV resfin public output, keyed by creditor category, scenario, and projection year.

    Returns:
        A data series of debt service-to-exports ratios for the C2 natural disaster scenario, keyed by scenario and projection years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period]), 100))

    return data.DsaPubC2NaturalDisasterDebtServiceExports.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_EXPORTS_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS_CELLS)
def dsa_pub_c2_natural_disaster_debt_service_revenue_excl_grants(*, dsa_pub_c2_natural_disaster_revenue: data.DsaPubC2NaturalDisasterRevenue, macro_debt_ppg_interest_due: data.MacroDebtPpgInterestDue, macro_debt_main_assumptions_us_dollars_by_year_6: data.MacroDebtMainAssumptionsUsDollarsByYear6, pv_resfin_pub_output_total_debt_service_in_usd: data.PvResfinPubOutputTotalDebtServiceInUsd) -> data.DsaPubC2NaturalDisasterDebtServiceRevenueExclGrants:
    """Compute C2 natural-disaster debt service-to-revenue excluding grants.

    Build the published C2 natural-disaster debt service-to-revenue excluding grants series from interest due, main assumptions, residual-financing debt service, and natural-disaster revenue.

    Args:
        dsa_pub_c2_natural_disaster_revenue: Natural-disaster revenue series over catalog coordinates, keyed by scenario and year, used as the denominator in the debt-service-to-revenue ratio.
        macro_debt_ppg_interest_due: Public and publicly guaranteed macro-debt interest due series over catalog coordinates, keyed by year, contributing to total debt service.
        macro_debt_main_assumptions_us_dollars_by_year_6: Macro-debt main assumptions expressed in U.S. dollars by year series with the year-6 variant, over catalog coordinates and keyed by year, contributing to total debt service.
        pv_resfin_pub_output_total_debt_service_in_usd: Present-value residual-financing public output total debt service in U.S. dollars series over catalog coordinates, selected for external PPG medium- and long-term debt under the CL1 natural-disaster scenario.

    Returns:
        Debt service-to-revenue ratio excluding grants for the C2 natural-disaster scenario, returned as a typed data series keyed by scenario and years from row 7, with values expressed as percentages.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_c2_natural_disaster_revenue[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_c2_natural_disaster_revenue[scenario, time_period]), 100))

    return data.DsaPubC2NaturalDisasterDebtServiceRevenueExclGrants.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_DEBT_SERVICE_REVENUE_EXCL_GRANTS_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE_CELLS)
def dsa_pub_c2_natural_disaster_exports_us_baseline(*, dsa_pub_c2_natural_disaster_exports_growth_rate: data.DsaPubC2NaturalDisasterExportsGrowthRate, macro_debt_exports_of_goods_services: data.MacroDebtExportsOfGoodsServices) -> data.DsaPubC2NaturalDisasterExportsUsBaseline:
    """Computes baseline exports (US$) for the natural disaster scenario.

    Projects baseline exports forward from 2024 using annual growth rates.

    Args:
        dsa_pub_c2_natural_disaster_exports_growth_rate: Annual growth rate (%) for exports in the natural disaster scenario, as a data.DsaPubC2NaturalDisasterExportsGrowthRate series keyed by scenario and year.
        macro_debt_exports_of_goods_services: Historical exports of goods and services (US$), as a data.MacroDebtExportsOfGoodsServices series keyed by year.

    Returns:
        A data.DsaPubC2NaturalDisasterExportsUsBaseline series of baseline exports (US$) for the natural disaster scenario, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_exports_of_goods_services[time_period])
        return as_measure(xl_mul(dsa_pub_c2_natural_disaster_exports_us_baseline[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_c2_natural_disaster_exports_growth_rate[scenario, time_period], 100))))

    dsa_pub_c2_natural_disaster_exports_us_baseline = CoordinateReader('dsa_pub_c2_natural_disaster_exports_us_baseline', data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE_REQUIRED, formula)
    return data.DsaPubC2NaturalDisasterExportsUsBaseline.collect((coord, dsa_pub_c2_natural_disaster_exports_us_baseline[coord]) for coord in data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_US_BASELINE_REQUIRED)

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE_CELLS)
def dsa_pub_c2_natural_disaster_exports_growth_rate(*, dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent: data.DsaExtGrowthOfExportsOfGSUsDollarTermsInPercent, leftover_real_interest_rate: data.LeftoverRealInterestRate) -> data.DsaPubC2NaturalDisasterExportsGrowthRate:
    """Compute the C2 natural disaster exports growth rate for public DSA scenarios.

    Derives the natural-disaster exports growth path by adjusting 2025 baseline exports growth with a scenario-specific residual real interest rate.

    Args:
        dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent: A data.DsaExtGrowthOfExportsOfGSUsDollarTermsInPercent series of baseline goods-and-services export growth in US dollar terms, expressed in percent and indexed by scenario and time period.
        leftover_real_interest_rate: A data.LeftoverRealInterestRate series indexed by scenario, supplying the residual real interest rate used to adjust the 2025 baseline exports growth value.

    Returns:
        A data.DsaPubC2NaturalDisasterExportsGrowthRate series keyed by scenario and year, containing the natural disaster exports growth rate; for 2025, the baseline exports growth is reduced by the scenario's leftover real interest rate, while all other years pass through the baseline value.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(xl_sub(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent['Baseline', time_period], leftover_real_interest_rate[scenario]))
        return as_measure(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent['Baseline', time_period])

    return data.DsaPubC2NaturalDisasterExportsGrowthRate.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_EXPORTS_GROWTH_RATE_REQUIRED))

@publish(data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE_SCHEMA, cells=data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE_CELLS)
def dsa_pub_c2_natural_disaster_revenue(*, dsa_pub_revenue_and_grants: data.DsaPubRevenueAndGrants, dsa_pub_of_which_grants: data.DsaPubOfWhichGrants, dsa_pub_nominal_gdp_local_currency: data.DsaPubNominalGdpLocalCurrency, leftover_exchange_rate_pa: data.LeftoverExchangeRatePa) -> data.DsaPubC2NaturalDisasterRevenue:
    """Compute public C2 natural disaster revenue from public revenue and grants, nominal GDP, and exchange-rate inputs.

    Derives the natural disaster revenue series used in LIC-DSF public debt analysis.

    Args:
        dsa_pub_revenue_and_grants: Typed data.DsaPubRevenueAndGrants series of public revenue and grants, keyed by scenario and time period.
        dsa_pub_of_which_grants: Typed data.DsaPubOfWhichGrants series of the grant component within public revenue and grants, keyed by scenario and time period.
        dsa_pub_nominal_gdp_local_currency: Typed data.DsaPubNominalGdpLocalCurrency series of nominal GDP in local currency, keyed by scenario and time period.
        leftover_exchange_rate_pa: Typed data.LeftoverExchangeRatePa series of period-average exchange rates used to convert local-currency GDP, keyed by scenario and time period.

    Returns:
        A data.DsaPubC2NaturalDisasterRevenue series containing natural disaster revenue, keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_sub(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_of_which_grants[scenario, time_period]), 100), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])))

    return data.DsaPubC2NaturalDisasterRevenue.collect(evaluate(formula, data.DSA_PUB_C2_NATURAL_DISASTER_REVENUE_REQUIRED))

@publish(key=('SCENARIO',), domain=None, cells=data.DSA_PUB_C3_COMMODITY_PRICES_PUB_DECLINE_IN_GDP_DEFLATOR_CELLS)
def dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator(*, c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10: float | str, c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10_2: float | str) -> float | str:
    """Compute the commodity-price GDP-deflator decline as the product of two authored factor series.

    Produces the C3_commodity_prices_pub GDP-deflator decline indicator by multiplying its two factor coordinates, yielding the published AA69 measure.

    Args:
        c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10: Historical commodity-price statistic series (workbook coordinate past_10) supplying the first GDP-deflator factor over catalog coordinates; passed through as a scalar when a scalar is given.
        c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10_2: Historical commodity-price statistic series (workbook coordinate past_10_2) supplying the second GDP-deflator factor over catalog coordinates; passed through as a scalar when a scalar is given.

    Returns:
        The measure-typed series resulting from multiplying the two factor inputs, or the `XlError` code string when the computation fails.
    """
    try:
        return as_measure(xl_mul(c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10, c3_commodity_pub_historical_statistics_key_historical_statistics_key_variables_past_10_2))
    except XlError as error:
        return error.code

@publish(data.INPUT4_DISCOUNT_RATE_SCHEMA, cells=data.INPUT4_DISCOUNT_RATE_CELLS)
def input4_discount_rate(*, discount_rate: float | str) -> data.Input4DiscountRate:
    """Resolve the external-instrument discount rate series for Input 4.

    Build the Input 4 discount-rate coordinate series, using the supplied rate for IMF rows and the IMF rate for all other external instruments.

    Args:
        discount_rate: Discount rate applied to each external instrument row, expressed as a scalar float or a string identifier.

    Returns:
        A data.Input4DiscountRate series giving the discount rate for each required external instrument coordinate, with the IMF entry taken from the supplied value and the remaining entries following the IMF rate.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'IMF':
            return as_measure(discount_rate)
        return as_measure(input4_discount_rate['IMF'])

    input4_discount_rate = CoordinateReader('input4_discount_rate', data.INPUT4_DISCOUNT_RATE_REQUIRED, formula)
    return data.Input4DiscountRate.collect((coord, input4_discount_rate[coord]) for coord in data.INPUT4_DISCOUNT_RATE_REQUIRED)

