@publish(data.INPUT5_PROJECTION_YEARS_SCHEMA, cells=data.INPUT5_PROJECTION_YEARS_CELLS)
def input5_projection_years(*, macro_debt_data: int | str) -> data.Input5ProjectionYears:
    """Compute the Input 5 projection-year axis by anchoring 2024 to macro debt data and deriving adjacent years recursively.

    Provide projection-year coordinates for Input 5 row 5, including the pre-projection year in H.

    Args:
        macro_debt_data: Scalar macro-debt data value (int or str) used as the 2024 projection-year anchor.

    Returns:
        A data.Input5ProjectionYears value collecting the computed projection-year series for Input 5 row 5, including the pre-projection year in H.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2023:
            return as_measure(xl_sub(input5_projection_years[time_period + 1], 1), 'int')
        elif time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(xl_add(input5_projection_years[time_period - 1], 1), 'int')

    input5_projection_years = CoordinateReader('input5_projection_years', data.INPUT5_PROJECTION_YEARS_REQUIRED, formula)
    return data.Input5ProjectionYears.collect((coord, input5_projection_years[coord]) for coord in data.INPUT5_PROJECTION_YEARS_REQUIRED)

