@publish(data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL_SCHEMA, cells=data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL_CELLS)
def input5_instrument_terms_instrument_label(*, translation_input_5_domestic_financing_locally_issued_debt: data.TranslationInput5DomesticFinancingLocallyIssuedDebt, translation_input_5_domestic_financing_central_bank_financing: data.TranslationInput5DomesticFinancingCentralBankFinancing, translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: data.TranslationInput5DomesticFinancingTBillsDenominatedInLocalCurrency, translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: data.TranslationInput5DomesticFinancingTBillsDenominatedInForeignCurrency, translation_input_5_domestic_financing_mlt_debt: data.TranslationInput5DomesticFinancingMltDebt, translation_input_5_domestic_financing_denominated_in_local_currency_lc: data.TranslationInput5DomesticFinancingDenominatedInLocalCurrencyLc, translation_input_5_domestic_financing_bonds_1_to_3_years_lc: data.TranslationInput5DomesticFinancingBonds1To3YearsLc, translation_input_5_domestic_financing_bonds_4_to_7_years_lc: data.TranslationInput5DomesticFinancingBonds4To7YearsLc, translation_input_5_domestic_financing_bonds_beyond_7_years_lc: data.TranslationInput5DomesticFinancingBondsBeyond7YearsLc, translation_input_5_domestic_financing_bonds_1_to_3_years_fx: data.TranslationInput5DomesticFinancingBonds1To3YearsFx, translation_input_5_domestic_financing_bonds_4_to_7_years_fx: data.TranslationInput5DomesticFinancingBonds4To7YearsFx, translation_input_5_domestic_financing_bonds_beyond_7_years_fx: data.TranslationInput5DomesticFinancingBondsBeyond7YearsFx, input5_definition_of_external_domestic_debt: str, external_domestic_debt_definition: str, start_debt_sustainability_analysis_m: int | str, lookup_afg_ap: str, lookup_hti: str, lookup_hnd: str, translation_st_debt: data.TranslationStDebt, lookup_afg: str) -> data.Input5InstrumentTermsInstrumentLabel:
    """Derive the Input 5 instrument-terms instrument-label output series from domestically issued and external debt translation labels.

    Resolve each instrument/holder coordinate of input5.instrument_terms to its display label, lifting the values from the matching translation series.

    Args:
        translation_input_5_domestic_financing_locally_issued_debt: Named-axis data.TranslationInput5DomesticFinancingLocallyIssuedDebt series over catalog coordinates supplying the English label for locally issued domestic financing debt.
        translation_input_5_domestic_financing_central_bank_financing: Named-axis data.TranslationInput5DomesticFinancingCentralBankFinancing series over catalog coordinates supplying the English label for central bank financing.
        translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: Named-axis data.TranslationInput5DomesticFinancingTBillsDenominatedInLocalCurrency series over catalog coordinates supplying the English label for T-bills denominated in local currency.
        translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: Named-axis data.TranslationInput5DomesticFinancingTBillsDenominatedInForeignCurrency series over catalog coordinates supplying the English label for T-bills denominated in foreign currency.
        translation_input_5_domestic_financing_mlt_debt: Named-axis data.TranslationInput5DomesticFinancingMltDebt series over catalog coordinates supplying the English label for medium- and long-term debt.
        translation_input_5_domestic_financing_denominated_in_local_currency_lc: Named-axis data.TranslationInput5DomesticFinancingDenominatedInLocalCurrencyLc series over catalog coordinates supplying the English label for debt denominated in local currency.
        translation_input_5_domestic_financing_bonds_1_to_3_years_lc: Named-axis data.TranslationInput5DomesticFinancingBonds1To3YearsLc series over catalog coordinates supplying the English label for local-currency bonds of 1 to 3 years.
        translation_input_5_domestic_financing_bonds_4_to_7_years_lc: Named-axis data.TranslationInput5DomesticFinancingBonds4To7YearsLc series over catalog coordinates supplying the English label for local-currency bonds of 4 to 7 years.
        translation_input_5_domestic_financing_bonds_beyond_7_years_lc: Named-axis data.TranslationInput5DomesticFinancingBondsBeyond7YearsLc series over catalog coordinates supplying the English label for local-currency bonds beyond 7 years.
        translation_input_5_domestic_financing_bonds_1_to_3_years_fx: Named-axis data.TranslationInput5DomesticFinancingBonds1To3YearsFx series over catalog coordinates supplying the English label for foreign-currency bonds of 1 to 3 years.
        translation_input_5_domestic_financing_bonds_4_to_7_years_fx: Named-axis data.TranslationInput5DomesticFinancingBonds4To7YearsFx series over catalog coordinates supplying the English label for foreign-currency bonds of 4 to 7 years.
        translation_input_5_domestic_financing_bonds_beyond_7_years_fx: Named-axis data.TranslationInput5DomesticFinancingBondsBeyond7YearsFx series over catalog coordinates supplying the English label for foreign-currency bonds beyond 7 years.
        input5_definition_of_external_domestic_debt: Scalar string holding the Input 5 external/domestic debt definition used to select among the FX label lookups.
        external_domestic_debt_definition: Scalar string holding the external/domestic debt definition compared against the input definition to choose the FX instrument label.
        start_debt_sustainability_analysis_m: Scalar integer or string giving the debt sustainability analysis start period that anchors the language and variant axis steps.
        lookup_afg_ap: Scalar string lookup returning the residents-held FX instrument label when the definitions match.
        lookup_hti: Scalar string lookup returning the alternative residents-held FX instrument label.
        lookup_hnd: Scalar string lookup returning the fallback residents-held FX instrument label.
        translation_st_debt: Named-axis data.TranslationStDebt series over catalog coordinates supplying the short-term debt instrument label for the maturity variant.
        lookup_afg: Scalar string lookup compared against the input definition to select between the external/domestic debt definition labels.

    Returns:
        data.Input5InstrumentTermsInstrumentLabel dataclass of series mapping each instrument and holder coordinate to its resolved display label, with residents falling back to the previously computed label when no translation applies.
    """
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_LOCALLY_ISSUED_DEBT_SCHEMA.validate(translation_input_5_domestic_financing_locally_issued_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_CENTRAL_BANK_FINANCING_SCHEMA.validate(translation_input_5_domestic_financing_central_bank_financing)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_LOCAL_CURRENCY_SCHEMA.validate(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_FOREIGN_CURRENCY_SCHEMA.validate(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_MLT_DEBT_SCHEMA.validate(translation_input_5_domestic_financing_mlt_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_DENOMINATED_IN_LOCAL_CURRENCY_LC_SCHEMA.validate(translation_input_5_domestic_financing_denominated_in_local_currency_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_LC_SCHEMA.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_LC_SCHEMA.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_LC_SCHEMA.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_FX_SCHEMA.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_FX_SCHEMA.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_FX_SCHEMA.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_fx)
    def formula(instrument: str, holder: str) -> str | None:
        if instrument == 'Locally-issued debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_locally_issued_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Held by residents' and holder == 'residents':
            return as_measure((lookup_afg_ap if xl_eq(external_domestic_debt_definition, lookup_afg) else ''), 'str')
        elif instrument == 'Central bank financing' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_central_bank_financing[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Short-term debt' and holder == 'residents':
            return as_measure(translation_st_debt[axis_step(data.VARIANT_AXIS_28, 'Maturity', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in local currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in foreign currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'MLT debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_mlt_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in local currency (LC)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_denominated_in_local_currency_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (1 to 3 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in foreign currency (FX)' and holder == 'residents':
            return as_measure((lookup_hti if xl_eq(input5_definition_of_external_domestic_debt, lookup_afg) else lookup_hnd), 'str')
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        return as_measure(input5_instrument_terms_instrument_label[instrument, 'residents'], 'str')

    input5_instrument_terms_instrument_label = CoordinateReader('input5_instrument_terms_instrument_label', data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL_REQUIRED, formula)
    return data.Input5InstrumentTermsInstrumentLabel.collect((coord, input5_instrument_terms_instrument_label[coord]) for coord in data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL_REQUIRED)

@publish(data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT_SCHEMA, cells=data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT_CELLS)
def input5_internal_interest_rate_on_domestic_debt(*, input5_interest_rate_on_domestic_debt: data.Input5InterestRateOnDomesticDebt) -> data.Input5InternalInterestRateOnDomesticDebt:
    """Compute internal interest rate on domestic debt.

    Derive the internal interest-rate-on-domestic-debt series from the input5 domestic-debt interest-rate series using authored coordinate identities.

    Args:
        input5_interest_rate_on_domestic_debt: Interest rate on domestic debt as a typed data series over instrument, holder, and time-period catalog coordinates.

    Returns:
        Internal interest rate on domestic debt as a typed data series over instrument, holder, and time-period catalog coordinates, following the authored identity rules.
    """
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT_SCHEMA.validate(input5_interest_rate_on_domestic_debt)
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if instrument == 'Central bank financing' and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX', 'Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])
        elif instrument == 'Central bank financing' and holder == 'residents' and time_period in (2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX', 'Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'non-residents' and time_period in (2024, 2025, 2026, 2027, 2028, 2029):
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, 'residents', time_period])
        return as_measure(input5_internal_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])

    input5_internal_interest_rate_on_domestic_debt = CoordinateReader('input5_internal_interest_rate_on_domestic_debt', data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT_REQUIRED, formula)
    return data.Input5InternalInterestRateOnDomesticDebt.collect((coord, input5_internal_interest_rate_on_domestic_debt[coord]) for coord in data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT_REQUIRED)

@publish(data.INPUT5_INTERNAL_GRACE_PERIOD_SCHEMA, cells=data.INPUT5_INTERNAL_GRACE_PERIOD_CELLS)
def input5_internal_grace_period(*, input5_grace_period: data.Input5GracePeriod) -> data.Input5InternalGracePeriod:
    """Build the internal grace-period series from Input 5 grace-period data.

    Reindexes Input 5 grace-period terms into the internal grace-period series consumed by downstream debt calculations.

    Args:
        input5_grace_period: Named-axis data.Input5GracePeriod series of grace-period terms for the six bond instruments (1 to 3 years, 4 to 7 years, and beyond 7 years, in FX and LC) across their holders.

    Returns:
        A data.Input5InternalGracePeriod series of internal grace-period values for the required instrument/holder coordinates.
    """
    data.INPUT5_GRACE_PERIOD_SCHEMA.validate(input5_grace_period)
    def formula(instrument: str, holder: str) -> float | str | None:
        return as_measure(input5_grace_period[instrument, 'residents'])

    return data.Input5InternalGracePeriod.collect(evaluate(formula, data.INPUT5_INTERNAL_GRACE_PERIOD_REQUIRED))

@publish(data.INPUT5_INTERNAL_MATURITY_SCHEMA, cells=data.INPUT5_INTERNAL_MATURITY_CELLS)
def input5_internal_maturity(*, input5_maturity: data.Input5Maturity) -> data.Input5InternalMaturity:
    """Extract internal maturity terms from Input 5 instrument data.

    Populate the LIC-DSF internal-maturity series from resident-holder maturity entries in Input 5 financing data.

    Args:
        input5_maturity: Typed data.Input5Maturity series over instrument and holder coordinates; supplies the resident-holder maturity term for each instrument.

    Returns:
        A data.Input5InternalMaturity series collected over the required internal-maturity coordinates, carrying the corresponding resident-holder maturity values from the input series.
    """
    data.INPUT5_MATURITY_SCHEMA.validate(input5_maturity)
    def formula(instrument: str, holder: str) -> float | str | None:
        return as_measure(input5_maturity[instrument, 'residents'])

    return data.Input5InternalMaturity.collect(evaluate(formula, data.INPUT5_INTERNAL_MATURITY_REQUIRED))

@publish(data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT_SCHEMA, cells=data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT_CELLS)
def input5_public_gfns_1_primary_deficit(*, macro_debt_public_sector_revenues_including_grants: data.MacroDebtPublicSectorRevenuesIncludingGrants, macro_debt_public_sector_primary_expenditure: data.MacroDebtPublicSectorPrimaryExpenditure) -> data.Input5PublicGfns1PrimaryDeficit:
    """Compute the Input 5 public-sector primary deficit by projection year.

    Derives the primary deficit from public-sector primary expenditure net of revenues including grants, as required by the LIC-DSF Input 5 financing block.

    Args:
        macro_debt_public_sector_revenues_including_grants: Typed data.MacroDebtPublicSectorRevenuesIncludingGrants series of public-sector revenues including grants by projection year.
        macro_debt_public_sector_primary_expenditure: Typed data.MacroDebtPublicSectorPrimaryExpenditure series of public-sector primary expenditure by projection year.

    Returns:
        A data.Input5PublicGfns1PrimaryDeficit series giving the primary deficit keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(macro_debt_public_sector_primary_expenditure[time_period], macro_debt_public_sector_revenues_including_grants[time_period]))

    return data.Input5PublicGfns1PrimaryDeficit.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT_REQUIRED))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_SCHEMA, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_CELLS)
def input5_public_gfns_2_debt_services_from_existing_debt(*, input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: data.Input5PublicGfns2DebtServicesFromExistingDebtDomesticIncludingStDebtFromPreviousYear, input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: data.Input5PublicGfns2DebtServicesFromExistingDebtExternalDebtMlt) -> data.Input5PublicGfns2DebtServicesFromExistingDebt:
    """Combine domestic (including previous-year short-term) and external MLT debt-service series into the Input 5 debt services from existing debt series.

    Populate Input 5 debt services from existing debt by summing the two component series across projection years.

    Args:
        input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: Domestic debt services from existing debt including short-term debt from the previous year, as a data series keyed by projection years.
        input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: External debt services from existing debt for medium- and long-term debt, as a data series keyed by projection years.

    Returns:
        A data.Input5PublicGfns2DebtServicesFromExistingDebt series containing the per-projection-year total debt services from existing debt.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year[time_period], input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt[time_period]))

    return data.Input5PublicGfns2DebtServicesFromExistingDebt.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_REQUIRED))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR_SCHEMA, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR_CELLS)
def input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year(*, input5_old_debt_debt_service_from_old_debt_residency_based: data.Input5OldDebtDebtServiceFromOldDebtResidencyBased) -> data.Input5PublicGfns2DebtServicesFromExistingDebtDomesticIncludingStDebtFromPreviousYear:
    """Compute Input 5 debt services from existing domestic debt, including short-term debt from the previous year.

    Map residency-based debt service from old debt into the Input 5 domestic debt-service series.

    Args:
        input5_old_debt_debt_service_from_old_debt_residency_based: Residency-based debt service from old debt, as a data.Input5OldDebtDebtServiceFromOldDebtResidencyBased series keyed by projection years.

    Returns:
        A data.Input5PublicGfns2DebtServicesFromExistingDebtDomesticIncludingStDebtFromPreviousYear series of debt services from existing debt / Domestic (including ST debt from the previous year) on Input 5, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(input5_old_debt_debt_service_from_old_debt_residency_based[time_period])

    return data.Input5PublicGfns2DebtServicesFromExistingDebtDomesticIncludingStDebtFromPreviousYear.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR_REQUIRED))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT_SCHEMA, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT_CELLS)
def input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Input5MacroNominalExchangeRateAverageLcuUsd, ext_debt_total_including_locally_issued: data.ExtDebtTotalIncludingLocallyIssued) -> data.Input5PublicGfns2DebtServicesFromExistingDebtExternalDebtMlt:
    """Compute Input 5 public GFNs debt services from existing external debt (MLT).

    Produces the Input 5 public GFNs debt-service series by applying the macro nominal exchange rate to external debt including locally issued debt.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Named-axis series of the Input 5 macro nominal exchange rate average in LCU per USD, aligned to projection years.
        ext_debt_total_including_locally_issued: Named-axis series of total external debt including locally issued debt, aligned to the same projection-year coordinates.

    Returns:
        data.Input5PublicGfns2DebtServicesFromExistingDebtExternalDebtMlt series containing debt services from existing debt / external debt (MLT) on Input 5, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_total_including_locally_issued[time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.Input5PublicGfns2DebtServicesFromExistingDebtExternalDebtMlt.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT_REQUIRED))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF_SCHEMA, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF_CELLS)
def input5_public_gfns_2_debt_services_from_existing_debt_ow_imf(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Input5MacroNominalExchangeRateAverageLcuUsd, ext_debt_old_mlt_debt_service: data.ExtDebtOldMltDebtService) -> data.Input5PublicGfns2DebtServicesFromExistingDebtOwImf:
    """Compute Input 5 public GFNS debt service from existing debt (o/w IMF).

    Translates the IMF coordinate of old MLT external debt service into local currency using the projected nominal average exchange rate.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Nominal average exchange rate series (LCU per USD) from Input 5 macro projections, keyed by projection year.
        ext_debt_old_mlt_debt_service: External debt old medium- and long-term debt service series, including the IMF creditor coordinate, keyed by projection year.

    Returns:
        Typed Input 5 series of public GFNS debt service from existing debt, IMF component, indexed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_old_mlt_debt_service['IMF', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.Input5PublicGfns2DebtServicesFromExistingDebtOwImf.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF_REQUIRED))

