    def pv_lc_output_stock_of_debt_in_lc_formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> float | str | None:
        if issuance_year == 2024 and time_period == 2024:
            return as_measure((pv_lc_output_new_borrowing_gross_in_local_currency[instrument, holder, 2024, time_period] if xl_eq(pv_lc_output_projection_year[instrument, holder, 2024, time_period], pv_lc_output_issuance_year[instrument, holder, 2024]) else xl_sub(pv_lc_labels_stock_of_debt_in_lc[instrument, holder], pv_lc_output_amortization_in_lc[instrument, holder, 2024, time_period])))
        elif issuance_year >= 2025 and time_period == 2024:
            return as_measure(0.0)
        elif issuance_year >= 2025 and time_period == 2025:
            return as_measure((pv_lc_output_new_borrowing_gross_in_local_currency[instrument, holder, issuance_year, time_period] if xl_eq(pv_lc_output_projection_year[instrument, holder, issuance_year, time_period], pv_lc_output_issuance_year[instrument, holder, issuance_year]) else xl_sub(pv_lc_output_stock_of_debt_in_lc[instrument, holder, issuance_year, time_period - 1], pv_lc_output_amortization_in_lc[instrument, holder, issuance_year, time_period])))
        elif issuance_year == 2025 and time_period >= 2026:
            return as_measure((pv_lc_output_new_borrowing_gross_in_local_currency[instrument, holder, 2025, time_period] if xl_eq(pv_lc_output_projection_year[instrument, holder, 2025, time_period], pv_lc_output_issuance_year[instrument, holder, 2025]) else xl_sub(pv_lc_output_stock_of_debt_in_lc[instrument, holder, 2025, time_period - 1], pv_lc_output_amortization_in_lc[instrument, holder, 2025, time_period])))
