    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(input5_new_issuance_locally_issued_debt['residents', time_period], input5_new_issuance_domestic_residual_financing_to_close_gap[time_period]) if xl_eq(input5_definition_of_external_domestic_debt, lookup_afg) else xl_add(xl_add(xl_add(input5_new_issuance['Central bank financing', 'residents', time_period], input5_new_issuance['T-bills (denominated in local currency)', 'residents', time_period]), input5_new_issuance_denominated_in_local_currency_lc['residents', time_period]), input5_new_issuance_domestic_residual_financing_to_close_gap[time_period])))

    return data.Input5DisbursementsTotalPublicNewDomesticDisbursementsResidencyBased.collect(evaluate(formula, data.INPUT5_DISBURSEMENTS_TOTAL_PUBLIC_NEW_DOMESTIC_DISBURSEMENTS_RESIDENCY_BASED_REQUIRED))

