@publish(data.INPUT5_SUMMARY_OUTSTANDING_STOCK_SCHEMA, cells=data.INPUT5_SUMMARY_OUTSTANDING_STOCK_CELLS)
def input5_summary_outstanding_stock(*, input5_old_debt_outstanding_of_old_debt_residency_based: data.Input5OldDebtOutstandingOfOldDebtResidencyBased, input5_new_debt_outstanding_of_new_debt_residency_based: data.Input5NewDebtOutstandingOfNewDebtResidencyBased) -> data.Input5SummaryOutstandingStock:
    """Sum residency-based old and new debt outstanding into the Input 5 summary outstanding stock.

    Combine the two residency-based outstanding-stock components into the Input 5 summary series used by the LIC-DSF template.

    Args:
        input5_old_debt_outstanding_of_old_debt_residency_based: Residency-based series of outstanding old debt on Input 5, keyed by projection years.
        input5_new_debt_outstanding_of_new_debt_residency_based: Residency-based series of outstanding new debt on Input 5, keyed by projection years.

    Returns:
        Input 5 summary outstanding stock, a data series keyed by projection years holding the elementwise sum of the new and old residency-based outstanding stock.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_new_debt_outstanding_of_new_debt_residency_based[time_period], input5_old_debt_outstanding_of_old_debt_residency_based[time_period]))

    return data.Input5SummaryOutstandingStock.collect(evaluate(formula, data.INPUT5_SUMMARY_OUTSTANDING_STOCK_REQUIRED))

@publish(data.INPUT5_SUMMARY_MLT_SCHEMA, cells=data.INPUT5_SUMMARY_MLT_CELLS)
def input5_summary_mlt(*, input5_summary_outstanding_stock: data.Input5SummaryOutstandingStock, input5_summary_short_term: data.Input5SummaryShortTerm) -> data.Input5SummaryMlt:
    """Compute the medium/long-term Input 5 summary by subtracting short-term debt from outstanding stock.

    Derive the residual medium/long-term debt series for the Input 5 projection surface.

    Args:
        input5_summary_outstanding_stock: Typed data series over catalog coordinates (projection years) holding Input 5 outstanding-stock summary values.
        input5_summary_short_term: Typed data series over catalog coordinates (projection years) holding Input 5 short-term summary values.

    Returns:
        Typed `data.Input5SummaryMlt` series keyed by projection years, where each value is the outstanding stock minus short-term debt for that period.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(input5_summary_outstanding_stock[time_period], input5_summary_short_term[time_period]))

    return data.Input5SummaryMlt.collect(evaluate(formula, data.INPUT5_SUMMARY_MLT_REQUIRED))

@publish(data.INPUT5_SUMMARY_SHORT_TERM_SCHEMA, cells=data.INPUT5_SUMMARY_SHORT_TERM_CELLS)
def input5_summary_short_term(*, input5_maturity: data.Input5Maturity, input5_new_issuance: data.Input5NewIssuance, input5_new_issuance_short_term_debt: data.Input5NewIssuanceShortTermDebt, input5_new_issuance_domestic_residual_financing_to_close_gap: data.Input5NewIssuanceDomesticResidualFinancingToCloseGap, input5_definition_of_external_domestic_debt: str, lookup_afg: str) -> data.Input5SummaryShortTerm:
    """Summarize Input 5 short-term new issuance by projection year.

    Compute the Input 5 short-term debt summary from maturity flags, new issuance, and residual domestic financing.

    Args:
        input5_maturity: Typed data.Input5Maturity series of Input 5 new-issuance maturity flags by instrument and residency.
        input5_new_issuance: Typed data.Input5NewIssuance series of Input 5 new-issuance amounts by instrument, residency, and projection year.
        input5_new_issuance_short_term_debt: Typed data.Input5NewIssuanceShortTermDebt series of Input 5 short-term debt new issuance by residency and projection year.
        input5_new_issuance_domestic_residual_financing_to_close_gap: Typed data.Input5NewIssuanceDomesticResidualFinancingToCloseGap series of residual domestic financing needed to close the gap, by projection year.
        input5_definition_of_external_domestic_debt: Scalar string external/domestic debt definition used to select the short-term financing formula.
        lookup_afg: Scalar string lookup label compared with the debt definition to choose the short-term financing formula.

    Returns:
        Typed data.Input5SummaryShortTerm series of short-term Input 5 financing, keyed by projection years.
    """
    data.INPUT5_MATURITY_SCHEMA.validate(input5_maturity)
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(xl_add((input5_new_issuance['Central bank financing', 'residents', time_period] if xl_eq(input5_maturity['Central bank financing', 'residents'], 1) else 0), input5_new_issuance_short_term_debt['residents', time_period]), input5_new_issuance_domestic_residual_financing_to_close_gap[time_period]) if xl_eq(input5_definition_of_external_domestic_debt, lookup_afg) else xl_add(xl_add((input5_new_issuance['Central bank financing', 'residents', time_period] if xl_eq(input5_maturity['Central bank financing', 'residents'], 1) else 0), input5_new_issuance['T-bills (denominated in local currency)', 'residents', time_period]), input5_new_issuance_domestic_residual_financing_to_close_gap[time_period])))

    return data.Input5SummaryShortTerm.collect(evaluate(formula, data.INPUT5_SUMMARY_SHORT_TERM_REQUIRED))

@publish(data.INPUT5_SUMMARY_INTEREST_PAYMENT_SCHEMA, cells=data.INPUT5_SUMMARY_INTEREST_PAYMENT_CELLS)
def input5_summary_interest_payment(*, input5_old_debt_interest_payment_on_old_debt_residency_based: data.Input5OldDebtInterestPaymentOnOldDebtResidencyBased, input5_new_debt_interest_payment_on_new_debt_residency_based: data.Input5NewDebtInterestPaymentOnNewDebtResidencyBased) -> data.Input5SummaryInterestPayment:
    """Combine the residency-based old-debt and new-debt interest payments into the Input 5 summary interest payment series.

    Aggregates the two residency-based interest payment components so the Input 5 summary reports total interest due in each projection year.

    Args:
        input5_old_debt_interest_payment_on_old_debt_residency_based: Residency-based interest payment on old debt, as a data.Input5OldDebtInterestPaymentOnOldDebtResidencyBased series keyed by projection year.
        input5_new_debt_interest_payment_on_new_debt_residency_based: Residency-based interest payment on new debt, as a data.Input5NewDebtInterestPaymentOnNewDebtResidencyBased series keyed by projection year.

    Returns:
        A data.Input5SummaryInterestPayment series keyed by projection year, holding the per-year sum of old- and new-debt residency-based interest payments, or None where the source values are unavailable.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_old_debt_interest_payment_on_old_debt_residency_based[time_period], input5_new_debt_interest_payment_on_new_debt_residency_based[time_period]))

    return data.Input5SummaryInterestPayment.collect(evaluate(formula, data.INPUT5_SUMMARY_INTEREST_PAYMENT_REQUIRED))

@publish(data.INPUT5_SUMMARY_PRINCIPAL_PAYMENT_SCHEMA, cells=data.INPUT5_SUMMARY_PRINCIPAL_PAYMENT_CELLS)
def input5_summary_principal_payment(*, input5_old_debt_principal_payment_on_old_debt_residency_based: data.Input5OldDebtPrincipalPaymentOnOldDebtResidencyBased, input5_new_debt_principal_payment_on_new_debt_residency_based: data.Input5NewDebtPrincipalPaymentOnNewDebtResidencyBased) -> data.Input5SummaryPrincipalPayment:
    """Combine residency-based old- and new-debt principal payments into the Input 5 principal-payment summary.

    Provides the total residency-based principal payment used in Input 5 summary reporting.

    Args:
        input5_old_debt_principal_payment_on_old_debt_residency_based: Residency-based principal payment series on old debt, keyed by projection years.
        input5_new_debt_principal_payment_on_new_debt_residency_based: Residency-based principal payment series on new debt, keyed by projection years.

    Returns:
        Input 5 summary principal-payment series keyed by projection years, summing old-debt and new-debt principal payments for each period.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_old_debt_principal_payment_on_old_debt_residency_based[time_period], input5_new_debt_principal_payment_on_new_debt_residency_based[time_period]))

    return data.Input5SummaryPrincipalPayment.collect(evaluate(formula, data.INPUT5_SUMMARY_PRINCIPAL_PAYMENT_REQUIRED))

