@publish(data.INPUT5_VINTAGE_INSTRUMENT_LABEL_SCHEMA, cells=data.INPUT5_VINTAGE_INSTRUMENT_LABEL_CELLS)
def input5_vintage_instrument_label(*, input5_instrument_titles: data.Input5InstrumentTitles) -> data.Input5VintageInstrumentLabel:
    """Lift vintage-specific instrument labels from current instrument titles across issuance years.

    Computes data.Input5VintageInstrumentLabel values for each instrument, resident holder, and issuance year by seeding 2024 from the provided instrument titles and carrying prior vintages forward.

    Args:
        input5_instrument_titles: A data.Input5InstrumentTitles series of instrument title strings for the six bond instruments (FX and LC variants across 1-3, 4-7, and beyond-7-year maturities) used as the source for the 2024 vintage labels.

    Returns:
        A data.Input5VintageInstrumentLabel series of instrument label strings or None, keyed by instrument, resident holder, and issuance year, where 2024 labels come from the supplied instrument titles and prior vintage labels are carried forward from the preceding issuance year.
    """
    def formula(instrument: str, holder: str, issuance_year: int) -> str | None:
        if issuance_year == 2024:
            return as_measure(input5_instrument_titles[instrument], 'str')
        return as_measure(input5_vintage_instrument_label[instrument, holder, issuance_year - 1], 'str')

    input5_vintage_instrument_label = CoordinateReader('input5_vintage_instrument_label', data.INPUT5_VINTAGE_INSTRUMENT_LABEL_REQUIRED, formula)
    return data.Input5VintageInstrumentLabel.collect((coord, input5_vintage_instrument_label[coord]) for coord in data.INPUT5_VINTAGE_INSTRUMENT_LABEL_REQUIRED)

@publish(data.A1_HIST_PUB_HISTORICAL_STATISTICS_SCHEMA, cells=data.A1_HIST_PUB_HISTORICAL_STATISTICS_CELLS)
def a1_hist_pub_historical_statistics(*, baseline_pub_inflation_rate_gdp_deflator_pct_al: float | str, baseline_pub_primary_deficit_by_indicator: data.BaselinePubPrimaryDeficitByIndicator, baseline_pub_real_gdp_growth_by_indicator: data.BaselinePubRealGdpGrowthByIndicator) -> data.A1HistPubHistoricalStatistics:
    """Compute historical averages and standard deviations for key public-debt variables over the past 10 years.

    Supports the A1 historical scenario in LIC-DSF public-debt stress testing by deriving baseline statistics from macro input series.

    Args:
        baseline_pub_inflation_rate_gdp_deflator_pct_al: GDP deflator percent inflation rate for the public baseline, supplied as a scalar float or string.
        baseline_pub_primary_deficit_by_indicator: Typed data series of the public baseline primary deficit by indicator, used to source the historical primary deficit measure.
        baseline_pub_real_gdp_growth_by_indicator: Typed data series of the public baseline real GDP growth by indicator, used to source the historical real GDP growth measure.

    Returns:
        A typed data.A1HistPubHistoricalStatistics dataclass of series containing the historical averages and standard deviations for the key public-debt variables.
    """
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit':
            return as_measure(baseline_pub_primary_deficit_by_indicator['Historical'])
        elif indicator == 'Real GDP growth (in percent)':
            return as_measure(baseline_pub_real_gdp_growth_by_indicator['Historical'])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct_al)

    return data.A1HistPubHistoricalStatistics.collect(evaluate(formula, data.A1_HIST_PUB_HISTORICAL_STATISTICS_REQUIRED))

@publish(key=(), domain=None, cells=data.BLEND_CALCULATED_BLEND_RATE_CELLS)
def blend_calculated_blend_rate(*, blend_ibrd_group_a_pricing: float | str, blend_sofr_selected_by_maturity: float | str) -> float | str:
    """Compute the uncapped blend floating rate from the selected SOFR swap and IBRD Group A pricing.

    Supports blend-rate construction by combining the maturity-selected SOFR swap with IBRD Group A pricing and subtracting the fixed 2.5% margin.

    Args:
        blend_ibrd_group_a_pricing: IBRD Group A pricing component for the blend, supplied as a scalar or an error-code string.
        blend_sofr_selected_by_maturity: SOFR swap rate selected by maturity for the blend, supplied as a scalar or an error-code string.

    Returns:
        The uncapped blend floating rate as a float, or an XlError code string if an input is not numeric.
    """
    try:
        return as_measure(xl_sub(xl_add(blend_sofr_selected_by_maturity, blend_ibrd_group_a_pricing), xl_div(2.5, 100)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_SOFR_SELECTED_BY_MATURITY_CELLS)
def blend_sofr_selected_by_maturity(*, blend_ida_new_floating_maturity: int | str, blend_interpolation_index: data.BlendInterpolationIndex, blend_sofr_interpolated_rate: data.BlendSofrInterpolatedRate) -> float | str:
    """Look up the interpolated SOFR swap rate matching the floating-loan maturity.

    Selects, from a blended SOFR rate grid, the interpolated rate cell identified by a floating-loan maturity index.

    Args:
        blend_ida_new_floating_maturity: Floating-loan maturity identifier (year count or maturity label) used as the lookup value into the interpolation index.
        blend_interpolation_index: Signed data.BlendInterpolationIndex series over catalog coordinates whose row axis is the time-period axis and whose cells hold maturity-index keys for the lookup.
        blend_sofr_interpolated_rate: Signed data.BlendSofrInterpolatedRate series over catalog coordinates whose row axis is the tenor axis and whose cells hold the interpolated swap rates returned for the matched maturity.

    Returns:
        Scalar interpolated SOFR swap rate for the selected maturity, or the Excel error code string when the lookup fails.
    """
    data.BLEND_INTERPOLATION_INDEX_SCHEMA.validate(blend_interpolation_index)
    _blend_sofr_selected_by_maturity_table_0 = view(blend_interpolation_index, rows=data.TIME_PERIOD_AXIS_3.keys)
    _blend_sofr_selected_by_maturity_table_1 = view(blend_sofr_interpolated_rate, rows=data.TENOR_AXIS_3.keys)
    try:
        return as_measure(xl_xlookup(blend_ida_new_floating_maturity, _blend_sofr_selected_by_maturity_table_0, _blend_sofr_selected_by_maturity_table_1))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_IDA_NEW_FLOATING_INTEREST_RATE_CELLS)
def blend_ida_new_floating_interest_rate(*, blend_calculated_blend_rate: float | str) -> float | str:
    """Blend floating interest rate after 0.75% floor and 5% ceiling.

    Constrain the calculated blend rate to the IDA floating-rate band before use.

    Args:
        blend_calculated_blend_rate: Scalar calculated blend rate to constrain, which may be a numeric rate or an error-code string.

    Returns:
        Scalar floating interest rate after the 0.75% floor and 5% ceiling, or an error-code string if the calculation propagates one.
    """
    try:
        return as_measure((xl_div(0.75, 100) if xl_le(blend_calculated_blend_rate, xl_div(0.75, 100)) else (xl_div(5, 100) if xl_ge(blend_calculated_blend_rate, xl_div(5, 100)) else blend_calculated_blend_rate)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_SELECTED_BASE_RATE_CELLS)
def blend_selected_base_rate(*, blend_ida_new_floating_currency: str, blend_reference_rate_currency: data.BlendReferenceRateCurrency, blend_reference_rate_name: data.BlendReferenceRateName) -> str:
    """Look up the blend reference base-rate name for a selected IDA new floating currency.

    Resolve which base-rate benchmark applies to the chosen currency via a catalog-coordinate lookup.

    Args:
        blend_ida_new_floating_currency: Scalar string identifying the IDA new floating currency used as the lookup key.
        blend_reference_rate_currency: Named-axis series of reference-rate currencies over catalog coordinates, validated against its schema and supplying the lookup column.
        blend_reference_rate_name: Named-axis series of reference-rate names over catalog coordinates, validated against its schema and supplying the lookup row axis.

    Returns:
        Scalar base-rate name (SOFR, EURIBOR, TONA, or SONIA) selected from the currency, or the Excel error code when the lookup fails.
    """
    data.BLEND_REFERENCE_RATE_CURRENCY_SCHEMA.validate(blend_reference_rate_currency)
    data.BLEND_REFERENCE_RATE_NAME_SCHEMA.validate(blend_reference_rate_name)
    _blend_selected_base_rate_table_0 = view(blend_reference_rate_currency, rows=data.VARIANT_AXIS_7.keys)
    _blend_selected_base_rate_table_1 = view(blend_reference_rate_name, rows=data.VARIANT_AXIS_7.keys)
    try:
        return as_measure(xl_xlookup(blend_ida_new_floating_currency, _blend_selected_base_rate_table_0, _blend_selected_base_rate_table_1), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_QUOTED_RATE_COLUMN_HEADER_CELLS)
def blend_quoted_rate_column_header(*, blend_selected_base_rate: str) -> str:
    """Return the quoted-rate column header for a selected base-rate name.

    Builds the column identifier used when a blended rate is quoted against a chosen base rate.

    Args:
        blend_selected_base_rate: Selected base-rate name string; appended with ' Swap rate' to form the column header.

    Returns:
        String column header resulting from concatenating the selected base-rate name with ' Swap rate', or the XlError code string if header construction fails.
    """
    try:
        return as_measure(xl_concat(blend_selected_base_rate, ' Swap rate'), 'str')
    except XlError as error:
        return error.code

@publish(data.BLEND_PUBLISHED_TENOR_YEARS_SCHEMA, cells=data.BLEND_PUBLISHED_TENOR_YEARS_CELLS)
def blend_published_tenor_years(*, blend_sofr_tenor_labels: data.BlendSofrTenorLabels) -> data.BlendPublishedTenorYears:
    """Parse published SOFR swap-curve tenor labels into numeric tenor years.

    Convert each published tenor label to the integer year count used by the blend calculation.

    Args:
        blend_sofr_tenor_labels: Keyword-only data.BlendSofrTenorLabels series of published SOFR swap-curve tenor labels; its values are left-parsed and numeric-coerced to yield tenor years.

    Returns:
        A data.BlendPublishedTenorYears series over catalog coordinates containing the numeric tenor years parsed from the published swap-curve labels in column J.
    """
    data.BLEND_SOFR_TENOR_LABELS_SCHEMA.validate(blend_sofr_tenor_labels)
    def formula(tenor: str) -> int | str | None:
        if tenor in ('1 Year', '2 Year', '3 Year', '4 Year', '5 Year'):
            return as_measure(xl_numbervalue(xl_left(blend_sofr_tenor_labels[tenor], 1)), 'int')
        return as_measure(xl_numbervalue(xl_left(blend_sofr_tenor_labels[tenor], 2)), 'int')

    return data.BlendPublishedTenorYears.collect(evaluate(formula, data.BLEND_PUBLISHED_TENOR_YEARS_REQUIRED))

@publish(data.BLEND_SOFR_QUOTED_RATE_SCHEMA, cells=data.BLEND_SOFR_QUOTED_RATE_CELLS)
def blend_sofr_quoted_rate(*, blend_interpolation_index: data.BlendInterpolationIndex, blend_sofr_swap_curve: data.BlendSofrSwapCurve, blend_published_tenor_years: data.BlendPublishedTenorYears) -> data.BlendSofrQuotedRate:
    """Map published SOFR swap rates onto the 1–30 year interpolation grid by coordinate lookup.

    Produce the blended quoted SOFR rate series by matching each interpolation-grid coordinate against the published tenor table and returning the corresponding swap rate.

    Args:
        blend_interpolation_index: Named-axis series of target coordinates on the 1–30 year interpolation grid, one entry per output tenor, used as the lookup key into the published tenor table.
        blend_sofr_swap_curve: Named-axis series of published SOFR swap rates keyed by swap tenor label, supplying the quoted values returned for each matched tenor.
        blend_published_tenor_years: Named-axis series of published swap tenor years keyed by tenor label; this forms the lookup array matched against the interpolation coordinates, with unpublished tenors left blank.

    Returns:
        Named-axis series of published SOFR swap rates aligned onto the 1–30 year interpolation grid, with blank (unpublished) years omitted.
    """
