@publish(data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_GDP_SCHEMA, cells=data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_GDP_CELLS)
def chart_chart_data_scenario_labels_pv_debt_to_gdp(*, start_debt_sustainability_analysis: str, translation_chart_data_growth: data.TranslationChartDataGrowth, translation_chart_data_exports: data.TranslationChartDataExports, translation_chart_data_non_debt_flows: data.TranslationChartDataNonDebtFlows, translation_chart_data_one_time_depreciation: data.TranslationChartDataOneTimeDepreciation, translation_chart_data_primary_balance: data.TranslationChartDataPrimaryBalance, translation_chart_data_combination: data.TranslationChartDataCombination, chart_tailored_test_names: data.ChartTailoredTestNames) -> data.ChartChartDataScenarioLabelsPvDebtToGdp:
    """Builds the translated scenario-label series for the PV of debt-to-GDP stress figure.

    Resolves each scenario row of the PV debt-to-GDP block to its localized display label, routing growth, primary-balance, exports, non-debt-flow, one-time-depreciation, and combination rows through the language-matched translation series and tailored-test rows through the tailored-test name series.

    Args:
        start_debt_sustainability_analysis: Scalar language selector (“English”, “French”, “Portuguese”, or “Spanish”) choosing which translation column supplies the chart labels; any other value falls back to Spanish.
        translation_chart_data_growth: Named-axis series of translated “Growth” scenario labels over the language coordinate.
        translation_chart_data_exports: Named-axis series of translated “Exports” scenario labels over the language coordinate.
        translation_chart_data_non_debt_flows: Named-axis series of translated “Non-debt flows” scenario labels over the language coordinate.
        translation_chart_data_one_time_depreciation: Named-axis series of translated “One-time depreciation” scenario labels over the language coordinate.
        translation_chart_data_primary_balance: Named-axis series of translated “Primary Balance” scenario labels over the language coordinate.
        translation_chart_data_combination: Named-axis series of translated “Combination” scenario labels over the language coordinate.
        chart_tailored_test_names: Named-axis series of tailored stress-test display names (Natural disaster, Commodity price, Market financing) over the tailored-test coordinate.

    Returns:
        A typed data.ChartChartDataScenarioLabelsPvDebtToGdp label series covering the required scenario rows of the PV of debt-to-GDP stress block (Chart Data!B40:B50, excluding the blank separator and the hardcoded C1 label), one localized label per row.
    """
    data.TRANSLATION_CHART_DATA_GROWTH_SCHEMA.validate(translation_chart_data_growth)
    data.TRANSLATION_CHART_DATA_EXPORTS_SCHEMA.validate(translation_chart_data_exports)
    data.TRANSLATION_CHART_DATA_NON_DEBT_FLOWS_SCHEMA.validate(translation_chart_data_non_debt_flows)
    data.TRANSLATION_CHART_DATA_ONE_TIME_DEPRECIATION_SCHEMA.validate(translation_chart_data_one_time_depreciation)
    data.TRANSLATION_CHART_DATA_PRIMARY_BALANCE_SCHEMA.validate(translation_chart_data_primary_balance)
    data.TRANSLATION_CHART_DATA_COMBINATION_SCHEMA.validate(translation_chart_data_combination)
    data.CHART_TAILORED_TEST_NAMES_SCHEMA.validate(chart_tailored_test_names)
    def formula(scenario: str) -> str | None:
        if scenario == 'Growth':
            return as_measure((translation_chart_data_growth['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_growth['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_growth['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_growth['Spanish']))), 'str')
        elif scenario == 'Primary Balance':
            return as_measure((translation_chart_data_primary_balance['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_primary_balance['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_primary_balance['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_primary_balance['Spanish']))), 'str')
        elif scenario == 'Exports':
            return as_measure((translation_chart_data_exports['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_exports['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_exports['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_exports['Spanish']))), 'str')
        elif scenario == 'Non-debt flows':
            return as_measure((translation_chart_data_non_debt_flows['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_non_debt_flows['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_non_debt_flows['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_non_debt_flows['Spanish']))), 'str')
        elif scenario == 'One-time depreciation':
            return as_measure((translation_chart_data_one_time_depreciation['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_one_time_depreciation['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_one_time_depreciation['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_one_time_depreciation['Spanish']))), 'str')
        elif scenario == 'Combination':
            return as_measure((translation_chart_data_combination['English'] if xl_eq(start_debt_sustainability_analysis, 'English') else (translation_chart_data_combination['French'] if xl_eq(start_debt_sustainability_analysis, 'French') else (translation_chart_data_combination['Portuguese'] if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else translation_chart_data_combination['Spanish']))), 'str')
        elif scenario == 'Natural disaster':
            return as_measure(chart_tailored_test_names['Natural disaster'], 'str')
        elif scenario == 'Commodity price':
            return as_measure(chart_tailored_test_names['Commodity price'], 'str')
        return as_measure(chart_tailored_test_names['Market financing'], 'str')

    return data.ChartChartDataScenarioLabelsPvDebtToGdp.collect(evaluate(formula, data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_GDP_REQUIRED))

@publish(data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_EXPORTS_SCHEMA, cells=data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_EXPORTS_CELLS)
def chart_chart_data_scenario_labels_pv_debt_to_exports(*, chart_combined_contingent_liabilities_label: str, chart_chart_data_scenario_labels_pv_debt_to_gdp: data.ChartChartDataScenarioLabelsPvDebtToGdp) -> data.ChartChartDataScenarioLabelsPvDebtToExports:
    """Translate the PV debt-to-exports scenario labels from the corresponding GDP-block labels.

    Resolve each stress-figure scenario label for the PV of debt-to-exports block, overriding the combined contingent liabilities entry with its dedicated text.

    Args:
        chart_combined_contingent_liabilities_label: Scalar label text applied to the combined contingent liabilities scenario.
        chart_chart_data_scenario_labels_pv_debt_to_gdp: Translated PV debt-to-GDP scenario label series, keyed by scenario, supplying the label for every other scenario.

    Returns:
        Typed scenario-label series for the PV of debt-to-exports stress-figure block (Chart Data!B82:B92, blank separator omitted).
    """
    def formula(scenario: str) -> str | None:
        if scenario == 'Combined contingent liabilities':
            return as_measure(chart_combined_contingent_liabilities_label, 'str')
        return as_measure(chart_chart_data_scenario_labels_pv_debt_to_gdp[scenario], 'str')

    return data.ChartChartDataScenarioLabelsPvDebtToExports.collect(evaluate(formula, data.CHART_CHART_DATA_SCENARIO_LABELS_PV_DEBT_TO_EXPORTS_REQUIRED))

