@publish(data.CHART_PROJECTION_YEARS_SCHEMA, cells=data.CHART_PROJECTION_YEARS_CELLS)
def chart_projection_years(*, macro_debt_main_assumptions_further_details: int | str, macro_debt_further_details: data.MacroDebtFurtherDetails) -> data.ChartProjectionYears:
    """Compute the Chart Data projection-year axis for Chart Data row 35.

    Derives the projection-year series by resolving 2024 from the main Macro-Debt further-details scalar and all other years from the typed MacroDebtFurtherDetails series.

    Args:
        macro_debt_main_assumptions_further_details: Scalar int or str main-assumptions further-details value used as the 2024 projection-year entry.
        macro_debt_further_details: Typed MacroDebtFurtherDetails series keyed by catalog time period; provides further-details projection-year values for all non-2024 years.

    Returns:
        Typed ChartProjectionYears series (Chart Data row 35 projection-year axis) produced by collecting the resolved per-year measures over the required chart projection years.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_main_assumptions_further_details, 'int')
        return as_measure(macro_debt_further_details[time_period], 'int')

    return data.ChartProjectionYears.collect(evaluate(formula, data.CHART_PROJECTION_YEARS_REQUIRED))

@dataclass(frozen=True, slots=True)
class ScanChartInternalChartDataPvDebtToGdpPvDebtGdpRatioStressPathResult:
    """Complete named results of one recurrence group evaluation."""
    chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path: data.ChartInternalChartDataPvDebtToGdpPvDebtGdpRatioStressPath
