@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH_SCHEMA, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH_CELLS)
def chart_internal_chart_data_pv_of_debt_to_gdp_ratio_pv_debt_to_gdp_stress_path(*, dsa_pub_pv_of_total_public_debt: data.DsaPubPvOfTotalPublicDebt) -> data.ChartInternalChartDataPvOfDebtToGdpRatioPvDebtToGdpStressPath:
    """Builds the PV of Debt-to-GDP Ratio stress-path chart series from the public-debt PV series.

    Maps each stress-path scenario label onto its corresponding public-debt PV scenario series so the chart's PV of Debt-to-GDP stress path is assembled over time periods.

    Args:
        dsa_pub_pv_of_total_public_debt: Public PV of total public debt by scenario, supplying the B2 market/non-market and B6 combination series read per time period.

    Returns:
        A data.ChartInternalChartDataPvOfDebtToGdpRatioPvDebtToGdpStressPath series of PV of Debt-to-GDP Ratio on Chart Data, keyed by scenario and stress_path.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B6_mkt', time_period])
        return as_measure(dsa_pub_pv_of_total_public_debt['B6_nonmkt', time_period])

    return data.ChartInternalChartDataPvOfDebtToGdpRatioPvDebtToGdpStressPath.collect(evaluate(formula, data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH_REQUIRED))

@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_SCHEMA, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_CELLS)
def chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue(*, chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue: data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue) -> data.ChartInternalChartDataPvOfDebtToRevenueRatioPvDebtToRevenue:
    """Compute internal chart data for the PV of Debt-to-Revenue ratio from chart output data.

    Derive the internal PV debt-to-revenue ratio chart series by applying authored coordinate identities to the provided chart output series.

    Args:
        chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue: A data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue series holding the PV of Debt-to-Revenue Ratio on Chart Data, keyed by scenario, used as the source chart output values for deriving the internal chart data series.

    Returns:
        A data.ChartInternalChartDataPvOfDebtToRevenueRatioPvDebtToRevenue series of internal PV of Debt-to-Revenue Ratio chart data, keyed by scenario, containing the derived values used by the chart output pipeline.
    """
    def formula(scenario: str, variant: str) -> float | str | None:
        if scenario == 'B1. Real GDP growth' and variant == '1st year breach - 2024':
            return as_measure(xl_rank(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], view(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue, rows=span(data.SCENARIO_AXIS_29, scenario, 'C4. Market Financing'), cols=('Number of breaches exc. 1st year - 2024',)), 0))
        elif scenario == 'C4. Market Financing' and variant == '1st year breach - 2024':
            return as_measure(xl_rank(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], view(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue, rows=span(data.SCENARIO_AXIS_29, 'B1. Real GDP growth', scenario), cols=('Number of breaches exc. 1st year - 2024',)), 0))
        elif scenario in ('B2. Primary balance', 'B3. Exports', 'B4. Other flows 3/', 'B5. Depreciation', 'B6. Combination of B1-B5', 'C1. Combined contingent liabilities', 'C2. Natural disaster', 'C3. Commodity price') and variant == '1st year breach - 2024':
            return as_measure(xl_rank(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], view(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue, rows=data.SCENARIO_AXIS_29.keys, cols=('Number of breaches exc. 1st year - 2024',)), 0))
        return as_measure(xl_max(view(chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue, rows=(scenario,), cols=span(data.TIME_PERIOD_AXIS_9, 2025, 2034))))

    chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue = CoordinateReader('chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue', data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_REQUIRED, formula)
    return data.ChartInternalChartDataPvOfDebtToRevenueRatioPvDebtToRevenue.collect((coord, chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[coord]) for coord in data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_REQUIRED)

@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH_SCHEMA, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH_CELLS)
def chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path(*, dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: data.DsaPubPvOfPublicDebtToRevenueAndGrantsRatio) -> data.ChartInternalChartDataPvOfDebtToRevenueRatioPvDebtToRevenueStressPath:
    """Compute Chart Data PV of debt-to-revenue ratio stress paths from public PV debt-to-revenue-and-grants ratios.

    Map public stress scenarios to the Chart Data series using authored coordinate identities for scenario and stress_path.

    Args:
        dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: data.DsaPubPvOfPublicDebtToRevenueAndGrantsRatio series of PV of public debt-to-revenue-and-grants ratios by scenario and time period, providing the B2 and B6 market and non-market source paths.

    Returns:
        data.ChartInternalChartDataPvOfDebtToRevenueRatioPvDebtToRevenueStressPath series of PV of Debt-to-Revenue Ratio on Chart Data, keyed by scenario and stress_path.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B6_mkt', time_period])
        return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B6_nonmkt', time_period])

