@publish(data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE_SCHEMA, cells=data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE_CELLS)
def chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space(*, fiscal_space_moderate_assessment_flag: int | str, fiscal_space_stock_band: data.FiscalSpaceStockBand, chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path: data.ChartInternalChartDataPvDebtToGdpPvDebtGdpRatioStressPath, chart_output_chart_data_figure_r61_pv_debt_gdp_ratio: data.ChartOutputChartDataFigureR61PvDebtGdpRatio) -> data.ChartInternalChartDataFiscalSpacePvDebtGdpModerateSpace:
    """Compute the internal fiscal-space PV-of-debt-to-GDP series for the moderate-risk assessment.

    Derive threshold-relative moderate-space classifications and stress-path values from assessment and stock-band inputs.

    Args:
        fiscal_space_moderate_assessment_flag: Scalar assessment flag; a value equal to 1 activates the moderate-space threshold calculations, otherwise threshold scenarios are blank.
        fiscal_space_stock_band: Typed data series of fiscal-space stock-band coefficients, providing the x and y percentages used to scale the PV-debt-to-GDP threshold.
        chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path: Typed stress-path data series of PV-of-debt-to-GDP ratios keyed by scenario and time period; supplies the baseline path when threshold scenarios are populated.
        chart_output_chart_data_figure_r61_pv_debt_gdp_ratio: Typed chart-output data series for the Figure R6.1 PV-of-debt-to-GDP ratio; supplies the threshold value aligned by time period.

    Returns:
        Typed data series of internal fiscal-space PV-debt-to-GDP moderate-space values, keyed by scenario and moderate-space coordinate, including threshold-scaled scenarios and the numeric moderate-space classification.
    """
    data.FISCAL_SPACE_STOCK_BAND_SCHEMA.validate(fiscal_space_stock_band)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == '(1-x)*Threshold':
            return as_measure((xl_mul(xl_sub(1, xl_div(fiscal_space_stock_band['x'], 100)), chart_output_chart_data_figure_r61_pv_debt_gdp_ratio['Threshold', time_period]) if xl_eq(fiscal_space_moderate_assessment_flag, 1) else ''))
        elif scenario == '(1-y)*Threshold':
            return as_measure((xl_mul(xl_sub(1, xl_div(fiscal_space_stock_band['y'], 100)), chart_output_chart_data_figure_r61_pv_debt_gdp_ratio['Threshold', time_period]) if xl_eq(fiscal_space_moderate_assessment_flag, 1) else ''))
        elif scenario == 'Baseline':
            return as_measure(('' if xl_eq(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-x)*Threshold', time_period], '') else chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path[scenario, time_period]))
        return as_measure(('' if xl_eq(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-y)*Threshold', time_period], '') else (0 if xl_le(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['Baseline', time_period], chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-y)*Threshold', time_period]) else (2 if xl_gt(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['Baseline', time_period], chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-x)*Threshold', time_period]) else 1))))

    chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space = CoordinateReader('chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space', data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE_REQUIRED, formula)
    return data.ChartInternalChartDataFiscalSpacePvDebtGdpModerateSpace.collect((coord, chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space[coord]) for coord in data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE_REQUIRED)

