@publish(data.EXT_DEBT_RESIDUAL_INTEREST_RATE_SCHEMA, cells=data.EXT_DEBT_RESIDUAL_INTEREST_RATE_CELLS)
def ext_debt_residual_interest_rate(*, input4_interest_rate: data.Input4InterestRate, input4_terms_ida_regular: data.Input4TermsIdaRegular, input4_terms_ida_and_lc: data.Input4TermsIdaAndLc, input4_terms_bonds_fx_non_residents: data.Input4TermsBondsFxNonResidents, input4_terms_bonds_fx_residents: data.Input4TermsBondsFxResidents, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal, ext_debt_new_disbursements_non_residents: data.ExtDebtNewDisbursementsNonResidents, ext_debt_new_disbursements_residents: data.ExtDebtNewDisbursementsResidents, ext_debt_new_disbursements_external_total: data.ExtDebtNewDisbursementsExternalTotal) -> data.ExtDebtResidualInterestRate:
    """Compute the average interest rate on new external debt.

    Derives the yearly residual-financing interest-rate term by weighting instrument-level rates with new disbursements and normalizing by total external disbursements.

    Args:
        input4_interest_rate: Input 4 interest-rate series over instrument coordinates, supplying rates for IMF, MULTI1/MULTI2, and other multi-currency or official-creditor instruments used in the weighted sum.
        input4_terms_ida_regular: IDA regular terms series over instrument coordinates, providing the interest rate for regular IDA borrowing.
        input4_terms_ida_and_lc: IDA and local-currency terms series over instrument coordinates, providing interest rates for IDA loan windows and local-currency bonds.
        input4_terms_bonds_fx_non_residents: FX bond terms for non-resident holders series over instrument and holder coordinates, providing interest rates for foreign-currency bonds held by non-residents.
        input4_terms_bonds_fx_residents: FX bond terms for resident holders series over instrument and holder coordinates, providing interest rates for foreign-currency bonds held by residents.
        ext_debt_new_disbursements_external: New external debt disbursements series by instrument and time period, used to weight rates for IMF, MULTI, and official-creditor instruments.
        ext_debt_new_disbursements_non_residents: New external debt disbursements to non-residents series by instrument and time period, used to weight local-currency and foreign-currency bond rates.
        ext_debt_new_disbursements_residents: New external debt disbursements to residents series by instrument and time period, used to weight resident-held foreign-currency bond rates.
        ext_debt_new_disbursements_external_total: Total new external debt disbursements series by time period, serving as the denominator in the weighted-average interest-rate calculation.

    Returns:
        data.ExtDebtResidualInterestRate series over time periods giving the average interest rate on new external debt in percent; blank when total new external disbursements are zero.
    """
    data.INPUT4_INTEREST_RATE_SCHEMA.validate(input4_interest_rate)
    _ext_debt_residual_interest_rate_table_0 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'))
    _ext_debt_residual_interest_rate_table_1 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'))
    _ext_debt_residual_interest_rate_table_2 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'))
    _ext_debt_residual_interest_rate_table_3 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'))
    _ext_debt_residual_interest_rate_table_4 = view(input4_terms_ida_and_lc, rows=span(data.INSTRUMENT_AXIS_12, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=('Interest rate',))
    _ext_debt_residual_interest_rate_table_5 = view(input4_terms_bonds_fx_non_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS.keys, 'INDICATOR': ('Interest rate',)})
    _ext_debt_residual_interest_rate_table_6 = view(input4_terms_bonds_fx_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS_2.keys, 'INDICATOR': ('Interest rate',)})
    def formula(time_period: int) -> float | str | None:
        return as_measure(('' if xl_eq(ext_debt_new_disbursements_external_total[time_period], 0) else xl_mul(xl_div(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_sumproduct((input4_interest_rate['IMF'], input4_terms_ida_regular['IDA - regular', 'Interest rate'], input4_terms_ida_and_lc['IDA - 50Y loans', 'Interest rate'], input4_terms_ida_and_lc['IDA - SML', 'Interest rate'], input4_terms_ida_and_lc['IDA NEW 40-year credits', 'Interest rate'], input4_terms_ida_and_lc['IDA NEW Regular', 'Interest rate'], input4_terms_ida_and_lc['IDA NEW Blend (also enter) -->', 'Interest rate'], input4_terms_ida_and_lc['IDA NEW 60-year credits', 'Interest rate'], input4_interest_rate['MULTI1'], input4_interest_rate['MULTI2']), view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'IMF', 'MULTI2'), cols=(time_period,))), xl_sumproduct(_ext_debt_residual_interest_rate_table_0, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_1, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Credit Agencies', 'PC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_2, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_3, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Eurobond', 'COM5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_4, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_5, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_interest_rate_table_6, view(ext_debt_new_disbursements_residents, rows=span(data.INSTRUMENT_AXIS_33, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), ext_debt_new_disbursements_external_total[time_period]), 100)))

    return data.ExtDebtResidualInterestRate.collect(evaluate(formula, data.EXT_DEBT_RESIDUAL_INTEREST_RATE_REQUIRED))

