@publish(data.EXT_DEBT_RESIDUAL_GRACE_PERIOD_SCHEMA, cells=data.EXT_DEBT_RESIDUAL_GRACE_PERIOD_CELLS)
def ext_debt_residual_grace_period(*, input4_grace_period: data.Input4GracePeriod, input4_terms_ida_regular: data.Input4TermsIdaRegular, input4_terms_ida_and_lc: data.Input4TermsIdaAndLc, input4_terms_bonds_fx_non_residents: data.Input4TermsBondsFxNonResidents, input4_terms_bonds_fx_residents: data.Input4TermsBondsFxResidents, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal, ext_debt_new_disbursements_non_residents: data.ExtDebtNewDisbursementsNonResidents, ext_debt_new_disbursements_residents: data.ExtDebtNewDisbursementsResidents, ext_debt_new_disbursements_external_total: data.ExtDebtNewDisbursementsExternalTotal) -> data.ExtDebtResidualGracePeriod:
    """Compute the yearly residual-financing average grace period on new external debt.

    Derive the disbursement-weighted average grace period on new external debt for residual financing from instrument-level terms and disbursements.

    Args:
        input4_grace_period: Grace-period assumptions by instrument, keyed by catalog instrument coordinates including IMF and MULTI entries.
        input4_terms_ida_regular: IDA-regular financing terms with grace-period values under the indicator axis.
        input4_terms_ida_and_lc: IDA and local-currency financing terms, keyed by instrument and indicator coordinates for grace-period lookups.
        input4_terms_bonds_fx_non_residents: Foreign-currency bond terms for non-resident holders, with grace-period values indexed by instrument, holder, and indicator coordinates.
        input4_terms_bonds_fx_residents: Foreign-currency bond terms for resident holders, with grace-period values indexed by instrument, holder, and indicator coordinates.
        ext_debt_new_disbursements_external: New external debt disbursements by instrument, aligned to projection time periods.
        ext_debt_new_disbursements_non_residents: New external debt disbursements to non-resident holders by instrument, aligned to projection time periods.
        ext_debt_new_disbursements_residents: New external debt disbursements to resident holders by instrument, aligned to projection time periods.
        ext_debt_new_disbursements_external_total: Total new external debt disbursements per period, serving as the denominator for the weighted average.

    Returns:
        A data.ExtDebtResidualGracePeriod named-axis series over projection years giving the average grace period on new debt for residual financing; periods with zero total new external disbursements are represented as an empty string measure.
    """
    data.INPUT4_GRACE_PERIOD_SCHEMA.validate(input4_grace_period)
    _ext_debt_residual_grace_period_table_0 = view(input4_grace_period, rows=span(data.INSTRUMENT_AXIS_2, 'OTH_MULTI1', 'OTH_MULTI3'))
    _ext_debt_residual_grace_period_table_1 = view(input4_grace_period, rows=span(data.INSTRUMENT_AXIS_2, 'Export Credit Agencies', 'PC5'))
    _ext_debt_residual_grace_period_table_2 = view(input4_grace_period, rows=span(data.INSTRUMENT_AXIS_2, 'Export Import Bank of NPC', 'NPC5'))
    _ext_debt_residual_grace_period_table_3 = view(input4_grace_period, rows=span(data.INSTRUMENT_AXIS_2, 'Eurobond', 'COM5'))
    _ext_debt_residual_grace_period_table_4 = view(input4_terms_ida_and_lc, rows=span(data.INSTRUMENT_AXIS_12, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=('Grace period',))
    _ext_debt_residual_grace_period_table_5 = view(input4_terms_bonds_fx_non_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS.keys, 'INDICATOR': ('Grace period',)})
    _ext_debt_residual_grace_period_table_6 = view(input4_terms_bonds_fx_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS_2.keys, 'INDICATOR': ('Grace period',)})
    def formula(time_period: int) -> float | str | None:
        return as_measure(('' if xl_eq(ext_debt_new_disbursements_external_total[time_period], 0) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_sumproduct((input4_grace_period['IMF'], input4_terms_ida_regular['IDA - regular', 'Grace period'], input4_terms_ida_and_lc['IDA - 50Y loans', 'Grace period'], input4_terms_ida_and_lc['IDA - SML', 'Grace period'], input4_terms_ida_and_lc['IDA NEW 40-year credits', 'Grace period'], input4_terms_ida_and_lc['IDA NEW Regular', 'Grace period'], input4_terms_ida_and_lc['IDA NEW Blend (also enter) -->', 'Grace period'], input4_terms_ida_and_lc['IDA NEW 60-year credits', 'Grace period'], input4_grace_period['MULTI1'], input4_grace_period['MULTI2']), view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'IMF', 'MULTI2'), cols=(time_period,))), xl_sumproduct(_ext_debt_residual_grace_period_table_0, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_1, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Credit Agencies', 'PC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_2, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_3, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Eurobond', 'COM5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_4, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_5, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_grace_period_table_6, view(ext_debt_new_disbursements_residents, rows=span(data.INSTRUMENT_AXIS_33, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), ext_debt_new_disbursements_external_total[time_period])))

    return data.ExtDebtResidualGracePeriod.collect(evaluate(formula, data.EXT_DEBT_RESIDUAL_GRACE_PERIOD_REQUIRED))

@publish(key=(), domain=None, cells=data.EXT_DEBT_RESIDUAL_GRACE_PERIOD_SUMMARY_CELLS)
def ext_debt_residual_grace_period_summary(*, ext_debt_residual_grace_period: data.ExtDebtResidualGracePeriod) -> float | str:
    """Compute the summary average external debt residual grace period on new debt.

    Derives a single summary value for the Average grace period on new debt from the external debt residual grace period series.

    Args:
        ext_debt_residual_grace_period: Typed external debt residual grace period series over catalog coordinates, used to compute the average grace period on new debt.

    Returns:
        A float average grace period on new debt, or an error-code string if the underlying spreadsheet average cannot be evaluated.
    """
    _ext_debt_residual_grace_period_summary_table_0 = view(ext_debt_residual_grace_period, cols=data.TIME_PERIOD_AXIS_25.keys)
    try:
        return as_measure(xl_average(_ext_debt_residual_grace_period_summary_table_0))
    except XlError as error:
        return error.code

@publish(data.EXT_DEBT_RESIDUAL_MATURITY_SCHEMA, cells=data.EXT_DEBT_RESIDUAL_MATURITY_CELLS)
def ext_debt_residual_maturity(*, input4_loan_maturity: data.Input4LoanMaturity, input4_terms_ida_regular: data.Input4TermsIdaRegular, input4_terms_ida_and_lc: data.Input4TermsIdaAndLc, input4_terms_bonds_fx_non_residents: data.Input4TermsBondsFxNonResidents, input4_terms_bonds_fx_residents: data.Input4TermsBondsFxResidents, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal, ext_debt_new_disbursements_non_residents: data.ExtDebtNewDisbursementsNonResidents, ext_debt_new_disbursements_residents: data.ExtDebtNewDisbursementsResidents, ext_debt_new_disbursements_external_total: data.ExtDebtNewDisbursementsExternalTotal) -> data.ExtDebtResidualMaturity:
    """Compute the residual-maturity term for external debt as a disbursement-weighted average of instrument-level loan maturities.

    Supplies the yearly average maturity of new external debt that drives the residual-financing term in the LIC-DSF external debt module.

    Args:
        input4_loan_maturity: Input 4 loan-maturity assumptions as a data.Input4LoanMaturity series over catalog instrument coordinates, giving maturity terms (in years) for IMF, multilateral, and other official creditors.
        input4_terms_ida_regular: Input 4 IDA regular-terms loan maturities as a data.Input4TermsIdaRegular series keyed by instrument.
        input4_terms_ida_and_lc: Input 4 IDA and local-currency loan and bond maturities as a data.Input4TermsIdaAndLc series over instrument coordinates.
        input4_terms_bonds_fx_non_residents: Input 4 FX bond loan-maturity terms for non-resident holders as a data.Input4TermsBondsFxNonResidents series over instrument and holder coordinates.
        input4_terms_bonds_fx_residents: Input 4 FX bond loan-maturity terms for resident holders as a data.Input4TermsBondsFxResidents series over instrument and holder coordinates.
        ext_debt_new_disbursements_external: New external disbursements by instrument as a data.ExtDebtNewDisbursementsExternal series over catalog instrument coordinates and projection periods.
        ext_debt_new_disbursements_non_residents: New external disbursements of FX bonds to non-residents as a data.ExtDebtNewDisbursementsNonResidents series over instrument coordinates and projection periods.
        ext_debt_new_disbursements_residents: New external disbursements of FX bonds to residents as a data.ExtDebtNewDisbursementsResidents series over instrument coordinates and projection periods.
        ext_debt_new_disbursements_external_total: Total new external disbursements per period as a data.ExtDebtNewDisbursementsExternalTotal series, used as the weighting denominator.

    Returns:
        A data.ExtDebtResidualMaturity series holding the yearly residual-financing term (average maturity of new external debt, in years) per projection period.
    """
    data.INPUT4_LOAN_MATURITY_SCHEMA.validate(input4_loan_maturity)
    _ext_debt_residual_maturity_table_0 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS_2, 'OTH_MULTI1', 'OTH_MULTI3'))
    _ext_debt_residual_maturity_table_1 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS_2, 'Export Credit Agencies', 'PC5'))
    _ext_debt_residual_maturity_table_2 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS_2, 'Export Import Bank of NPC', 'NPC5'))
    _ext_debt_residual_maturity_table_3 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS_2, 'Eurobond', 'COM5'))
    _ext_debt_residual_maturity_table_4 = view(input4_terms_ida_and_lc, rows=span(data.INSTRUMENT_AXIS_12, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=('Loan Maturity',))
    _ext_debt_residual_maturity_table_5 = view(input4_terms_bonds_fx_non_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS.keys, 'INDICATOR': ('Loan Maturity',)})
    _ext_debt_residual_maturity_table_6 = view(input4_terms_bonds_fx_residents, rows={'INSTRUMENT': data.INSTRUMENT_AXIS_10.keys}, cols={'HOLDER': data.HOLDER_AXIS_2.keys, 'INDICATOR': ('Loan Maturity',)})
    def formula(time_period: int) -> float | str | None:
        return as_measure(('' if xl_eq(ext_debt_new_disbursements_external_total[time_period], 0) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_sumproduct((input4_loan_maturity['IMF'], input4_terms_ida_regular['IDA - regular', 'Loan Maturity'], input4_terms_ida_and_lc['IDA - 50Y loans', 'Loan Maturity'], input4_terms_ida_and_lc['IDA - SML', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW 40-year credits', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW Regular', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW Blend (also enter) -->', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW 60-year credits', 'Loan Maturity'], input4_loan_maturity['MULTI1'], input4_loan_maturity['MULTI2']), view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'IMF', 'MULTI2'), cols=(time_period,))), xl_sumproduct(_ext_debt_residual_maturity_table_0, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_1, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Credit Agencies', 'PC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_2, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_3, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS_31, 'Eurobond', 'COM5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_4, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_5, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_32, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_6, view(ext_debt_new_disbursements_residents, rows=span(data.INSTRUMENT_AXIS_33, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), ext_debt_new_disbursements_external_total[time_period])))

    return data.ExtDebtResidualMaturity.collect(evaluate(formula, data.EXT_DEBT_RESIDUAL_MATURITY_REQUIRED))

@publish(key=(), domain=None, cells=data.EXT_DEBT_RESIDUAL_MATURITY_SUMMARY_CELLS)
def ext_debt_residual_maturity_summary(*, ext_debt_residual_maturity: data.ExtDebtResidualMaturity) -> float | str:
    """Compute the summary average of external debt residual maturity.

    Provide the Series average used in the LIC-DSF IDA21 template for the average maturity of new debt.

    Args:
        ext_debt_residual_maturity: A keyword-only named-axis tensor over catalog coordinates (data.ExtDebtResidualMaturity) holding external debt residual maturity observations for the average maturity of new debt.

    Returns:
        A float average of the provided series, or the Excel error code string if the averaging operation raises an XlError.
    """
    _ext_debt_residual_maturity_summary_table_0 = view(ext_debt_residual_maturity, cols=data.TIME_PERIOD_AXIS_25.keys)
    try:
        return as_measure(xl_average(_ext_debt_residual_maturity_summary_table_0))
    except XlError as error:
        return error.code

