@publish(data.IMPORTED_CLASSIFICATION_YEARS_SCHEMA, cells=data.IMPORTED_CLASSIFICATION_YEARS_CELLS)
def imported_classification_years(*, classification_cpia_reported_years: data.ClassificationCpiaReportedYears) -> data.ImportedClassificationYears:
    """Compute imported classification years from CPIA-reported classification-window years.

    Derive a catalog-aligned imported classification-year series anchored on the 2024 reported CPIA value and extended to adjacent years by one-year steps.

    Args:
        classification_cpia_reported_years: CPIA-reported classification-window years aligned to the projection vintage on row 37, as a data.ClassificationCpiaReportedYears named-axis series over catalog coordinates.

    Returns:
        The imported classification years as a data.ImportedClassificationYears named-axis series over catalog coordinates, with 2024 taken from the reported CPIA series and neighboring years shifted by one year.
    """
    data.CLASSIFICATION_CPIA_REPORTED_YEARS_SCHEMA.validate(classification_cpia_reported_years)
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(classification_cpia_reported_years[2024], 'int')
        elif time_period >= 2025:
            return as_measure(xl_add(imported_classification_years[time_period - 1], 1), 'int')
        return as_measure(xl_sub(imported_classification_years[time_period + 1], 1), 'int')

    imported_classification_years = CoordinateReader('imported_classification_years', data.IMPORTED_CLASSIFICATION_YEARS_REQUIRED, formula)
    return data.ImportedClassificationYears.collect((coord, imported_classification_years[coord]) for coord in data.IMPORTED_CLASSIFICATION_YEARS_REQUIRED)

