@publish(data.IMPORTED_CLASSIFICATION_IDS_SCHEMA, cells=data.IMPORTED_CLASSIFICATION_IDS_CELLS)
def imported_classification_ids(*, imported_series_stub_cpia: str, imported_series_stub_gr_a: str, imported_series_stub_res_a: str, imported_series_stub_wgr: str, imported_components: data.ImportedComponents) -> data.ImportedClassificationIds:
    """Build imported classification lookup IDs from prefix stubs and imported component series.

    Construct INDEX/MATCH classification keys for imported indicators.

    Args:
        imported_series_stub_cpia: Scalar string prefix for CPIA imported-classification lookup keys.
        imported_series_stub_gr_a: Scalar string prefix for real growth rate imported-classification lookup keys.
        imported_series_stub_res_a: Scalar string prefix for import coverage of reserves imported-classification lookup keys.
        imported_series_stub_wgr: Scalar string prefix for remaining imported-classification lookup keys (non-CPIA, non-real-growth, non-reserve-coverage indicators).
        imported_components: Typed data.ImportedComponents series over catalog coordinates; supplies the year-indexed component appended to each classification prefix.

    Returns:
        The evaluated data.ImportedClassificationIds collection/dataclass of typed series containing the constructed classification lookup keys (prefix plus year) used by INDEX/MATCH.
    """
    def formula(indicator: str, time_period: int) -> str | None:
        if indicator == 'CPIA':
            return as_measure(xl_concat(imported_series_stub_cpia, imported_components[time_period]), 'str')
        elif indicator == 'Real growth rate \n(in percent)':
            return as_measure(xl_concat(imported_series_stub_gr_a, imported_components[time_period]), 'str')
        elif indicator == 'Import coverage of reserves\n(in percent)':
            return as_measure(xl_concat(imported_series_stub_res_a, imported_components[time_period]), 'str')
        return as_measure(xl_concat(imported_series_stub_wgr, imported_components[time_period]), 'str')

    return data.ImportedClassificationIds.collect(evaluate(formula, data.IMPORTED_CLASSIFICATION_IDS_REQUIRED))

