@publish(data.IMPORTED_COMMODITY_IDS_SCHEMA, cells=data.IMPORTED_COMMODITY_IDS_CELLS)
def imported_commodity_ids(*, imported_commodity_names: data.ImportedCommodityNames, imported_of: float | str) -> data.ImportedCommodityIds:
    """Build imported commodity IDs by concatenating an as-of serial with imported commodity names.

    Produce lookup keys used to retrieve RES prices for imported commodities.

    Args:
        imported_commodity_names: Typed data series of imported commodity names over catalog coordinates.
        imported_of: Scalar as-of serial, either a float or string, concatenated with each commodity name.

    Returns:
        Typed data.ImportedCommodityIds series of concatenated as-of serial and commodity name keys, aligned to the commodity catalog.
    """
    data.IMPORTED_COMMODITY_NAMES_SCHEMA.validate(imported_commodity_names)
    def formula(commodity: str) -> str | None:
        return as_measure(xl_concat(imported_of, imported_commodity_names[commodity]), 'str')

    return data.ImportedCommodityIds.collect(evaluate(formula, data.IMPORTED_COMMODITY_IDS_REQUIRED))

