@publish(data.IN8_SDR_SDR_INTEREST_SCHEMA, cells=data.IN8_SDR_SDR_INTEREST_CELLS)
def in8_sdr_sdr_interest(*, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.In8SdrSdrAllocationHoldingsInMillionOfUsd, discount_rate: float | str, input8_sdr_interest_rate: data.Input8SdrInterestRate) -> data.In8SdrSdrInterest:
    """Compute SDR interest on Input 8 by issuance cohort and projection year.

    Derive the SDR interest series from allocation holdings, the SDR interest-rate schedule, and a discount rate, applying the template's cohort-specific timing and discounting rules.

    Args:
        in8_sdr_sdr_allocation_holdings_in_million_of_usd: SDR allocation holdings in millions of USD as a named-axis series over catalog coordinates, used to select the opening balance for each issuance-year cohort.
        discount_rate: Scalar discount rate used to add the discounted interest component in the applicable projection-year cases; accepts a numeric value or string literal.
        input8_sdr_interest_rate: SDR interest-rate schedule as a named-axis series over projection years, supplying the rate applied to each cohort's balance.

    Returns:
        SDR interest as a data.In8SdrSdrInterest named-axis series keyed by issuance year and projection year, with zero where the relevant prior holding is non-positive and accrued-plus-discounted amounts otherwise.
    """
    data.INPUT8_SDR_INTEREST_RATE_SCHEMA.validate(input8_sdr_interest_rate)
    def formula(issuance_year: int, time_period: int) -> int | str | None:
        if issuance_year == 2024 and time_period == 2025:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[issuance_year], input8_sdr_interest_rate[time_period]) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        elif issuance_year == 2024 and time_period == 2028:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 4], input8_sdr_interest_rate[time_period]) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        elif issuance_year == 2024 and time_period == 2029:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 5], input8_sdr_interest_rate[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 5], input8_sdr_interest_rate[time_period]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 5], 0) else 0), 'int')
        elif issuance_year == 2025 and time_period == 2029:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 4], input8_sdr_interest_rate[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 4], input8_sdr_interest_rate[time_period]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 4], 0) else 0), 'int')
        elif issuance_year == 2026 and time_period == 2029:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 3], input8_sdr_interest_rate[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 3], input8_sdr_interest_rate[time_period]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 3], 0) else 0), 'int')
        elif issuance_year == 2027 and time_period == 2029:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 2], input8_sdr_interest_rate[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 2], input8_sdr_interest_rate[time_period]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 2], 0) else 0), 'int')
        elif issuance_year == 2028 and time_period == 2029:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[2029]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[2029]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        elif issuance_year <= 2025 and 2027 <= time_period <= 2028 and time_period - issuance_year == 3:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 3], input8_sdr_interest_rate[time_period]) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        elif issuance_year <= 2026 and 2026 <= time_period <= 2028 and time_period - issuance_year == 2:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 2], input8_sdr_interest_rate[time_period]) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        elif 2025 <= issuance_year <= 2027 and 2026 <= time_period <= 2028 and time_period - issuance_year == 1:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[time_period]) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')
        return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], input8_sdr_interest_rate[time_period]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[time_period - 1], 0) else 0), 'int')

