@publish(key=(), domain=None, cells=data.IN8_SDR_OF_END_2044_CELLS)
def in8_sdr_of_end_2044(*, discount_rate: float | str, input8_sdr_interest_rate: data.Input8SdrInterestRate, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.In8SdrSdrAllocationHoldingsInMillionOfUsd) -> int | str:
    """Compute the Input 8 SDR interest income at end-2044.

    Derive the end-2044 SDR-related value from the allocation holdings and interest rate, discounted by the discount rate.

    Args:
        discount_rate: Scalar discount rate used to bring the end-2044 SDR interest income to present value; provided as a number or an error-code string.
        input8_sdr_interest_rate: Single-cell Input 8 SDR interest rate series anchored at end-2044.
        in8_sdr_sdr_allocation_holdings_in_million_of_usd: Single-cell Input 8 SDR allocation holdings, in millions of USD, anchored at end-2044.

    Returns:
        The computed end-2044 SDR value as an integer, or the XlError code string if the underlying formula raises an error.
    """
    data.INPUT8_SDR_INTEREST_RATE_SCHEMA.validate(input8_sdr_interest_rate)
    try:
        return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[2044], input8_sdr_interest_rate[2044]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[2044], input8_sdr_interest_rate[2044]), discount_rate)) if xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[2044], 0) else 0), 'int')
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_NOMINAL_GDP_SCHEMA, cells=data.C4_MKT_FIN_NOMINAL_GDP_CELLS)
def c4_mkt_fin_nominal_gdp(*, c4_market_path_nominal_gdp: float | str, c4_mkt_fin_gdp_deflator: data.C4MktFinGdpDeflator, c4_market_path_real_gdp_growth: data.C4MarketPathRealGdpGrowth) -> data.C4MktFinNominalGdp:
    """Compute nominal GDP under the market-financing stress path.

    Project nominal GDP by compounding the prior-year value with real GDP growth and GDP deflator for the C4 market scenario.

    Args:
        c4_market_path_nominal_gdp: Scalar nominal GDP level used as the base for the market-financing path in the first projection year.
        c4_mkt_fin_gdp_deflator: Market-financing GDP deflator series over catalog coordinates, providing annual deflator percentages.
        c4_market_path_real_gdp_growth: Real GDP growth series for the C4 market path over catalog coordinates, providing annual growth rates.

    Returns:
        Nominal GDP series under the market-financing stress path, as a data.C4MktFinNominalGdp instance indexed by catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(xl_mul(xl_mul(c4_market_path_nominal_gdp, xl_add(1, xl_div(c4_market_path_real_gdp_growth['C4_Market', time_period], 100))), xl_add(1, xl_div(c4_mkt_fin_gdp_deflator[time_period], 100))))
        return as_measure(xl_mul(xl_mul(c4_mkt_fin_nominal_gdp[time_period - 1], xl_add(1, xl_div(c4_market_path_real_gdp_growth['C4_Market', time_period], 100))), xl_add(1, xl_div(c4_mkt_fin_gdp_deflator[time_period], 100))))

    c4_mkt_fin_nominal_gdp = CoordinateReader('c4_mkt_fin_nominal_gdp', data.C4_MKT_FIN_NOMINAL_GDP_REQUIRED, formula)
    return data.C4MktFinNominalGdp.collect((coord, c4_mkt_fin_nominal_gdp[coord]) for coord in data.C4_MKT_FIN_NOMINAL_GDP_REQUIRED)

@publish(data.C4_MKT_FIN_GDP_DEFLATOR_SCHEMA, cells=data.C4_MKT_FIN_GDP_DEFLATOR_CELLS)
def c4_mkt_fin_gdp_deflator(*, dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: data.DsaExtGdpDeflatorInUsDollarTermsChangeInPercent, c4_mkt_fin_nc_depreciation: float | str, c4_mkt_fin_historical_flag: float | str, c4_market_path_non_interest_ca_pct_gdp: float | str) -> data.C4MktFinGdpDeflator:
    """Compute the GDP deflator series on the C4 market-financing path, overlaying the tailored FX shock in the first projection year when the historical-flag switch is enabled.

    Derive the C4 market-financing GDP deflator path used in the LIC-DSF template's external debt sustainability calculations.

    Args:
        dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: Baseline change in the GDP deflator in US dollar terms (percent) as a typed data series over catalog coordinates.
        c4_mkt_fin_nc_depreciation: Depreciation rate scalar (or string sentinel) applied on the C4 market-financing path.
        c4_mkt_fin_historical_flag: Historical-flag scalar (or string sentinel); when equal to one, the first projection year overlays the tailored FX shock.
        c4_market_path_non_interest_ca_pct_gdp: Non-interest current account balance as a percent of GDP on the market-financing path, as a scalar (or string sentinel).

    Returns:
        A typed data series over catalog coordinates containing the C4 market-financing GDP deflator path, with the first projection year adjusted for the tailored FX shock when the historical flag is active.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure((xl_add(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period], xl_mul(xl_sub(c4_market_path_non_interest_ca_pct_gdp, 1), c4_mkt_fin_nc_depreciation)) if xl_eq(c4_mkt_fin_historical_flag, 1) else dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period]))
        return as_measure(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period])

    return data.C4MktFinGdpDeflator.collect(evaluate(formula, data.C4_MKT_FIN_GDP_DEFLATOR_REQUIRED))

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_NC_DEPRECIATION_CELLS)
def c4_mkt_fin_nc_depreciation(*, c4_mkt_fin_i_macro_indicators: int | str, dsa_ext_depreciation_of_nc_depreciation: data.DsaExtDepreciationOfNcDepreciation) -> float | str:
    """Compute the C4 market-financing first-year nominal depreciation overlay.

    Return the first-year nominal depreciation overlay for the C4 shock from macro-indicator and external depreciation inputs.

    Args:
        c4_mkt_fin_i_macro_indicators: Macro-indicator scalar (integer or text code) used as the first-year nominal depreciation overlay value for the C4 shock.
        dsa_ext_depreciation_of_nc_depreciation: Typed data series of external depreciation of non-concessional debt over catalog coordinates, supplying the baseline depreciation schedule used by the C4 overlay.

    Returns:
        First-year nominal depreciation overlay as a float, or the XL error code string if the underlying calculation fails.
    """
    try:
        return as_measure(xl_add(xl_mul(dsa_ext_depreciation_of_nc_depreciation['Baseline', 2025], 0), c4_mkt_fin_i_macro_indicators))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_HISTORICAL_FLAG_CELLS)
def c4_mkt_fin_historical_flag(*, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal) -> float | str:
    """Compute the historical commercial external-debt disbursement flag for the LIC-DSF market-financing shock.

    Selects the historical versus standard shock parameterization by testing whether any commercial external new-disbursement flow is present over the 2024–2044 projection span.

    Args:
        ext_debt_new_disbursements_external: External new-disbursement series for the external debt perimeter; the Commercial row is sliced across the 2024–2044 time-period axis to determine whether historical market-financing shocks apply.

    Returns:
        Scalar flag as a float: 1 when the summed commercial disbursement slice is positive, otherwise 0; returns the workbook error code string if evaluation raises an XlError.
    """
    _c4_mkt_fin_historical_flag_table_0 = view(ext_debt_new_disbursements_external, rows=('Commercial',), cols=span(data.TIME_PERIOD_AXIS_39, 2024, 2044))
    try:
        return as_measure((1 if xl_gt(xl_sum(_c4_mkt_fin_historical_flag_table_0), 0) else 0))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_STRESSED_LENDING_TERMS_SCHEMA, cells=data.C4_MKT_FIN_STRESSED_LENDING_TERMS_CELLS)
def c4_mkt_fin_stressed_lending_terms(*, c4_market_instruments: data.C4MarketInstruments, c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row: data.C4MktFinNetNonDebtCreatingFlowsFdiGdpRatioByRow) -> data.C4MktFinStressedLendingTerms:
    """Compute stressed lending terms by commercial instrument.

    Derives the stressed maturity, grace period, and bullet/amortization flags applied to each commercial market instrument in the market-financing stress test.

    Args:
        c4_market_instruments: Typed market-instrument series over catalog coordinates giving each commercial instrument's observed terms; its 2023 and 2024 maturities drive the bullet/amortization flag, the grace-period cap, and the comparison against the five-year maturity threshold.
        c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row: Typed series of stress-shortening parameters for market financing, read by row label: the new maturity applied when original maturity exceeds five years, the maturity-shortening factor for shorter original maturities, and the grace-period shortening factor.

    Returns:
        A data.C4MktFinStressedLendingTerms series holding stressed maturity, grace, and bullet/amortization flags (with rounded variants) for every commercial instrument, indexed over the instrument and term-variant coordinates.
    """
    def formula(instrument: str, variant: str) -> float | str | None:
        if variant == 'Bullet (1) or Amort. (>1)':
            return as_measure((1 if xl_le(xl_sub(c4_market_instruments[instrument, 2024], c4_market_instruments[instrument, 2023]), 1) else 0))
        elif variant == 'Maturity':
            return as_measure((c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is greater than 5 years, new maturity is'] if xl_gt(c4_market_instruments[instrument, 2024], 5) else xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is less than 5 years, new maturity is shortened by'], c4_market_instruments[instrument, 2024])))
        elif variant == 'Grace':
            return as_measure((xl_sub(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 1) if xl_eq(c4_mkt_fin_stressed_lending_terms[instrument, 'Bullet (1) or Amort. (>1)'], 1) else xl_min(xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['Shortening of grace period, for 3 years: shortened by'], c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity']), c4_market_instruments[instrument, 2023])))
        elif variant == 'Maturity\n(rounded)':
            return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 0))
        return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Grace'], 0))

    c4_mkt_fin_stressed_lending_terms = CoordinateReader('c4_mkt_fin_stressed_lending_terms', data.C4_MKT_FIN_STRESSED_LENDING_TERMS_REQUIRED, formula)
    return data.C4MktFinStressedLendingTerms.collect((coord, c4_mkt_fin_stressed_lending_terms[coord]) for coord in data.C4_MKT_FIN_STRESSED_LENDING_TERMS_REQUIRED)

@publish(data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS_SCHEMA, cells=data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS_CELLS)
def c4_mkt_fin_average_residual_terms(*, c4_mkt_fin_stressed_lending_terms: data.C4MktFinStressedLendingTerms, c4_mkt_fin_total_commercial_borrowing_total: float | str, c4_mkt_fin_new_borrowing_total: data.C4MktFinNewBorrowingTotal) -> data.C4MktFinAverageResidualTerms:
    """Compute disbursement-weighted average maturity and grace for residual financing from stressed lending terms and new borrowing totals.

    Derive the average residual financing terms used in the LIC-DSF market-financing calculations.

    Args:
        c4_mkt_fin_stressed_lending_terms: Keyword-only data.C4MktFinStressedLendingTerms series of stressed lending terms by creditor and variant, supplying the maturity and grace values to be weighted.
        c4_mkt_fin_total_commercial_borrowing_total: Keyword-only scalar total commercial borrowing amount, typed as float or str, used as the denominator for the disbursement-weighted averages.
        c4_mkt_fin_new_borrowing_total: Keyword-only data.C4MktFinNewBorrowingTotal series of new borrowing amounts by creditor, supplying the disbursement weights.

    Returns:
        data.C4MktFinAverageResidualTerms typed result containing the disbursement-weighted average maturity and grace series for residual financing.
    """
    def formula(variant: str) -> float | str | None:
        if variant == 'Maturity\n(rounded)':
            return as_measure(xl_rounddown(c4_mkt_fin_average_residual_terms['Maturity'], 0))
        elif variant == 'Grace\n(rounded)':
            return as_measure(xl_rounddown(c4_mkt_fin_average_residual_terms['Grace'], 0))
        return as_measure((0 if xl_eq(c4_mkt_fin_total_commercial_borrowing_total, 0) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_mul(c4_mkt_fin_stressed_lending_terms['Eurobond', variant], c4_mkt_fin_new_borrowing_total['Eurobond']), xl_mul(c4_mkt_fin_stressed_lending_terms['Commecial Bank', variant], c4_mkt_fin_new_borrowing_total['Commecial Bank'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM3', variant], c4_mkt_fin_new_borrowing_total['COM3'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM4', variant], c4_mkt_fin_new_borrowing_total['COM4'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM5', variant], c4_mkt_fin_new_borrowing_total['COM5'])), c4_mkt_fin_total_commercial_borrowing_total)))

    c4_mkt_fin_average_residual_terms = CoordinateReader('c4_mkt_fin_average_residual_terms', data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS_REQUIRED, formula)
    return data.C4MktFinAverageResidualTerms.collect((coord, c4_mkt_fin_average_residual_terms[coord]) for coord in data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS_REQUIRED)

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_AVERAGE_RESIDUAL_INTEREST_CELLS)
def c4_mkt_fin_average_residual_interest(*, c4_mkt_fin_total_commercial_borrowing_total: float | str, c4_mkt_fin_new_borrowing_total: data.C4MktFinNewBorrowingTotal, c4_market_instruments_k: data.C4MarketInstrumentsK) -> float | str:
    """Compute the disbursement-weighted average interest rate on residual commercial financing across market instruments.

    Aggregate instrument-level interest rates weighted by new borrowing amounts and divide by total commercial borrowing to obtain the average residual interest rate.

    Args:
        c4_mkt_fin_total_commercial_borrowing_total: Scalar total commercial borrowing for the period; when it equals zero the weighted average is defined as zero, and a string error code is propagated.
        c4_mkt_fin_new_borrowing_total: Named-axis series of new borrowing amounts by market instrument, supplying the disbursement weights for the weighted average.
        c4_market_instruments_k: Named-axis series of interest rates by market instrument, aligned to the borrowing series on the same catalog coordinates.

    Returns:
        Scalar disbursement-weighted average interest rate for residual financing, or the string error code if the underlying arithmetic fails.
    """
    try:
        return as_measure((0 if xl_eq(c4_mkt_fin_total_commercial_borrowing_total, 0) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_mul(c4_market_instruments_k['Eurobond'], c4_mkt_fin_new_borrowing_total['Eurobond']), xl_mul(c4_market_instruments_k['Commecial Bank'], c4_mkt_fin_new_borrowing_total['Commecial Bank'])), xl_mul(c4_market_instruments_k['COM3'], c4_mkt_fin_new_borrowing_total['COM3'])), xl_mul(c4_market_instruments_k['COM4'], c4_mkt_fin_new_borrowing_total['COM4'])), xl_mul(c4_market_instruments_k['COM5'], c4_mkt_fin_new_borrowing_total['COM5'])), c4_mkt_fin_total_commercial_borrowing_total)))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING_SCHEMA, cells=data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING_CELLS)
def c4_mkt_fin_total_commercial_borrowing(*, c4_mkt_fin_new_borrowing: data.C4MktFinNewBorrowing) -> data.C4MktFinTotalCommercialBorrowing:
    """Aggregates new commercial borrowing disbursements into total commercial borrowing by summing across commercial instrument rows for each shock-year time period.

    Derives the total commercial borrowing series from the per-instrument new borrowing series so downstream market-financing calculations can use a single consolidated commercial disbursement measure.

    Args:
        c4_mkt_fin_new_borrowing: A typed data.C4MktFinNewBorrowing series of new commercial borrowing disbursements over catalog coordinates, indexed by commercial instrument and time period.

    Returns:
        A data.C4MktFinTotalCommercialBorrowing series giving total commercial borrowing, formed as the sum of commercial disbursements across shock years along the time-period axis.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sum(view(c4_mkt_fin_new_borrowing, rows=data.INSTRUMENT_AXIS_34.keys, cols=(time_period,))))

    return data.C4MktFinTotalCommercialBorrowing.collect(evaluate(formula, data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING_REQUIRED))

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING_TOTAL_CELLS)
def c4_mkt_fin_total_commercial_borrowing_total(*, c4_mkt_fin_total_commercial_borrowing: data.C4MktFinTotalCommercialBorrowing) -> float | str:
    """Compute total commercial borrowing across the shock-window time periods.

    Sum the commercial borrowing series into a single three-year total for the shock window.

    Args:
        c4_mkt_fin_total_commercial_borrowing: Named-axis data series of commercial borrowing amounts over catalog time periods; summed across the shock window.

    Returns:
        Three-year total of commercial disbursements in the shock window as a float, or a str error code if the underlying sum fails.
    """
    _c4_mkt_fin_total_commercial_borrowing_total_table_0 = view(c4_mkt_fin_total_commercial_borrowing, cols=data.TIME_PERIOD_AXIS_42.keys)
    try:
        return as_measure(xl_sum(_c4_mkt_fin_total_commercial_borrowing_total_table_0))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_NEW_BORROWING_SCHEMA, cells=data.C4_MKT_FIN_NEW_BORROWING_CELLS)
def c4_mkt_fin_new_borrowing(*, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal) -> data.C4MktFinNewBorrowing:
    """Compute the C4 market-financing new-borrowing series from external debt new disbursements.

    Reindexes external debt new disbursements onto the required instrument and time-period coordinates to yield market-financing new borrowing.

    Args:
        ext_debt_new_disbursements_external: Commercial disbursements in the shock years by instrument, as a named-axis series over catalog instrument and time-period coordinates.

    Returns:
        A data.C4MktFinNewBorrowing series of commercial disbursements in the shock years by instrument, collected over the required coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure(ext_debt_new_disbursements_external[instrument, time_period])

    return data.C4MktFinNewBorrowing.collect(evaluate(formula, data.C4_MKT_FIN_NEW_BORROWING_REQUIRED))

@publish(data.C4_MKT_FIN_NEW_BORROWING_TOTAL_SCHEMA, cells=data.C4_MKT_FIN_NEW_BORROWING_TOTAL_CELLS)
def c4_mkt_fin_new_borrowing_total(*, c4_mkt_fin_new_borrowing: data.C4MktFinNewBorrowing) -> data.C4MktFinNewBorrowingTotal:
    """Compute three-year total commercial new borrowing by instrument.

    Aggregate the input disbursement series across the time-period axis for each required instrument.

    Args:
        c4_mkt_fin_new_borrowing: Three-year commercial new borrowing disbursements by instrument and time period, represented as a data.C4MktFinNewBorrowing named-axis tensor over catalog coordinates.

    Returns:
        A data.C4MktFinNewBorrowingTotal series giving three-year total commercial disbursements by instrument.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(xl_sum(view(c4_mkt_fin_new_borrowing, rows=(instrument,), cols=data.TIME_PERIOD_AXIS_42.keys)))

    return data.C4MktFinNewBorrowingTotal.collect(evaluate(formula, data.C4_MKT_FIN_NEW_BORROWING_TOTAL_REQUIRED))

@publish(data.C4_MKT_FIN_GFN_INCREASE_SCHEMA, cells=data.C4_MKT_FIN_GFN_INCREASE_CELLS)
def c4_mkt_fin_gfn_increase(*, c4_market_path_total_debt_service: data.C4MarketPathTotalDebtService, c4_market_path_total_debt_service_alt: data.C4MarketPathTotalDebtServiceAlt) -> data.C4MktFinGfnIncrease:
    """Compute the per-period increase in external gross financing needs under the C4 market-financing stress test.

    Derive the GFN increase by differencing the alternative and baseline C4 market-path total debt service on the market-financing stress sheet.

    Args:
        c4_market_path_total_debt_service: Baseline `data.C4MarketPathTotalDebtService` series of total external debt service along the C4 market-financing path, a named-axis tensor over catalog coordinates (`TIME_PERIOD`, `INDICATOR`).
        c4_market_path_total_debt_service_alt: Alternative `data.C4MarketPathTotalDebtServiceAlt` series of total external debt service under the stressed C4 market-financing path, aligned to the same catalog coordinates.

    Returns:
        `data.C4MktFinGfnIncrease` series of the per-period increase (alternative minus baseline) in external gross financing needs, with float values per coordinate and strings or None where the underlying cells are blank or non-numeric.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(c4_market_path_total_debt_service_alt['C4_Market', time_period], c4_market_path_total_debt_service['C4_Market', time_period]))

    return data.C4MktFinGfnIncrease.collect(evaluate(formula, data.C4_MKT_FIN_GFN_INCREASE_REQUIRED))

@publish(data.C4_MKT_FIN_PV_RESIDUAL_FINANCING_SCHEMA, cells=data.C4_MKT_FIN_PV_RESIDUAL_FINANCING_CELLS)
def c4_mkt_fin_pv_residual_financing(*, pv_stress_pv_of_new_forex_debt: data.PvStressPvOfNewForexDebt) -> data.C4MktFinPvResidualFinancing:
    """Compute the C4 market-financing residual financing PV.

    Sum primary and secondary market-financing stress-test PVs of new forex debt to derive the residual financing requirement.

    Args:
        pv_stress_pv_of_new_forex_debt: Typed data.PvStressPvOfNewForexDebt series containing primary and secondary PV of new forex debt under the market-financing stress test over catalog coordinates.

    Returns:
        A data.C4MktFinPvResidualFinancing series giving PV of residual financing on the C4 market-financing stress sheet over catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period], pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period]))

    return data.C4MktFinPvResidualFinancing.collect(evaluate(formula, data.C4_MKT_FIN_PV_RESIDUAL_FINANCING_REQUIRED))

@publish(data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS_SCHEMA, cells=data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS_CELLS)
def c4_mkt_fin_pv_debt_adjustments(*, c4_mkt_fin_pv_residual_financing: data.C4MktFinPvResidualFinancing, c4_market_path_pv_of_debt: data.C4MarketPathPvOfDebt, c4_market_path_pv_of_debt_alt: data.C4MarketPathPvOfDebtAlt) -> data.C4MktFinPvDebtAdjustments:
    """Compute adjustments to the present value of debt on the C4 market-financing stress sheet.

    Combine residual financing and alternative PV of debt paths to derive the C4 market-financing PV debt adjustment series.

    Args:
        c4_mkt_fin_pv_residual_financing: Residual financing series used in the C4 market-financing PV debt adjustment calculation.
        c4_market_path_pv_of_debt: Baseline C4 market path of the present value of debt.
        c4_market_path_pv_of_debt_alt: Alternative C4 market path of the present value of debt.

    Returns:
        A C4 market-financing PV debt adjustments data series.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_sub(c4_market_path_pv_of_debt_alt['C4_Market', time_period], c4_market_path_pv_of_debt['C4_Market', time_period]), c4_mkt_fin_pv_residual_financing[time_period]))

    return data.C4MktFinPvDebtAdjustments.collect(evaluate(formula, data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS_REQUIRED))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT_SCHEMA, cells=data.C4_MKT_FIN_REVISED_PV_DEBT_CELLS)
def c4_mkt_fin_revised_pv_debt(*, c4_mkt_fin_pv_debt_adjustments: data.C4MktFinPvDebtAdjustments, c4_market_path_baseline_pv_of_debt: data.C4MarketPathBaselinePvOfDebt) -> data.C4MktFinRevisedPvDebt:
    """Compute the revised PV of debt on the C4 market-financing stress sheet.

    Combines the baseline market-path PV of debt with market-financing PV-of-debt adjustments, applying adjustments only after 2024.

    Args:
        c4_mkt_fin_pv_debt_adjustments: Keyword-only data.C4MktFinPvDebtAdjustments series of market-financing PV-of-debt adjustments indexed by catalog coordinates.
        c4_market_path_baseline_pv_of_debt: Keyword-only data.C4MarketPathBaselinePvOfDebt series of baseline market-path PV of debt indexed by catalog coordinates.

    Returns:
        data.C4MktFinRevisedPvDebt series containing the revised PV of debt indexed by catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], None))
        return as_measure(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], c4_mkt_fin_pv_debt_adjustments[time_period]))

    return data.C4MktFinRevisedPvDebt.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT_REQUIRED))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP_SCHEMA, cells=data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP_CELLS)
def c4_mkt_fin_revised_pv_debt_pct_gdp(*, c4_mkt_fin_revised_pv_debt: data.C4MktFinRevisedPvDebt, c4_market_path_nominal_gdp_stress: data.C4MarketPathNominalGdpStress) -> data.C4MktFinRevisedPvDebtPctGdp:
    """Compute revised PV of debt as a percent of GDP on the C4 market-financing stress sheet.

    Express the revised PV of debt relative to the stressed nominal GDP market path by scaling the ratio by 100.

    Args:
        c4_mkt_fin_revised_pv_debt: Revised PV of debt series over catalog coordinates on the C4 market-financing stress sheet.
        c4_market_path_nominal_gdp_stress: Stressed nominal GDP series over catalog coordinates supplying the market-path denominator for the ratio.

    Returns:
        Revised PV of debt as a percent of GDP, returned as a data.C4MktFinRevisedPvDebtPctGdp series over catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(c4_mkt_fin_revised_pv_debt[time_period], c4_market_path_nominal_gdp_stress['C4_Market', time_period]), 100))

    return data.C4MktFinRevisedPvDebtPctGdp.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP_REQUIRED))

@publish(data.C4_MKT_FIN_BASELINE_DEBT_SERVICE_SCHEMA, cells=data.C4_MKT_FIN_BASELINE_DEBT_SERVICE_CELLS)
def c4_mkt_fin_baseline_debt_service(*, macro_debt_ppg_interest_due: data.MacroDebtPpgInterestDue, macro_debt_main_assumptions_us_dollars_by_year_6: data.MacroDebtMainAssumptionsUsDollarsByYear6) -> data.C4MktFinBaselineDebtService:
    """Compute baseline debt service for the C4 market-financing stress sheet.

    Combines macro-debt PPG interest due with main macro-debt U.S. dollar assumptions to produce the C4 baseline debt-service path.

    Args:
        macro_debt_ppg_interest_due: Macro-debt PPG interest due, as a named-axis data series over catalog coordinates.
        macro_debt_main_assumptions_us_dollars_by_year_6: Main macro-debt assumptions in U.S. dollars by year 6, as a named-axis data series over catalog coordinates.

    Returns:
        A data.C4MktFinBaselineDebtService series containing the computed baseline debt-service values across the required projection periods.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]))

    return data.C4MktFinBaselineDebtService.collect(evaluate(formula, data.C4_MKT_FIN_BASELINE_DEBT_SERVICE_REQUIRED))

@publish(data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT_SCHEMA, cells=data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT_CELLS)
def c4_mkt_fin_debt_service_adjustment(*, c4_market_path_total_debt_service: data.C4MarketPathTotalDebtService, c4_market_path_total_debt_service_alt: data.C4MarketPathTotalDebtServiceAlt, pv_stress_total_debt_service: data.PvStressTotalDebtService) -> data.C4MktFinDebtServiceAdjustment:
    """Compute the C4 market-financing stress-sheet debt service adjustment.

    Derives the debt service adjustment from C4 market path totals and PV stress components.

    Args:
        c4_market_path_total_debt_service: Baseline C4 market-path total debt service series over projection periods.
        c4_market_path_total_debt_service_alt: Alternative C4 market-path total debt service series over projection periods.
        pv_stress_total_debt_service: PV stress total debt service series providing market-financing primary and secondary stress values.

    Returns:
        C4 market-financing debt service adjustment series collected over the required time periods.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_add(xl_add(xl_sub(None, None), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]))
        return as_measure(xl_add(xl_add(xl_sub(c4_market_path_total_debt_service_alt['C4_Market', time_period], c4_market_path_total_debt_service['C4_Market', time_period]), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]))

    return data.C4MktFinDebtServiceAdjustment.collect(evaluate(formula, data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT_REQUIRED))

@publish(data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE_SCHEMA, cells=data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE_CELLS)
def c4_mkt_fin_adjusted_debt_service(*, c4_mkt_fin_baseline_debt_service: data.C4MktFinBaselineDebtService, c4_mkt_fin_debt_service_adjustment: data.C4MktFinDebtServiceAdjustment) -> data.C4MktFinAdjustedDebtService:
    """Compute adjusted debt service for the C4 market-financing stress sheet.

    Sums the baseline debt service and the debt service adjustment over the projected time periods to produce the adjusted debt service series.

    Args:
        c4_mkt_fin_baseline_debt_service: Baseline debt service on the C4 market-financing stress sheet, as a data.C4MktFinBaselineDebtService time series over catalog coordinates.
        c4_mkt_fin_debt_service_adjustment: Debt service adjustment on the C4 market-financing stress sheet, as a data.C4MktFinDebtServiceAdjustment time series over catalog coordinates.

    Returns:
        A data.C4MktFinAdjustedDebtService series holding the adjusted debt service per time period.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(c4_mkt_fin_baseline_debt_service[time_period], c4_mkt_fin_debt_service_adjustment[time_period]))

    return data.C4MktFinAdjustedDebtService.collect(evaluate(formula, data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE_REQUIRED))

@publish(data.C4_MKT_FIN_REVENUE_EX_GRANTS_SCHEMA, cells=data.C4_MKT_FIN_REVENUE_EX_GRANTS_CELLS)
def c4_mkt_fin_revenue_ex_grants(*, dsa_ext_nominal_gdp_million_of_us_dollars: data.DsaExtNominalGdpMillionOfUsDollars, dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.DsaExtGovernmentRevenuesExcludingGrantsInPercentOfGdp) -> data.C4MktFinRevenueExGrants:
    """Compute C4 market-financing revenue excluding grants.

    Derive the C4 market-financing stress-sheet revenue measure from baseline GDP and government revenue shares.

    Args:
        dsa_ext_nominal_gdp_million_of_us_dollars: Baseline nominal GDP series in millions of US dollars, indexed by catalog coordinates.
        dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: Baseline government revenues excluding grants as a percent of GDP series, indexed by catalog coordinates.

    Returns:
        C4 market-financing revenue excluding grants as a typed data series over catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]))

    return data.C4MktFinRevenueExGrants.collect(evaluate(formula, data.C4_MKT_FIN_REVENUE_EX_GRANTS_REQUIRED))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS_SCHEMA, cells=data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS_CELLS)
def c4_mkt_fin_revised_pv_debt_to_exports(*, c4_mkt_fin_pv_debt_adjustments: data.C4MktFinPvDebtAdjustments, c4_market_path_baseline_pv_of_debt: data.C4MarketPathBaselinePvOfDebt, c4_market_path_exports: data.C4MarketPathExports) -> data.C4MktFinRevisedPvDebtToExports:
    """Revised PV of debt to exports under the C4 market-financing stress test.

    Compute the adjusted present-value-of-debt-to-exports ratio for the C4 market-financing stress scenario by adding PV-of-debt adjustments to baseline PV of debt and dividing by C4 Market path exports.

    Args:
        c4_mkt_fin_pv_debt_adjustments: data.C4MktFinPvDebtAdjustments series of PV-of-debt adjustment values over catalog coordinates, added to the baseline PV of debt on the C4 market-financing stress sheet.
        c4_market_path_baseline_pv_of_debt: data.C4MarketPathBaselinePvOfDebt series giving the baseline PV of debt along the C4 Market path over catalog coordinates.
        c4_market_path_exports: data.C4MarketPathExports series giving exports along the C4 Market path over catalog coordinates, used as the denominator.

    Returns:
        data.C4MktFinRevisedPvDebtToExports series of revised PV-of-debt-to-exports ratios (expressed per cent) over catalog coordinates on the C4 market-financing stress sheet.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], c4_mkt_fin_pv_debt_adjustments[time_period]), c4_market_path_exports['C4_Market', time_period]), 100))

    return data.C4MktFinRevisedPvDebtToExports.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS_REQUIRED))

@publish(data.C4_MKT_FIN_DSR_EXPORTS_STRESS_SCHEMA, cells=data.C4_MKT_FIN_DSR_EXPORTS_STRESS_CELLS)
def c4_mkt_fin_dsr_exports_stress(*, c4_mkt_fin_adjusted_debt_service: data.C4MktFinAdjustedDebtService, c4_market_path_exports: data.C4MarketPathExports) -> data.C4MktFinDsrExportsStress:
    """Compute the debt service-to-exports ratio under the C4 market-financing stress scenario.

    Derive stress-test debt service-to-exports ratios from adjusted debt service and market-path exports for the C4 market-financing stress sheet.

    Args:
        c4_mkt_fin_adjusted_debt_service: Adjusted debt service series over catalog time periods on the C4 market-financing basis.
        c4_market_path_exports: Exports series for the C4_Market scenario path, aligned to the same catalog time periods.

    Returns:
        A data.C4MktFinDsrExportsStress series of debt service-to-exports ratios expressed in percent, indexed by TIME_PERIOD over the required projection periods.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(c4_mkt_fin_adjusted_debt_service[time_period], c4_market_path_exports['C4_Market', time_period]), 100))

    return data.C4MktFinDsrExportsStress.collect(evaluate(formula, data.C4_MKT_FIN_DSR_EXPORTS_STRESS_REQUIRED))

@publish(data.C4_MKT_FIN_DSR_REVENUE_STRESS_SCHEMA, cells=data.C4_MKT_FIN_DSR_REVENUE_STRESS_CELLS)
def c4_mkt_fin_dsr_revenue_stress(*, c4_mkt_fin_adjusted_debt_service: data.C4MktFinAdjustedDebtService, c4_mkt_fin_revenue_ex_grants: data.C4MktFinRevenueExGrants) -> data.C4MktFinDsrRevenueStress:
    """Compute the stressed debt service-to-revenue ratio for the C4 market-financing stress test.

    Derive the percentage ratio by dividing C4 adjusted debt service by C4 revenue excluding grants across catalog time periods.

    Args:
        c4_mkt_fin_adjusted_debt_service: C4 market-financing adjusted debt service series, a named-axis tensor over catalog time periods.
        c4_mkt_fin_revenue_ex_grants: C4 market-financing revenue excluding grants series, a named-axis tensor over catalog time periods.

    Returns:
        C4 market-financing debt service-to-revenue stress series, a named-axis tensor over catalog time periods, expressed in percent.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(c4_mkt_fin_adjusted_debt_service[time_period], c4_mkt_fin_revenue_ex_grants[time_period]), 100))

    return data.C4MktFinDsrRevenueStress.collect(evaluate(formula, data.C4_MKT_FIN_DSR_REVENUE_STRESS_REQUIRED))

@publish(key=(), domain=None, cells=data.CI_SUMMARY_DEBT_CARRYING_CAPACITY_CELLS)
def ci_summary_debt_carrying_capacity(*, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: str, ci_summary_performance_policy: str, ci_summary_debt_carrying_capacity_vintage_reconciled: str) -> str:
    """Return the final debt-carrying-capacity classification used for applicable thresholds.

    Selects between the vintage-reconciled and performance-policy debt-carrying-capacity strings based on the IDA terms comparison.

    Args:
        lookup_ida_terms_new: Scalar string containing the IDA terms lookup value used as the comparison key for the standard-size threshold mode.
        input6_standard_size_threshold_mode: Scalar string for the standard-size threshold mode; when equal to the IDA terms lookup, it selects the vintage-reconciled result.
        ci_summary_performance_policy: Scalar string providing the performance-policy debt-carrying-capacity value used when the standard-size threshold mode does not match the IDA terms lookup.
        ci_summary_debt_carrying_capacity_vintage_reconciled: Scalar string providing the vintage-reconciled debt-carrying-capacity value used when the standard-size threshold mode matches the IDA terms lookup.

    Returns:
        String measure containing the final weak, medium, or strong debt-carrying-capacity classification, or an XlError code if evaluation fails.
    """
    try:
        return as_measure((ci_summary_debt_carrying_capacity_vintage_reconciled if xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new) else ci_summary_performance_policy), 'str')
    except XlError as error:
        return error.code

