@publish(key=(), domain=None, cells=data.CI_SUMMARY_CI_RATING_CELLS)
def ci_summary_ci_rating(*, ci_cutoff_weak: float | str, ci_cutoff_strong: float | str, ci_class_labels_cutoffs: data.CiClassLabelsCutoffs, ci_summary_ci_score: float | str) -> str:
    """Classify a CI summary score as weak, medium, or strong using cutoff values and label mapping.

    Compute the textual CI rating implied by the summary score's position relative to weak and strong cutoffs.

    Args:
        ci_cutoff_weak: Scalar weak-score cutoff; a summary score below this threshold selects the weak class.
        ci_cutoff_strong: Scalar strong-score cutoff; a summary score above this threshold selects the strong class.
        ci_class_labels_cutoffs: Named-axis label cutoffs series providing the Weak, Medium, and Strong output labels keyed by rating class.
        ci_summary_ci_score: Scalar CI summary score evaluated against the weak and strong cutoffs.

    Returns:
        String rating label from the class-label cutoffs series, or the XlError code if cutoff evaluation fails.
    """
    data.CI_CLASS_LABELS_CUTOFFS_SCHEMA.validate(ci_class_labels_cutoffs)
    try:
        return as_measure((ci_class_labels_cutoffs['Weak'] if xl_lt(ci_summary_ci_score, ci_cutoff_weak) else (ci_class_labels_cutoffs['Strong'] if xl_gt(ci_summary_ci_score, ci_cutoff_strong) else ci_class_labels_cutoffs['Medium'])), 'str')
    except XlError as error:
        return error.code

@publish(data.CI_SUMMARY_COMPONENTS_BY_YEAR_SCHEMA, cells=data.CI_SUMMARY_COMPONENTS_BY_YEAR_CELLS)
def ci_summary_components_by_year(*, ci_remittances_higher_cutoff: float | str, imported_classification_values: data.ImportedClassificationValues, ci_summary_gdp_us_dollars_billions: data.CiSummaryGdpUsDollarsBillions, ci_summary_remittances_gross_us_dollars_billions: data.CiSummaryRemittancesGrossUsDollarsBillions) -> data.CiSummaryComponentsByYear:
    """Compute per-year CI summary components from imported classifications and a capped remittances-to-GDP ratio.

    Assemble the ten-year CI component history aligned to Imported data.

    Args:
        ci_remittances_higher_cutoff: Scalar `float | str` cap applied to the computed remittances-to-GDP percentage; raw shares above it are clamped to the cutoff value.
        imported_classification_values: Typed `data.ImportedClassificationValues` series of classification values over catalog coordinates, returned unchanged for every indicator other than the remittances-in-percent row.
        ci_summary_gdp_us_dollars_billions: Typed `data.CiSummaryGdpUsDollarsBillions` series of GDP in billions of U.S. dollars over catalog coordinates, used as the denominator of the remittances share.
        ci_summary_remittances_gross_us_dollars_billions: Typed `data.CiSummaryRemittancesGrossUsDollarsBillions` series of gross remittances in billions of U.S. dollars over catalog coordinates, used as the numerator of the remittances share.

    Returns:
        Typed `data.CiSummaryComponentsByYear` series of CI summary components over catalog coordinates, with the remittances-in-percent row computed from the GDP and remittances series (capped by the cutoff) and all other rows taken from the imported classifications.
    """
    def formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'Remittances\n(in percent)':
            return as_measure((ci_remittances_higher_cutoff if xl_gt(xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100), ci_remittances_higher_cutoff) else xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100)))
        return as_measure(imported_classification_values[indicator, time_period])

    return data.CiSummaryComponentsByYear.collect(evaluate(formula, data.CI_SUMMARY_COMPONENTS_BY_YEAR_REQUIRED))

