@publish(data.CI_SUMMARY_PUBLIC_CAPACITY_CLASS_HEADERS_SCHEMA, cells=data.CI_SUMMARY_PUBLIC_CAPACITY_CLASS_HEADERS_CELLS)
def ci_summary_public_capacity_class_headers(*, ci_class_labels_thresholds: data.CiClassLabelsThresholds) -> data.CiSummaryPublicCapacityClassHeaders:
    """Build the public-capacity class column headers for the CI summary.

    Derives the Weak/Medium/Strong class headers shown on the public-benchmark display grid from validated class-label thresholds.

    Args:
        ci_class_labels_thresholds: A data.CiClassLabelsThresholds named-axis tensor over catalog coordinates whose entries supply the class-label thresholds; it is validated before being converted to string measures for header evaluation.

    Returns:
        The resolved data.CiSummaryPublicCapacityClassHeaders value containing the Weak/Medium/Strong public-capacity class column headers for the public-benchmark display grid.
    """
    data.CI_CLASS_LABELS_THRESHOLDS_SCHEMA.validate(ci_class_labels_thresholds)
    def formula(parameter: str) -> str | None:
        return as_measure(ci_class_labels_thresholds[parameter], 'str')

    return data.CiSummaryPublicCapacityClassHeaders.collect(evaluate(formula, data.CI_SUMMARY_PUBLIC_CAPACITY_CLASS_HEADERS_REQUIRED))

