@publish(data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS_SCHEMA, cells=data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS_CELLS)
def custom_pub_please_do_not_change_these_numbers(*, customized_public_template_anchor: float | str) -> data.CustomPubPleaseDoNotChangeTheseNumbers:
    """Builds the customized public scenario series of protected numeric anchors.

    Produces the Customized Scenario - public values keyed by projection years from row 7 without altering the authored template numbers.

    Args:
        customized_public_template_anchor: Base value for the first projection year, provided as a scalar float or string.

    Returns:
        A data.CustomPubPleaseDoNotChangeTheseNumbers series keyed by projection years, holding the customized public scenario values.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2025:
            return as_measure(xl_add(customized_public_template_anchor, 1), 'int')
        return as_measure(xl_add(custom_pub_please_do_not_change_these_numbers[time_period - 1], 1), 'int')

    custom_pub_please_do_not_change_these_numbers = CoordinateReader('custom_pub_please_do_not_change_these_numbers', data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS_REQUIRED, formula)
    return data.CustomPubPleaseDoNotChangeTheseNumbers.collect((coord, custom_pub_please_do_not_change_these_numbers[coord]) for coord in data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS_REQUIRED)

@publish(data.CUSTOM_PUB_REVENUE_GRANTS_SCHEMA, cells=data.CUSTOM_PUB_REVENUE_GRANTS_CELLS)
def custom_pub_revenue_grants(*, customized_public_delta: data.CustomizedPublicDelta, baseline_pub_revenue_grants: data.BaselinePubRevenueGrants) -> data.CustomPubRevenueGrants:
    """Compute customized public revenue and grants by adding customized public-scenario deltas to baseline public revenue and grants over projection years.

    Combine baseline public revenue and grants with customized public scenario adjustments to produce the customized-scenario public revenue and grants series.

    Args:
        customized_public_delta: Customized public-scenario delta series for revenue and grants, keyed by projection years from row 7, with scalar or blank cells treated as measures during addition.
        baseline_pub_revenue_grants: Baseline public revenue and grants series over the same projection-year coordinate, aligned for element-wise addition with the customized public-scenario deltas.

    Returns:
        Typed customized-scenario public revenue and grants series, keyed by projection years, with values preserving scalar, string, or blank measures.
    """
    data.CUSTOMIZED_PUBLIC_DELTA_SCHEMA.validate(customized_public_delta)
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(baseline_pub_revenue_grants[time_period], customized_public_delta['Revenue and grants', time_period]))

    return data.CustomPubRevenueGrants.collect(evaluate(formula, data.CUSTOM_PUB_REVENUE_GRANTS_REQUIRED))

