@publish(key=(), domain=None, cells=data.IN2_COVERAGE_Y3_SIZE_OF_PPP_SHOCK_PCT_GDP_1_2_CELLS)
def in2_coverage_y3_size_of_ppp_shock_pct_gdp_1_2(*, ppp_capital_stock_shock_pct: float | str, in2_coverage_y1_ppp_capital_stock_from_world_bank_s_ppp: float | str) -> float | str:
    """Compute the size of the PPP shock in percent of GDP.

    Multiplies the PPP capital-stock shock percentage by the year-1 World Bank PPP capital-stock baseline under Input 2 debt coverage.

    Args:
        ppp_capital_stock_shock_pct: Scalar percent shock applied to PPP capital stock.
        in2_coverage_y1_ppp_capital_stock_from_world_bank_s_ppp: Scalar year-1 PPP capital stock from the World Bank (PPP basis) under Input 2 debt coverage.

    Returns:
        Scalar size of the PPP shock as a percent of GDP, or the workbook error code as a string if the multiplication cannot be evaluated.
    """
    try:
        return as_measure(xl_mul(ppp_capital_stock_shock_pct, in2_coverage_y1_ppp_capital_stock_from_world_bank_s_ppp))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN3_MACRO_OUTSTANDING_CELLS)
def in3_macro_outstanding(*, external_domestic_debt_definition: str, input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: data.Input3Input3MacroNationalCurrencyPerUSDollarEOP, input3_domestic_outstanding_of_existing_debt: data.Input3DomesticOutstandingOfExistingDebt, lookup_afg: str) -> float | str:
    """Compute the Input 3 macro outstanding anchor for 2023.

    Resolve the single-cell domestic outstanding amount under the selected external/domestic debt definition, converting foreign-currency residents' debt when required.

    Args:
        external_domestic_debt_definition: Scalar debt-definition selector; when it matches the lookup selector, foreign-currency residents' outstanding is converted and added.
        input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: End-of-period national currency per U.S. dollar exchange-rate series over catalog coordinates; its 2023 value converts foreign-currency outstanding.
        input3_domestic_outstanding_of_existing_debt: Domestic outstanding of existing debt series over catalog coordinates, keyed by currency and residency; its 2023 local- and foreign-residents cells feed the anchor.
        lookup_afg: Scalar lookup selector compared against the debt definition to decide whether the conversion-and-add branch is used.

    Returns:
        Float-valued 2023 outstanding measure, or an Excel error code string if evaluation raises an XlError.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_E_O_P_SCHEMA.validate(input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p)
    data.INPUT3_DOMESTIC_OUTSTANDING_OF_EXISTING_DEBT_SCHEMA.validate(input3_domestic_outstanding_of_existing_debt)
    try:
        return as_measure((xl_add((input3_domestic_outstanding_of_existing_debt['local', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['local', 'residents', 2023]) else 0), xl_mul((input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023]) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[2023])) if xl_eq(external_domestic_debt_definition, lookup_afg) else (input3_domestic_outstanding_of_existing_debt['local', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['local', 'residents', 2023]) else 0)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN3_MACRO_O_W_MEDIUM_LONG_TERM_CELLS)
def in3_macro_o_w_medium_long_term(*, in3_macro_outstanding: float | str, in3_macro_o_w_st: data.In3MacroOWSt) -> float | str:
    """Compute the medium- and long-term overweight measure from outstanding macro debt and its 2023 anchor.

    Supply the Input 3 macro-debt helper that evaluates the authored identity for the medium/long-term overweight series.

    Args:
        in3_macro_outstanding: Scalar outstanding macro-debt amount, or an error-code string if the upstream workbook evaluation already failed.
        in3_macro_o_w_st: Single-cell `data.In3MacroOWSt` series anchor for the medium- and long-term overweight (Input 3 Macro-Debt data (DMX)), evaluated at the 2023 catalog coordinate.

    Returns:
        Scalar float measure equal to the outstanding amount minus the 2023 overweight anchor, or a string `XlError` code if the subtraction cannot be evaluated.
    """
    try:
        return as_measure(xl_sub(in3_macro_outstanding, in3_macro_o_w_st[2023]))
    except XlError as error:
        return error.code

@publish(data.IN3_MACRO_O_W_ST_SCHEMA, cells=data.IN3_MACRO_O_W_ST_CELLS)
def in3_macro_o_w_st(*, external_domestic_debt_definition: str, input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: data.Input3Input3MacroNationalCurrencyPerUSDollarEOP, input3_domestic_o_w_st: data.Input3DomesticOWSt, lookup_afg: str) -> data.In3MacroOWSt:
    """Derive the Input 3 short-term macro-debt (o/w) series keyed by projection year.

    Compute each projection year's short-term debt stock, converting foreign-currency residents' holdings to national currency when the selected debt definition calls for it, and otherwise reporting only local-currency residents' debt.

    Args:
        external_domestic_debt_definition: Scalar debt-definition code selecting which short-term debt aggregation applies; when it equals the lookup sentinel, foreign-currency residents' debt is converted to national currency and added to local-currency residents' debt.
        input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: Typed data series of Input 3 macro end-of-period national-currency-per-U.S.-dollar exchange rates, indexed by projection year and used to convert foreign-currency residents' balances.
        input3_domestic_o_w_st: Typed data series of Input 3 domestic short-term (o/w) debt by currency and residency, indexed by projection year; its local-residents and foreign-residents cells supply the base amounts.
        lookup_afg: Scalar lookup sentinel for the debt definition whose value triggers the conversion-and-sum branch rather than the local-residents-only branch.

    Returns:
        Typed data series of Input 3 macro short-term (o/w) debt keyed by projection year, holding the per-year computed debt stock.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_E_O_P_SCHEMA.validate(input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p)
    data.INPUT3_DOMESTIC_O_W_ST_SCHEMA.validate(input3_domestic_o_w_st)
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add((input3_domestic_o_w_st['local', 'residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['local', 'residents', time_period]) else 0), xl_mul((input3_domestic_o_w_st['foreign', 'residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['foreign', 'residents', time_period]) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[time_period])) if xl_eq(external_domestic_debt_definition, lookup_afg) else (input3_domestic_o_w_st['local', 'residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['local', 'residents', time_period]) else 0)))

    return data.In3MacroOWSt.collect(evaluate(formula, data.IN3_MACRO_O_W_ST_REQUIRED))

@publish(key=(), domain=None, cells=data.IN3_MACRO_TRANSITION_FORMULA_THESE_OUTSTANDING_CELLS)
def in3_macro_transition_formula_these_outstanding(*, external_domestic_debt_definition: str, input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: data.Input3Input3MacroNationalCurrencyPerUSDollarEOP, input3_domestic_outstanding_of_existing_debt: data.Input3DomesticOutstandingOfExistingDebt, lookup_afg: str) -> float | str:
    """Compute the 2023 macro transition formula for existing debt outstanding.

    Validate the Input 3 series schemas, choose the external/domestic branch via the definition lookup, and evaluate the anchored outstanding amount.

    Args:
        external_domestic_debt_definition: Scalar text selector for the external-versus-domestic debt definition, compared against a lookup constant to choose the calculation branch.
        input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: End-of-period national currency per U.S. dollar exchange-rate series over catalog coordinates, read at its 2023 anchor.
        input3_domestic_outstanding_of_existing_debt: Domestic outstanding of existing debt series over catalog coordinates, supplying local-non-resident, foreign-non-resident, and foreign-resident cells at the 2023 anchor.
        lookup_afg: Scalar text lookup value used as the equality target for the external/domestic debt definition selector.

    Returns:
        Scalar 2023 outstanding measure as a float, or the workbook error code string if evaluation fails.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_E_O_P_SCHEMA.validate(input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p)
    data.INPUT3_DOMESTIC_OUTSTANDING_OF_EXISTING_DEBT_SCHEMA.validate(input3_domestic_outstanding_of_existing_debt)
    try:
        return as_measure((xl_add(xl_div((input3_domestic_outstanding_of_existing_debt['local', 'non-residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['local', 'non-residents', 2023]) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[2023]), (input3_domestic_outstanding_of_existing_debt['foreign', 'non-residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['foreign', 'non-residents', 2023]) else 0)) if xl_eq(external_domestic_debt_definition, lookup_afg) else (input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023]) else 0)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN3_MACRO_TRANSITION_FORMULA_THESE_O_W_MEDIUM_LONG_TERM_CELLS)
def in3_macro_transition_formula_these_o_w_medium_long_term(*, in3_macro_transition_formula_these_outstanding: float | str, in3_macro_transition_formula_these_o_w_st: int | str) -> float | str:
    """Compute the medium- and long-term o/w difference for the Input 3 macro-debt transition formula.

    Subtract the medium- and long-term o/w anchor from the outstanding amount and wrap the result as a measure.

    Args:
        in3_macro_transition_formula_these_outstanding: Outstanding amount as a scalar on the Input 3 Macro-Debt data (DMX) workbook surface, supplied as a float or an Excel error code string.
        in3_macro_transition_formula_these_o_w_st: Single-cell anchor for the o/w medium- and long-term stock on the Input 3 Macro-Debt data (DMX) surface, supplied as an int or an Excel error code string.

    Returns:
        Scalar value of the outstanding amount minus the medium- and long-term o/w anchor, wrapped as a measure, or an Excel error code string when the subtraction raises an XlError.
    """
    try:
        return as_measure(xl_sub(in3_macro_transition_formula_these_outstanding, in3_macro_transition_formula_these_o_w_st))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN3_MACRO_TRANSITION_FORMULA_THESE_O_W_ST_CELLS)
def in3_macro_transition_formula_these_o_w_st(*, external_domestic_debt_definition: str, input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: data.Input3Input3MacroNationalCurrencyPerUSDollarEOP, input3_domestic_o_w_st: data.Input3DomesticOWSt, lookup_afg: str) -> int | str:
    """Compute the Input 3 domestic short-term-of-which macro transition formula using 2023 anchors.

    Select and evaluate the correct 2023 short-term debt expression from the external/domestic debt definition.

    Args:
        external_domestic_debt_definition: Scalar debt-definition label used to choose the transition branch; it is compared for equality with the lookup token.
        input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p: Typed Input 3 macro series of national currency per U.S. dollar end-of-period rates over catalog coordinates, supplying the 2023 exchange-rate anchor.
        input3_domestic_o_w_st: Typed Input 3 domestic of-which short-term debt series over catalog coordinates for local/foreign and residents/non-residents, supplying the 2023 local non-resident, foreign non-resident, and foreign resident anchor cells.
        lookup_afg: Scalar lookup label whose equality with the debt-definition selector selects the local/foreign non-resident branch.

    Returns:
        Selected transition result as an integer measure when evaluation succeeds, or the Excel error code string if evaluation raises XlError.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_E_O_P_SCHEMA.validate(input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p)
    data.INPUT3_DOMESTIC_O_W_ST_SCHEMA.validate(input3_domestic_o_w_st)
    try:
        return as_measure((xl_add(xl_div((input3_domestic_o_w_st['local', 'non-residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['local', 'non-residents', 2023]) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[2023]), (input3_domestic_o_w_st['foreign', 'non-residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['foreign', 'non-residents', 2023]) else 0)) if xl_eq(external_domestic_debt_definition, lookup_afg) else (input3_domestic_o_w_st['foreign', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_o_w_st['foreign', 'residents', 2023]) else 0)), 'int')
    except XlError as error:
        return error.code

@publish(data.IN3_MACRO_INTEREST_SCHEMA, cells=data.IN3_MACRO_INTEREST_CELLS)
def in3_macro_interest(*, external_domestic_debt_definition: str, input3_input_3_macro_national_currency_per_u_s_dollar_p_a: data.Input3Input3MacroNationalCurrencyPerUSDollarPA, input3_domestic_interest_payment_from_existing_debt: data.Input3DomesticInterestPaymentFromExistingDebt, lookup_afg: str) -> data.In3MacroInterest:
    """Compute Input 3 macro-debt interest from domestic interest payments and exchange rates.

    Derives the macro interest series for the LIC-DSF Input 3 debt block under the selected external/domestic debt definition.

    Args:
        external_domestic_debt_definition: Scalar string debt-definition selector; when it matches the lookup key, macro interest combines local non-resident and foreign non-resident interest components, otherwise it uses foreign resident interest.
        input3_input_3_macro_national_currency_per_u_s_dollar_p_a: Typed data series of macro national currency per U.S. dollar, period average, used to convert local-currency interest payments.
        input3_domestic_interest_payment_from_existing_debt: Typed data series of domestic interest payments from existing debt, with local/foreign and resident/non-resident components used to select payment amounts.
        lookup_afg: Scalar string lookup key compared against the debt-definition selector to determine which formula branch applies.

    Returns:
        Typed data.In3MacroInterest series containing Input 3 Macro-Debt interest, keyed by projection years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_P_A_SCHEMA.validate(input3_input_3_macro_national_currency_per_u_s_dollar_p_a)
    data.INPUT3_DOMESTIC_INTEREST_PAYMENT_FROM_EXISTING_DEBT_SCHEMA.validate(input3_domestic_interest_payment_from_existing_debt)
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(xl_div((input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period]) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_p_a[time_period]), (input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period]) else 0)) if xl_eq(external_domestic_debt_definition, lookup_afg) else (input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period] if xl_isnumber_lazy(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period]) else 0)))

    return data.In3MacroInterest.collect(evaluate(formula, data.IN3_MACRO_INTEREST_REQUIRED))

@publish(key=(), domain=None, cells=data.IN3_MACRO_FX_DENOMINATED_DEBT_INCLUDING_LOCALLY_ISSUED_CELLS)
def in3_macro_fx_denominated_debt_including_locally_issued(*, input3_input_3_external_debt_ppg_mlt_external_debt_outstanding: data.Input3Input3ExternalDebtPpgMltExternalDebtOutstanding, input3_input_3_external_debt_ppg_st_external_debt_outstanding: data.Input3Input3ExternalDebtPpgStExternalDebtOutstanding, input3_domestic_outstanding_of_existing_debt: data.Input3DomesticOutstandingOfExistingDebt) -> float | str:
    """Sum foreign-currency-denominated external and locally-issued debt outstanding as of 2023.

    Derive the single-cell Input 3 macro-debt anchor for FX-denominated debt, including locally issued instruments, for use by downstream external-debt calculations.

    Args:
        input3_input_3_external_debt_ppg_mlt_external_debt_outstanding: Single-cell anchor series of public and publicly guaranteed medium- and long-term external debt outstanding, valued at 2023.
        input3_input_3_external_debt_ppg_st_external_debt_outstanding: Single-cell anchor series of public and publicly guaranteed short-term external debt outstanding, valued at 2023.
        input3_domestic_outstanding_of_existing_debt: Domestic outstanding of existing debt series carrying a currency axis and a residency axis, from which the foreign-currency positions of residents and non-residents at 2023 are drawn.

    Returns:
        Scalar total of the 2023 outstanding amounts combined across the supplied series, or the XlError code string when any contributing value cannot be evaluated.
    """
    data.INPUT3_INPUT_3_EXTERNAL_DEBT_PPG_MLT_EXTERNAL_DEBT_OUTSTANDING_SCHEMA.validate(input3_input_3_external_debt_ppg_mlt_external_debt_outstanding)
    data.INPUT3_INPUT_3_EXTERNAL_DEBT_PPG_ST_EXTERNAL_DEBT_OUTSTANDING_SCHEMA.validate(input3_input_3_external_debt_ppg_st_external_debt_outstanding)
    data.INPUT3_DOMESTIC_OUTSTANDING_OF_EXISTING_DEBT_SCHEMA.validate(input3_domestic_outstanding_of_existing_debt)
    try:
        return as_measure(xl_add(xl_add(xl_add((input3_input_3_external_debt_ppg_mlt_external_debt_outstanding[2023] if xl_isnumber_lazy(lambda: input3_input_3_external_debt_ppg_mlt_external_debt_outstanding[2023]) else 0), (input3_input_3_external_debt_ppg_st_external_debt_outstanding[2023] if xl_isnumber_lazy(lambda: input3_input_3_external_debt_ppg_st_external_debt_outstanding[2023]) else 0)), (input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['foreign', 'residents', 2023]) else 0)), (input3_domestic_outstanding_of_existing_debt['foreign', 'non-residents', 2023] if xl_isnumber_lazy(lambda: input3_domestic_outstanding_of_existing_debt['foreign', 'non-residents', 2023]) else 0)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN6_TAILORED_NATDISASTER_CELLS)
def in6_tailored_natdisaster(*, trigger_natural_disaster_sample: data.TriggerNaturalDisasterSample, country: str) -> str:
    """Compute the Input 6 tailored natural-disaster applicability flag for a country.

    Return whether the given country is present in the tailored natural-disaster stress-test sample.

    Args:
        trigger_natural_disaster_sample: A data.TriggerNaturalDisasterSample named-axis tensor over catalog coordinates containing the workbook's tailored natural-disaster sample entries.
        country: A scalar country identifier string used to match against the natural-disaster sample entries.

    Returns:
        A scalar string, typically "Yes" when the country matches an applicable natural-disaster sample and "No" otherwise; an Excel error code string if evaluation fails.
    """
    data.TRIGGER_NATURAL_DISASTER_SAMPLE_SCHEMA.validate(trigger_natural_disaster_sample)
    _in6_tailored_natdisaster_table_0 = view(trigger_natural_disaster_sample, rows=data.REF_AREA_AXIS_7.keys)
    try:
        return as_measure(('Yes' if xl_gt((0 if xl_isna(lambda: xl_match(country, _in6_tailored_natdisaster_table_0, 0)) else xl_match(country, _in6_tailored_natdisaster_table_0, 0)), 0) else 'No'), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN6_TAILORED_COMMODITY_PRICE_CELLS)
def in6_tailored_commodity_price(*, input6_tailored_tests_enabled: str, in6_tailored_share_of_commodities_in_total_exports_of_goods: float | str) -> str:
    """Compute the Input 6 tailored commodity-price applicability flag.

    Derive a single-cell tailored-test anchor from tailored-tests enablement and the commodity export share.

    Args:
        input6_tailored_tests_enabled: Scalar string toggle for Input 6 tailored tests; the commodity test is considered only when this equals `'On'`.
        in6_tailored_share_of_commodities_in_total_exports_of_goods: Scalar numeric or numeric-string share of commodities in total exports of goods, compared against the 0.5 tailored-test threshold.

    Returns:
        A scalar string: `'Yes'` when tailored tests are enabled and the commodity export share exceeds 0.5, `'No'` otherwise, or the corresponding `XlError` code if evaluation fails.
    """
    try:
        return as_measure((('Yes' if xl_gt(in6_tailored_share_of_commodities_in_total_exports_of_goods, 0.5) else 'No') if xl_eq(input6_tailored_tests_enabled, 'On') else 'No'), 'str')
    except XlError as error:
        return error.code

