@publish(key=(), domain=None, cells=data.IN6_TAILORED_SHARE_OF_COMMODITIES_IN_TOTAL_EXPORTS_OF_GOODS_CELLS)
def in6_tailored_share_of_commodities_in_total_exports_of_goods(*, input6_tailored_params_2: data.Input6TailoredParams2) -> float | str:
    """Compute the Input 6 tailored share of commodities in total exports of goods and services.

    Aggregate fuel and non-fuel export share components from tailored test parameters into the single-cell commodity share anchor.

    Args:
        input6_tailored_params_2: data.Input6TailoredParams2 series providing the fuel and non-fuel export share components for the tailored Input 6 calculation; keyword-only.

    Returns:
        float | str – the summed commodity share as a scalar float, or an XlError code string when the underlying addition fails.
    """
    try:
        return as_measure(xl_add(input6_tailored_params_2['fuel_share_exports'], input6_tailored_params_2['nonfuel_share_exports']))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.IN6_TAILORED_ADJUSTED_SHARE_OF_COMMODITIES_IN_TOTAL_EXPORTS_CELLS)
def in6_tailored_adjusted_share_of_commodities_in_total_exports(*, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: data.In6TailoredAdjustedShareOfFuelInExportsOfGS, in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: data.In6TailoredAdjustedShareOfNonFuelInExportsOfGS) -> float | str:
    """Compute the tailored adjusted share of commodities in total exports by adding the adjusted fuel and non-fuel export shares.

    Sum the tailored adjusted fuel and non-fuel shares to obtain the adjusted share of commodities in total exports.

    Args:
        in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: Tailored adjusted share of fuel in exports of goods and services, as a data.In6TailoredAdjustedShareOfFuelInExportsOfGS series.
        in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: Tailored adjusted share of non-fuel in exports of goods and services, as a data.In6TailoredAdjustedShareOfNonFuelInExportsOfGS series.

    Returns:
        The sum of fuel and non-fuel tailored adjusted commodity export shares as a float, or an Excel error code string if the underlying calculation fails.
    """
    try:
        return as_measure(xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['User defined'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['User defined']))
    except XlError as error:
        return error.code

@dataclass(frozen=True, slots=True)
class ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult:
    """Complete named results of one recurrence group evaluation."""
    in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s: data.In6TailoredAdjustedShareOfFuelInExportsOfGS
    in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s: data.In6TailoredAdjustedShareOfNonFuelInExportsOfGS
    in6_tailored_average_of_prices_shock_default: float | str
    input6_tailored_params_2: data.Input6TailoredParams2

def scan_in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s(*, input6_tailored_tests_enabled: str, in6_tailored_price_shock_non_fuel: data.In6TailoredPriceShockNonFuel, in6_tailored_natdisaster_shock_size_default: float | str, in6_tailored_commodity_close_gap_default: float | str, in6_tailored_share_of_fuel_in_exports_of_g_s_default: float | str, in6_tailored_share_of_non_fuel_in_exports_of_g_s_default: float | str, in6_tailored_mitigating_factor_fuel_default: float | str, in6_tailored_mitigating_factor_non_fuel_default: float | str, in6_tailored_mkt_fin_borrowing_cost_default: float | str, in6_tailored_mkt_fin_maturity_defaults: data.In6TailoredMktFinMaturityDefaults, in6_tailored_mkt_fin_fx_depreciation_default: float | str, input6_tailored_params_fuel_label: str) -> ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult:
    """Evaluate the recurrence group `in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s`, `in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s`, `in6_tailored_average_of_prices_shock_default`, `input6_tailored_params_2` and publish complete tensors."""
    def in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure(xl_max(0, xl_sub(in6_tailored_share_of_fuel_in_exports_of_g_s_default, in6_tailored_mitigating_factor_fuel_default)))
        return as_measure(xl_max(0, xl_sub(input6_tailored_params_2['fuel_share_exports'], input6_tailored_params_2['fuel_price'])))

    in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s = CoordinateReader('in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s', data.IN6_TAILORED_ADJUSTED_SHARE_OF_FUEL_IN_EXPORTS_OF_G_S_REQUIRED, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s_formula)
    def in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s_formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure(xl_max(0, xl_sub(in6_tailored_share_of_non_fuel_in_exports_of_g_s_default, in6_tailored_mitigating_factor_non_fuel_default)))
        return as_measure(xl_max(0, xl_sub(input6_tailored_params_2['nonfuel_share_exports'], input6_tailored_params_2['nonfuel_price'])))

    in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s = CoordinateReader('in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s', data.IN6_TAILORED_ADJUSTED_SHARE_OF_NON_FUEL_IN_EXPORTS_OF_G_S_REQUIRED, in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s_formula)
    def in6_tailored_average_of_prices_shock_default_formula() -> float | str:
        return as_measure(((xl_div(xl_add(xl_mul(input6_tailored_params_fuel_label, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default']), xl_mul(in6_tailored_price_shock_non_fuel['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])), xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])) if xl_isnumber_lazy(lambda: xl_div(xl_add(xl_mul(input6_tailored_params_fuel_label, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default']), xl_mul(in6_tailored_price_shock_non_fuel['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default'])), xl_add(in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s['Default'], in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s['Default']))) else 0) if xl_eq(input6_tailored_tests_enabled, 'On') else 0))

    in6_tailored_average_of_prices_shock_default = CoordinateReader('in6_tailored_average_of_prices_shock_default', Domain.product(), in6_tailored_average_of_prices_shock_default_formula)
    def input6_tailored_params_2_formula(parameter: str) -> float | str | None:
        if parameter == 'mkt_ppg_debt_gdp_shock':
            return as_measure(in6_tailored_natdisaster_shock_size_default)
        elif parameter == 'commodity_export_gdp_gap_years':
            return as_measure(in6_tailored_commodity_close_gap_default)
        elif parameter == 'fuel_share_exports':
            return as_measure(in6_tailored_share_of_fuel_in_exports_of_g_s_default)
        elif parameter == 'nonfuel_share_exports':
            return as_measure(in6_tailored_share_of_non_fuel_in_exports_of_g_s_default)
        elif parameter == 'avg_price_shock':
            return as_measure(in6_tailored_average_of_prices_shock_default[()])
        elif parameter == 'fuel_price':
            return as_measure(in6_tailored_mitigating_factor_fuel_default)
        elif parameter == 'nonfuel_price':
            return as_measure(in6_tailored_mitigating_factor_non_fuel_default)
        elif parameter == 'mkt_financing_shock_on':
            return as_measure(in6_tailored_mkt_fin_borrowing_cost_default)
        elif parameter == 'new_maturity_if_gt_5y_1':
            return as_measure(in6_tailored_mkt_fin_maturity_defaults['If original maturity is greater than 5 years, new maturity is'])
        elif parameter == 'new_maturity_if_gt_5y_2':
            return as_measure(in6_tailored_mkt_fin_maturity_defaults['If original maturity is less than 5 years, new maturity is shortened by'])
        elif parameter == 'new_maturity_if_gt_5y_3':
            return as_measure(in6_tailored_mkt_fin_maturity_defaults['Shortening of grace period, for 3 years: shortened by'])
        return as_measure(in6_tailored_mkt_fin_fx_depreciation_default)

    input6_tailored_params_2 = CoordinateReader('input6_tailored_params_2', data.INPUT6_TAILORED_PARAMS_2_REQUIRED, input6_tailored_params_2_formula)
    return ScanIn6TailoredAdjustedShareOfFuelInExportsOfGSResult(
        in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s=data.In6TailoredAdjustedShareOfFuelInExportsOfGS.collect((coord, in6_tailored_adjusted_share_of_fuel_in_exports_of_g_s[coord]) for coord in data.IN6_TAILORED_ADJUSTED_SHARE_OF_FUEL_IN_EXPORTS_OF_G_S_REQUIRED),
        in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s=data.In6TailoredAdjustedShareOfNonFuelInExportsOfGS.collect((coord, in6_tailored_adjusted_share_of_non_fuel_in_exports_of_g_s[coord]) for coord in data.IN6_TAILORED_ADJUSTED_SHARE_OF_NON_FUEL_IN_EXPORTS_OF_G_S_REQUIRED),
        in6_tailored_average_of_prices_shock_default=in6_tailored_average_of_prices_shock_default[()],
        input6_tailored_params_2=data.Input6TailoredParams2.collect((coord, input6_tailored_params_2[coord]) for coord in data.INPUT6_TAILORED_PARAMS_2_REQUIRED),
    )

@publish(data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL_SCHEMA, cells=data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL_CELLS)
def in6_tailored_price_shock_non_fuel(*, in6_tailored_commodity_group_price_shock: data.In6TailoredCommodityGroupPriceShock) -> data.In6TailoredPriceShockNonFuel:
    """Derive the Input 6 non-fuel tailored price shock from tailored commodity-group price shocks.

    Resolve the non-fuel tailored price-shock series used by Input 6 tailored tests.

    Args:
        in6_tailored_commodity_group_price_shock: Keyword-only data.In6TailoredCommodityGroupPriceShock series of tailored commodity-group price shocks; evaluated across catalog variants and commodity coordinates to yield zero when all constituent shocks are blank or their average otherwise.

    Returns:
        data.In6TailoredPriceShockNonFuel series keyed by column labels from row 16.
    """
    def formula(variant: str) -> float | str | None:
        return as_measure((0 if xl_and(xl_eq(in6_tailored_commodity_group_price_shock['1) Base metal (e.g., iron, copper, nickel, bauxite, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['2) Precious metal (e.g., gold, silver, platinum, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['3) Grain (e.g., wheat, corn, soybeans, etc.)', variant], ''), xl_eq(in6_tailored_commodity_group_price_shock['4) Other agricultural commodities (e.g., coffee, cocoa, tea, etc.)', variant], '')) else xl_average(view(in6_tailored_commodity_group_price_shock, rows=data.COMMODITY_AXIS_2.keys, cols=(variant,)))))

    return data.In6TailoredPriceShockNonFuel.collect(evaluate(formula, data.IN6_TAILORED_PRICE_SHOCK_NON_FUEL_REQUIRED))

@publish(data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK_SCHEMA, cells=data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK_CELLS)
def in6_tailored_commodity_group_price_shock(*, input6_commodity_group_relevant: data.Input6CommodityGroupRelevant, imported_commodity_prices: data.ImportedCommodityPrices) -> data.In6TailoredCommodityGroupPriceShock:
    """Compute tailored non-fuel commodity-group price shocks from Input 6 relevance flags and imported commodity price changes.

    Populate the tailored commodity-group price-shock series used by the IDA21 LIC-DSF stress-test workflow.

    Args:
        input6_commodity_group_relevant: Typed data.Input6CommodityGroupRelevant series over named commodity-group coordinates, carrying relevance selections that determine whether each tailored commodity-group shock is active.
        imported_commodity_prices: Typed data.ImportedCommodityPrices series over named commodity and measure coordinates, supplying percent-change price inputs for base metals, precious metals, grains, and other agricultural commodities.

    Returns:
        Typed data.In6TailoredCommodityGroupPriceShock series of tailored non-fuel commodity-group price shocks, keyed by commodity group and Default/User-defined variant.
    """
    data.INPUT6_COMMODITY_GROUP_RELEVANT_SCHEMA.validate(input6_commodity_group_relevant)
    def formula(commodity: str, variant: str) -> float | str | None:
        if commodity == '1) Base metal (e.g., iron, copper, nickel, bauxite, etc.)' and variant == 'Default':
            return as_measure((imported_commodity_prices['Copper', '% change'] if xl_eq(input6_commodity_group_relevant[commodity], 'Yes') else ''))
        elif commodity == '2) Precious metal (e.g., gold, silver, platinum, etc.)' and variant == 'Default':
            return as_measure((imported_commodity_prices['Gold', '% change'] if xl_eq(input6_commodity_group_relevant[commodity], 'Yes') else ''))
        elif commodity == '3) Grain (e.g., wheat, corn, soybeans, etc.)' and variant == 'Default':
            return as_measure((imported_commodity_prices['Wheat', '% change'] if xl_eq(input6_commodity_group_relevant[commodity], 'Yes') else ''))
        elif commodity == '4) Other agricultural commodities (e.g., coffee, cocoa, tea, etc.)' and variant == 'Default':
            return as_measure((imported_commodity_prices['Coffee', '% change'] if xl_eq(input6_commodity_group_relevant[commodity], 'Yes') else ''))
        return as_measure(in6_tailored_commodity_group_price_shock[commodity, 'Default'])

    in6_tailored_commodity_group_price_shock = CoordinateReader('in6_tailored_commodity_group_price_shock', data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK_REQUIRED, formula)
    return data.In6TailoredCommodityGroupPriceShock.collect((coord, in6_tailored_commodity_group_price_shock[coord]) for coord in data.IN6_TAILORED_COMMODITY_GROUP_PRICE_SHOCK_REQUIRED)

@publish(key=(), domain=None, cells=data.IN6_TAILORED_NATDISASTER_SHOCK_SIZE_DEFAULT_CELLS)
def in6_tailored_natdisaster_shock_size_default(*, input6_tailored_tests_enabled: str) -> float | str:
    """Return the default natural-disaster PPG-debt-GDP shock size for tailored tests.

    Provide the standard natural-disaster shock magnitude used when tailored stress tests are enabled.

    Args:
        input6_tailored_tests_enabled: Flag indicating whether tailored stress tests are enabled; 'On' activates the default natural-disaster shock, while any other value suppresses it.

    Returns:
        Float shock size (10 when tailored tests are enabled, otherwise 0), or the XL error code string if evaluation fails.
    """
    try:
        return as_measure((10 if xl_eq(input6_tailored_tests_enabled, 'On') else 0))
    except XlError as error:
        return error.code

@publish(data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS_SCHEMA, cells=data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS_CELLS)
def in6_tailored_natdisaster_interaction_defaults(*, input6_tailored_tests_enabled: str) -> data.In6TailoredNatdisasterInteractionDefaults:
    """Compute standard natural-disaster tailored interaction default shocks.

    Provide Input 6 defaults for natural-disaster tailored stress interaction shocks, gated by the tailored-tests enable flag.

    Args:
        input6_tailored_tests_enabled: Scalar string enable flag; the value `On` activates tailored tests and selects the standard non-zero interaction shocks, while any other value yields zero shocks.

    Returns:
        A `data.In6TailoredNatdisasterInteractionDefaults` dataclass of named-axis series giving the natural-disaster real GDP growth and export growth interaction default shocks.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Size of associated real GDP growth shock':
            return as_measure((1.5 if xl_eq(input6_tailored_tests_enabled, 'On') else 0))
        return as_measure((3.5 if xl_eq(input6_tailored_tests_enabled, 'On') else 0))

    return data.In6TailoredNatdisasterInteractionDefaults.collect(evaluate(formula, data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS_REQUIRED))

@publish(key=(), domain=None, cells=data.IN6_TAILORED_COMMODITY_CLOSE_GAP_DEFAULT_CELLS)
def in6_tailored_commodity_close_gap_default(*, input6_tailored_tests_enabled: str) -> float | str:
    """Return the default tailored commodity-price close gap for Input 6 tailored tests.

    Resolve the standard years-to-close commodity price gap based on whether tailored tests are enabled.

    Args:
        input6_tailored_tests_enabled: Enabled flag string; the tailored-test gap is applied when this equals 'On'.

    Returns:
        float or str: the standard commodity price gap in years when tailored tests are enabled (6) or zero otherwise, or the Excel error code string if evaluation fails.
    """
    try:
        return as_measure((6 if xl_eq(input6_tailored_tests_enabled, 'On') else 0))
    except XlError as error:
        return error.code

@publish(data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS_SCHEMA, cells=data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS_CELLS)
def in6_tailored_commodity_interaction_defaults(*, in6_tailored_average_of_prices_shock_default: float | str, input6_tailored_tests_enabled: str) -> data.In6TailoredCommodityInteractionDefaults:
    """Compute Input 6 tailored commodity-price interaction shock defaults.

    Provide the standard commodity-price GDP-growth and revenue-drop interaction shocks used when tailored tests are enabled.

    Args:
        in6_tailored_average_of_prices_shock_default: Scalar average-of-prices shock default used to scale the commodity-price interaction shocks.
        input6_tailored_tests_enabled: Scalar flag indicating whether tailored stress tests are enabled; 'On' applies the shocks, otherwise they default to zero.

    Returns:
        A data.In6TailoredCommodityInteractionDefaults dataclass of typed series containing the real GDP growth shock and revenue-drop shock derived from the average-of-prices shock, or zeros when tailored tests are off.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Size of associated real GDP growth shock':
            return as_measure((xl_div(xl_mul(in6_tailored_average_of_prices_shock_default, 0.5), xl_neg(xl_div(10, 100))) if xl_eq(input6_tailored_tests_enabled, 'On') else 0))
        return as_measure((xl_div(xl_mul(in6_tailored_average_of_prices_shock_default, 0.75), xl_neg(xl_div(10, 100))) if xl_eq(input6_tailored_tests_enabled, 'On') else 0))

    return data.In6TailoredCommodityInteractionDefaults.collect(evaluate(formula, data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS_REQUIRED))

