@publish(data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS_SCHEMA, cells=data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS_CELLS)
def in6_tailored_mkt_fin_maturity_defaults(*, input6_tailored_tests_enabled: str) -> data.In6TailoredMktFinMaturityDefaults:
    """Collect tailored commercial-maturity and grace-period maturity defaults.

    Supplies the standard maturity shortenings used by Input 6 tailored market-financing tests when enabled.

    Args:
        input6_tailored_tests_enabled: Scalar string control flag; the tailored maturity reductions are applied only when it equals 'On', otherwise zero values are emitted.

    Returns:
        A `data.In6TailoredMktFinMaturityDefaults` dataclass of indicator-keyed series: a 5-year maturity shortening for original maturities greater than five years and a two-thirds grace-period shortening when tailored tests are enabled, with zeros for all fields otherwise.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'If original maturity is greater than 5 years, new maturity is':
            return as_measure((5 if xl_eq(input6_tailored_tests_enabled, 'On') else 0))
        return as_measure((xl_div(2, 3) if xl_eq(input6_tailored_tests_enabled, 'On') else 0))

    return data.In6TailoredMktFinMaturityDefaults.collect(evaluate(formula, data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS_REQUIRED))

