    data.INPUT3_INPUT_3_EXTERNAL_DEBT_PRIVATE_MLT_EXTERNAL_DEBT_AMORTIZATION_DUE_SCHEMA.validate(input3_input_3_external_debt_private_mlt_external_debt_amortization_due)
