@publish(data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT_SCHEMA, cells=data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT_CELLS)
def macro_debt_total_mlt_public_domestic_debt_amortization_debt(*, input5_summary_principal_payment: data.Input5SummaryPrincipalPayment, macro_debt_public_domestic_st: data.MacroDebtPublicDomesticSt, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtTotalMltPublicDomesticDebtAmortizationDebt:
    """Derive medium- and long-term public domestic debt amortization in US dollars from Input 5 principal payments.

    Converts period-over-period principal repayment on public domestic debt into a US dollar amortization series using the national-currency exchange rate.

    Args:
        input5_summary_principal_payment: Input 5 summary principal payment series, in national currency, keyed by projection years.
        macro_debt_public_domestic_st: Public domestic debt stock series, evaluated at the prior projection period to net out outstanding balances.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National-currency-per-US-dollar exchange rate series keyed by projection years.

    Returns:
        A data.MacroDebtTotalMltPublicDomesticDebtAmortizationDebt series of MLT public domestic debt amortization expressed in US dollars, keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(input5_summary_principal_payment[time_period], macro_debt_public_domestic_st[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MacroDebtTotalMltPublicDomesticDebtAmortizationDebt.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT_REQUIRED))

