@publish(data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE_SCHEMA, cells=data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE_CELLS)
def macro_debt_public_sector_interest_expenditure(*, macro_debt_ppg_interest_due: data.MacroDebtPpgInterestDue, macro_debt_total_public_domestic_debt_interest_due: data.MacroDebtTotalPublicDomesticDebtInterestDue, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtPublicSectorInterestExpenditure:
    """Compute public sector interest expenditure from PPG and domestic debt interest due, converted at the national-currency-per-U.S.-dollar exchange rate.

    Derive the national-currency public sector interest expenditure series for the Macro-Debt projection years.

    Args:
        macro_debt_ppg_interest_due: PPG interest due as a named-axis Macro-Debt series over projection years.
        macro_debt_total_public_domestic_debt_interest_due: Total public domestic debt interest due as a named-axis Macro-Debt series over projection years.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National-currency-per-U.S.-dollar exchange rate as a named-axis Macro-Debt series over projection years.

    Returns:
        A data.MacroDebtPublicSectorInterestExpenditure named-axis series of public sector interest expenditure in national currency, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_total_public_domestic_debt_interest_due[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MacroDebtPublicSectorInterestExpenditure.collect(evaluate(formula, data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE_REQUIRED))

