@publish(data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP_SCHEMA, cells=data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP_CELLS)
def macro_debt_private_debt_pct_gdp(*, macro_debt_private_sector_ext_debt: data.MacroDebtPrivateSectorExtDebt, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars) -> data.MacroDebtPrivateDebtPctGdp:
    """Compute private debt as a percent of GDP.

    Derive the private debt-to-GDP ratio from private-sector external debt and GDP at current prices in U.S. dollars.

    Args:
        macro_debt_private_sector_ext_debt: A data.MacroDebtPrivateSectorExtDebt series over catalog coordinates providing private-sector external debt by projection year.
        macro_debt_gdp_current_prices_u_s_dollars: A data.MacroDebtGdpCurrentPricesUSDollars series over catalog coordinates providing GDP at current prices in U.S. dollars by projection year.

    Returns:
        A data.MacroDebtPrivateDebtPctGdp series on Macro-Debt_Data keyed by projection years, giving private debt as a percent of GDP; non-numeric inputs yield a blank sentinel.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_private_sector_ext_debt[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100) if xl_isnumber_lazy(lambda: xl_mul(xl_div(macro_debt_private_sector_ext_debt[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100)) else '…'))

    return data.MacroDebtPrivateDebtPctGdp.collect(evaluate(formula, data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP_REQUIRED))

@publish(data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS_SCHEMA, cells=data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS_CELLS)
def macro_debt_private_debt_service_pct_exports(*, macro_debt_private_sector_short_term: data.MacroDebtPrivateSectorShortTerm, macro_debt_private_external_interest_due: data.MacroDebtPrivateExternalInterestDue, macro_debt_mlt_private_ext_debt_amortization: data.MacroDebtMltPrivateExtDebtAmortization, macro_debt_exports_of_goods_services: data.MacroDebtExportsOfGoodsServices) -> data.MacroDebtPrivateDebtServicePctExports:
    """Compute private debt service as a percentage of exports of goods and services.

    Derive the private-sector debt service ratio for the LIC-DSF macro-debt block from short-term debt, external interest due, amortization, and export series.

    Args:
        macro_debt_private_sector_short_term: Named-axis series of short-term private sector debt over the catalog coordinates, sampled at the projection year preceding the current one.
        macro_debt_private_external_interest_due: Named-axis series of interest due on private external debt for each projection year.
        macro_debt_mlt_private_ext_debt_amortization: Named-axis series of medium- and long-term private external debt amortization for each projection year.
        macro_debt_exports_of_goods_services: Named-axis series of exports of goods and services for each projection year, used as the denominator of the ratio.

    Returns:
        A data.MacroDebtPrivateDebtServicePctExports named-axis series of private debt service in percent of exports, keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(xl_add(xl_add(macro_debt_mlt_private_ext_debt_amortization[time_period], macro_debt_private_external_interest_due[time_period]), macro_debt_private_sector_short_term[time_period - 1]), macro_debt_exports_of_goods_services[time_period]), 100) if xl_isnumber_lazy(lambda: xl_mul(xl_div(xl_add(xl_add(macro_debt_mlt_private_ext_debt_amortization[time_period], macro_debt_private_external_interest_due[time_period]), macro_debt_private_sector_short_term[time_period - 1]), macro_debt_exports_of_goods_services[time_period]), 100)) else '…'))

    return data.MacroDebtPrivateDebtServicePctExports.collect(evaluate(formula, data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS_REQUIRED))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END_SCHEMA, cells=data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END_CELLS)
def macro_debt_total_public_debt_outstanding_year_end(*, macro_debt_total_public_ext_debt: data.MacroDebtTotalPublicExtDebt, macro_debt_total_public_domestic_debt: data.MacroDebtTotalPublicDomesticDebt) -> data.MacroDebtTotalPublicDebtOutstandingYearEnd:
    """Compute year-end total public debt outstanding from its external and domestic components.

    Combines the external and domestic public debt stock series into the aggregate year-end total public debt outstanding series.

    Args:
        macro_debt_total_public_ext_debt: External public debt outstanding at year end, in national currency, as a named-axis data series keyed by projection years.
        macro_debt_total_public_domestic_debt: Domestic public debt outstanding at year end, in national currency, as a named-axis data series keyed by projection years.

    Returns:
        Total public debt outstanding at year end, in national currency, as a named-axis data series keyed by projection years; each value is the sum of the corresponding external and domestic components when both are numeric, and zero otherwise.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(macro_debt_total_public_ext_debt[time_period], macro_debt_total_public_domestic_debt[time_period]) if xl_isnumber_lazy(lambda: xl_add(macro_debt_total_public_ext_debt[time_period], macro_debt_total_public_domestic_debt[time_period])) else 0))

    return data.MacroDebtTotalPublicDebtOutstandingYearEnd.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END_REQUIRED))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT_SCHEMA, cells=data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT_CELLS)
def macro_debt_total_public_ext_debt(*, macro_debt_us_dollars_by_year: data.MacroDebtUsDollarsByYear, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar) -> data.MacroDebtTotalPublicExtDebt:
    """Compute total public external debt in national currency from US-dollar debt and exchange rates.

    Multiply US-dollar macro-debt amounts by national-currency-per-US-dollar exchange rates to produce the total public external debt series.

    Args:
        macro_debt_us_dollars_by_year: US-dollar-denominated macro-debt amounts by projection year, as a data.MacroDebtUsDollarsByYear series.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: National-currency-per-US-dollar exchange rates by projection year, as a data.MacroDebtExchangeRateNationalCurrencyPerUSDollar series.

    Returns:
        A data.MacroDebtTotalPublicExtDebt series of total public external debt in national currency, keyed by projection year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(macro_debt_us_dollars_by_year[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MacroDebtTotalPublicExtDebt.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT_REQUIRED))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_SCHEMA, cells=data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_CELLS)
def macro_debt_total_public_domestic_debt(*, macro_debt_national_currency: data.MacroDebtNationalCurrency) -> data.MacroDebtTotalPublicDomesticDebt:
    """Compute total public domestic debt in national currency.

    Derive the total public domestic debt series from the macro-debt national-currency series.

    Args:
        macro_debt_national_currency: Macro-debt national currency series over catalog coordinates, keyed by projection years, supplying source national-currency debt values.

    Returns:
        Total public domestic debt as a data.MacroDebtTotalPublicDomesticDebt series over catalog coordinates, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((macro_debt_national_currency[time_period] if xl_isnumber_lazy(lambda: macro_debt_national_currency[time_period]) else 0))

    return data.MacroDebtTotalPublicDomesticDebt.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT_REQUIRED))

@publish(data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD_SCHEMA, cells=data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD_CELLS)
def macro_debt_fx_denominated_public_debt_end_of_period(*, in3_macro_fx_denominated_debt_including_locally_issued: float | str, ext_debt_fx_denominated_debt_outstanding: data.ExtDebtFxDenominatedDebtOutstanding, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar) -> data.MacroDebtFxDenominatedPublicDebtEndOfPeriod:
    """Compute end-of-period FX-denominated public debt.

    Convert applicable FX-denominated debt stocks into national-currency terms using the period exchange rate.

    Args:
        in3_macro_fx_denominated_debt_including_locally_issued: Scalar FX-denominated public debt including locally issued debt, used for the 2023 period.
        ext_debt_fx_denominated_debt_outstanding: Typed data series of outstanding external FX-denominated debt, indexed by projection years.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Typed data series of exchange rates in national currency per U.S. dollar, keyed by projection years from row 1.

    Returns:
        Typed data series of FX-denominated public debt at end of period, keyed by projection years, formed from the applicable FX debt stock multiplied by the national-currency-per-U.S.-dollar exchange rate.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_mul(in3_macro_fx_denominated_debt_including_locally_issued, macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))
        return as_measure(xl_mul(ext_debt_fx_denominated_debt_outstanding[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MacroDebtFxDenominatedPublicDebtEndOfPeriod.collect(evaluate(formula, data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD_REQUIRED))

@publish(data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL_SCHEMA, cells=data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL_CELLS)
def macro_debt_share_of_local_currency_denominated_external(*, input5_old_debt_outstanding_from_old_debt_in_local_currency: data.Input5OldDebtOutstandingFromOldDebtInLocalCurrency, input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: data.Input5NewDebtDebtStockOnNewDebtDenominatedInLocalCurrency, external_domestic_debt_definition: str, macro_debt_us_dollars: data.MacroDebtUsDollars, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar, lookup_afg: str) -> data.MacroDebtShareOfLocalCurrencyDenominatedExternal:
    """Compute the share of local-currency-denominated external public debt in total external debt.

    Produce the Macro-Debt_Data series for the local-currency external debt share, used in risk and chart calculations.

    Args:
        input5_old_debt_outstanding_from_old_debt_in_local_currency: Named-axis data.* series over catalog coordinates holding old debt outstanding from old debt in local currency (Input 5).
        input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: Named-axis data.* series over catalog coordinates holding new debt stock on new debt denominated in local currency (Input 5).
        external_domestic_debt_definition: Scalar string selecting the external/domestic debt definition to compare against the lookup constant.
        macro_debt_us_dollars: Named-axis data.* series over catalog coordinates for macro debt denominated in US dollars.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Named-axis data.* series over catalog coordinates for the exchange rate in national currency per US dollar.
        lookup_afg: Scalar string lookup constant for the debt-definition marker used in the equality test.

    Returns:
        A data.MacroDebtShareOfLocalCurrencyDenominatedExternal series keyed by projection years, giving the share of local-currency-denominated external public debt in total external debt, or zero when the external/domestic debt definition does not match the lookup constant.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(xl_div(xl_add(input5_old_debt_outstanding_from_old_debt_in_local_currency['non-residents', time_period], input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency['non-residents', time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), macro_debt_us_dollars[time_period]), 100) if xl_eq(external_domestic_debt_definition, lookup_afg) else 0))

    return data.MacroDebtShareOfLocalCurrencyDenominatedExternal.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL_REQUIRED))

@publish(data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT_SCHEMA, cells=data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT_CELLS)
def macro_debt_interest_rate_ext_debt(*, macro_debt_us_dollars_by_year: data.MacroDebtUsDollarsByYear, macro_debt_ppg_interest_due: data.MacroDebtPpgInterestDue) -> data.MacroDebtInterestRateExtDebt:
    """Compute the external-debt interest rate from PPG interest due and the prior year's US-dollar debt stock.

    Derive the Macro-Debt_Data interest-rate-on-external-debt series used in the LIC-DSF Chart Data pipeline.

    Args:
        macro_debt_us_dollars_by_year: A data.MacroDebtUsDollarsByYear series of annual US-dollar external debt stock by projection year, used lagged as the denominator in the interest-rate ratio.
        macro_debt_ppg_interest_due: A data.MacroDebtPpgInterestDue series of PPG external-debt interest due by projection year, used as the numerator in the interest-rate ratio.

    Returns:
        A data.MacroDebtInterestRateExtDebt series of interest rates on external debt, keyed by projection years from row 1, with numeric percentage values and the string ellipsis where the ratio cannot be computed.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_ppg_interest_due[time_period], macro_debt_us_dollars_by_year[time_period - 1]), 100) if xl_isnumber_lazy(lambda: xl_div(macro_debt_ppg_interest_due[time_period], macro_debt_us_dollars_by_year[time_period - 1])) else '...'))

    return data.MacroDebtInterestRateExtDebt.collect(evaluate(formula, data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT_REQUIRED))

@publish(data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT_SCHEMA, cells=data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT_CELLS)
def macro_debt_interest_rate_domestic_debt(*, macro_debt_national_currency: data.MacroDebtNationalCurrency, macro_debt_total_public_domestic_debt_interest_due: data.MacroDebtTotalPublicDomesticDebtInterestDue, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtInterestRateDomesticDebt:
    """Compute the annual interest rate on domestic debt from interest due, the prior-year national-currency base, and the concurrent exchange rate.

    Produces the Macro-Debt_Data domestic-debt interest rate series used in public-debt projections and DSA charts.

    Args:
        macro_debt_national_currency: National-currency base series on the Macro-Debt_Data coordinate grid; its prior projection-year value serves as the denominator in the domestic-debt interest-rate calculation.
        macro_debt_total_public_domestic_debt_interest_due: Total public domestic debt interest due series on the Macro-Debt_Data coordinate grid, used as the numerator of the domestic-debt interest-rate ratio.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National currency per U.S. dollar exchange rate series on the Macro-Debt_Data coordinate grid, applied to align the interest-due numerator with the national-currency denominator before scaling to percent.

    Returns:
        A data.MacroDebtInterestRateDomesticDebt series of annual domestic-debt interest rates keyed by projection years from row 1, with non-numeric denominator cases yielding '...'.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_mul(xl_div(macro_debt_total_public_domestic_debt_interest_due[time_period], macro_debt_national_currency[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), 100) if xl_isnumber_lazy(lambda: xl_div(macro_debt_total_public_domestic_debt_interest_due[time_period], macro_debt_national_currency[time_period - 1])) else '...'))

    return data.MacroDebtInterestRateDomesticDebt.collect(evaluate(formula, data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT_REQUIRED))

@publish(data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD_SCHEMA, cells=data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD_CELLS)
def macro_debt_pv_of_public_sector_ext_debt_end_of_period(*, ext_debt_total_pv_of_debt: data.ExtDebtTotalPvOfDebt, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar) -> data.MacroDebtPvOfPublicSectorExtDebtEndOfPeriod:
    """Return the present value of public sector external debt at end of period.

    Derive the end-of-period public external debt PV by multiplying total debt PV by the national-currency-per-U.S.-dollar exchange rate.

    Args:
        ext_debt_total_pv_of_debt: data.ExtDebtTotalPvOfDebt series of total external debt present values over catalog coordinates.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar series of national-currency-per-U.S.-dollar exchange rates over catalog coordinates.

    Returns:
        data.MacroDebtPvOfPublicSectorExtDebtEndOfPeriod series of public sector external debt present values at period end, keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_total_pv_of_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MacroDebtPvOfPublicSectorExtDebtEndOfPeriod.collect(evaluate(formula, data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD_REQUIRED))

@publish(data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS_SCHEMA, cells=data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS_CELLS)
def macro_debt_national_currency_us_dollars(*, macro_debt_public_sector_revenues_including_grants: data.MacroDebtPublicSectorRevenuesIncludingGrants, macro_debt_public_sector_grants: data.MacroDebtPublicSectorGrants, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtNationalCurrencyUsDollars:
    """Compute the US-dollar national-currency macro-debt series from net public-sector revenues.

    Convert public-sector revenues net of grants from national currency to US dollars using the period exchange rate.

    Args:
        macro_debt_public_sector_revenues_including_grants: Projection-year series of public-sector revenues including grants, expressed in national currency.
        macro_debt_public_sector_grants: Projection-year series of public-sector grants, expressed in national currency.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Projection-year series of the exchange rate, national currency per US dollar.

    Returns:
        A data.MacroDebtNationalCurrencyUsDollars series of US-dollar values keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_sub(macro_debt_public_sector_revenues_including_grants[time_period], macro_debt_public_sector_grants[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]) if xl_isnumber_lazy(lambda: xl_div(xl_sub(macro_debt_public_sector_revenues_including_grants[time_period], macro_debt_public_sector_grants[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) else '…'))

    return data.MacroDebtNationalCurrencyUsDollars.collect(evaluate(formula, data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS_REQUIRED))

@publish(data.MACRO_DEBT_REVENUES_PCT_GDP_SCHEMA, cells=data.MACRO_DEBT_REVENUES_PCT_GDP_CELLS)
def macro_debt_revenues_pct_gdp(*, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_national_currency_us_dollars: data.MacroDebtNationalCurrencyUsDollars) -> data.MacroDebtRevenuesPctGdp:
    """Derive the Macro-Debt revenues-to-GDP percentage series from national-currency debt amounts and current-price GDP.

    Expresses each projection year's revenue as a share of GDP for the Macro-Debt_Data sheet.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: Gross domestic product at current prices in US dollars, supplied as a data.MacroDebtGdpCurrentPricesUSDollars named-axis series over catalog coordinates.
        macro_debt_national_currency_us_dollars: National-currency debt amounts expressed in US dollars, supplied as a data.MacroDebtNationalCurrencyUsDollars named-axis series over catalog coordinates.

    Returns:
        Revenues in percent of GDP as a data.MacroDebtRevenuesPctGdp series, keyed by projection years from row 1, with non-numeric cells yielded as a placeholder.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_national_currency_us_dollars[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100) if xl_isnumber_lazy(lambda: xl_mul(xl_div(macro_debt_national_currency_us_dollars[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100)) else '…'))

    return data.MacroDebtRevenuesPctGdp.collect(evaluate(formula, data.MACRO_DEBT_REVENUES_PCT_GDP_REQUIRED))

@publish(data.MACRO_DEBT_REAL_GDP_GROWTH_SCHEMA, cells=data.MACRO_DEBT_REAL_GDP_GROWTH_CELLS)
def macro_debt_real_gdp_growth(*, macro_debt_gdp_constant_prices: data.MacroDebtGdpConstantPrices) -> data.MacroDebtRealGdpGrowth:
    """Compute real GDP growth from macro-debt GDP at constant prices.

    Derive the Macro-Debt_Data real GDP growth series used in LIC-DSF projections.

    Args:
        macro_debt_gdp_constant_prices: Macro-debt GDP at constant prices as a typed data series over catalog/projection coordinates; supplies the current and prior-period values needed for year-over-year growth.

    Returns:
        Typed data series of real GDP growth (Macro-Debt_Data), keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_constant_prices[time_period], macro_debt_gdp_constant_prices[time_period - 1]), 1), 100) if xl_isnumber_lazy(lambda: xl_mul(xl_sub(xl_div(macro_debt_gdp_constant_prices[time_period], macro_debt_gdp_constant_prices[time_period - 1]), 1), 100)) else '…'))

    return data.MacroDebtRealGdpGrowth.collect(evaluate(formula, data.MACRO_DEBT_REAL_GDP_GROWTH_REQUIRED))

@publish(data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY_SCHEMA, cells=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY_CELLS)
def macro_debt_gdp_deflator_index_national_currency(*, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_gdp_constant_prices: data.MacroDebtGdpConstantPrices, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtGdpDeflatorIndexNationalCurrency:
    """Compute the GDP deflator index in national currency.

    Derives the national-currency GDP deflator index from current-price USD GDP, constant-price GDP, and the national-currency-per-USD exchange rate using authored coordinate identities.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: Current-price GDP series expressed in US dollars and keyed by projection years.
        macro_debt_gdp_constant_prices: Constant-price GDP series keyed by projection years.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Exchange-rate series giving national currency per US dollar and keyed by projection years.

    Returns:
        A data.MacroDebtGdpDeflatorIndexNationalCurrency series keyed by projection years; each value is the computed deflator index or an ellipsis placeholder when the numeric expression cannot be evaluated.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), macro_debt_gdp_constant_prices[time_period]), 100) if xl_isnumber_lazy(lambda: xl_div(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), macro_debt_gdp_constant_prices[time_period])) else '…'))

    return data.MacroDebtGdpDeflatorIndexNationalCurrency.collect(evaluate(formula, data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY_REQUIRED))

@publish(data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_SCHEMA, cells=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_CELLS)
def macro_debt_change_in_gdp_deflator_factor(*, macro_debt_gdp_deflator_index_national_currency: data.MacroDebtGdpDeflatorIndexNationalCurrency) -> data.MacroDebtChangeInGdpDeflatorFactor:
    """Compute the annual percent change in the national-currency GDP deflator factor from the GDP deflator index series.

    Derive the Macro-Debt change-in-GDP-deflator factor used in LIC-DSF macro-debt calculations.

    Args:
        macro_debt_gdp_deflator_index_national_currency: National-currency GDP deflator index series keyed by projection year; each observation is compared with the prior period to compute the deflator change factor.

    Returns:
        data.MacroDebtChangeInGdpDeflatorFactor series containing percent changes in the GDP deflator factor, keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_deflator_index_national_currency[time_period], macro_debt_gdp_deflator_index_national_currency[time_period - 1]), 1), 100) if xl_isnumber_lazy(lambda: macro_debt_gdp_deflator_index_national_currency[time_period - 1]) else '...'))

    return data.MacroDebtChangeInGdpDeflatorFactor.collect(evaluate(formula, data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_REQUIRED))

@publish(data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS_SCHEMA, cells=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS_CELLS)
def macro_debt_gdp_deflator_index_dollars(*, macro_debt_gdp_current_prices_u_s_dollars: data.MacroDebtGdpCurrentPricesUSDollars, macro_debt_gdp_constant_prices: data.MacroDebtGdpConstantPrices) -> data.MacroDebtGdpDeflatorIndexDollars:
    """Compute the GDP deflator index in dollars from current- and constant-price macro debt series.

    Derives the deflator index by dividing current-price U.S. dollar debt-to-GDP values by constant-price values and scaling by 100.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: A data.MacroDebtGdpCurrentPricesUSDollars series of current-price U.S. dollar debt-to-GDP values over catalog coordinates.
        macro_debt_gdp_constant_prices: A data.MacroDebtGdpConstantPrices series of constant-price debt-to-GDP values over catalog coordinates.

    Returns:
        A data.MacroDebtGdpDeflatorIndexDollars series containing the GDP deflator index (dollars), keyed by projection years from row 1.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_gdp_constant_prices[time_period]), 100) if xl_isnumber_lazy(lambda: xl_div(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_gdp_constant_prices[time_period])) else '…'))

    return data.MacroDebtGdpDeflatorIndexDollars.collect(evaluate(formula, data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS_REQUIRED))

@publish(data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR_SCHEMA, cells=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR_CELLS)
def macro_debt_change_in_gdp_deflator_factor_by_year(*, macro_debt_gdp_deflator_index_dollars: data.MacroDebtGdpDeflatorIndexDollars) -> data.MacroDebtChangeInGdpDeflatorFactorByYear:
    """Derive the year-over-year percent change in the GDP deflator factor from the deflator index series.

    Convert the dollar-denominated GDP deflator index into the annual percent change factor used by the Macro-Debt block.

    Args:
        macro_debt_gdp_deflator_index_dollars: data.MacroDebtGdpDeflatorIndexDollars series of GDP deflator index levels keyed by projection year; each year's value is divided by the prior year's value (yielding an ellipsis string when that prior value is non-numeric) to form the percent change.

    Returns:
        data.MacroDebtChangeInGdpDeflatorFactorByYear series of GDP deflator change factors (percent), keyed by projection years starting at row 1, with ellipsis strings where the prior-year index is unavailable.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_deflator_index_dollars[time_period], macro_debt_gdp_deflator_index_dollars[time_period - 1]), 1), 100) if xl_isnumber_lazy(lambda: macro_debt_gdp_deflator_index_dollars[time_period - 1]) else '...'))

    return data.MacroDebtChangeInGdpDeflatorFactorByYear.collect(evaluate(formula, data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR_REQUIRED))

@publish(data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE_SCHEMA, cells=data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE_CELLS)
def macro_debt_us_gdp_deflator_percent_change(*, macro_debt_none: data.MacroDebtNone) -> data.MacroDebtUsGdpDeflatorPercentChange:
    """Compute US GDP deflator percent change from macro-debt levels.

    Derive the deflator inflation-rate series used in macro-debt projections.

    Args:
        macro_debt_none: Typed data series supplying GDP deflator levels keyed by projection years; the prior-year value provides the base for the percent-change calculation.

    Returns:
        Typed data series of US GDP deflator percent change keyed by projection years, carrying blank or string placeholders where the prior-year value is not numeric.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_none[time_period], macro_debt_none[time_period - 1]), 1), 100) if xl_isnumber_lazy(lambda: macro_debt_none[time_period - 1]) else '...'))

    return data.MacroDebtUsGdpDeflatorPercentChange.collect(evaluate(formula, data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE_REQUIRED))

@publish(data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC_SCHEMA, cells=data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC_CELLS)
def macro_debt_exchange_rate_dollar_nc(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.MacroDebtExchangeRateDollarNc:
    """Compute the reciprocal of a national-currency-per-U.S.-dollar exchange-rate series.

    Derive the U.S.-dollar-per-national-currency series used in macro-debt calculations.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc series of national-currency-per-U.S.-dollar exchange rates keyed by projection years.

    Returns:
        data.MacroDebtExchangeRateDollarNc series of U.S.-dollar-per-national-currency exchange rates keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(1, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MacroDebtExchangeRateDollarNc.collect(evaluate(formula, data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC_REQUIRED))

@publish(data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION_SCHEMA, cells=data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION_CELLS)
def macro_debt_depreciation_of_nc_depreciation(*, macro_debt_exchange_rate_dollar_nc: data.MacroDebtExchangeRateDollarNc) -> data.MacroDebtDepreciationOfNcDepreciation:
    """Compute the implied depreciation of the national currency from the dollar exchange-rate series.

    Derives the Macro-Debt_Data NC depreciation path, expressed in percent, by applying the year-over-year change identity to the dollar exchange rate for each projection year.

    Args:
        macro_debt_exchange_rate_dollar_nc: Named-axis data series of the dollar exchange rate for the national currency, keyed by projection years and read at both the current and prior period to form the percent change; non-numeric periods propagate a placeholder.

    Returns:
        data.MacroDebtDepreciationOfNcDepreciation series of NC depreciation (positive values denote depreciation), keyed by projection years aligned to row 1 of the Macro-Debt_Data block.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[time_period - 1]), 1)) if xl_isnumber_lazy(lambda: xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[time_period - 1]), 1))) else '...'))

    return data.MacroDebtDepreciationOfNcDepreciation.collect(evaluate(formula, data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION_REQUIRED))

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_CELLS)
def start_debt_sustainability_analysis(*, start_working_language: str, lookup_language_native_name: data.LookupLanguageNativeName, lookup_language_english_name: data.LookupLanguageEnglishName) -> str:
    """Resolve the English language name for a START working language via the language lookup tables.

    Map a DSA START working-language label to its English equivalent using the native and English language coordinate series.

    Args:
        start_working_language: Scalar working-language label to match in the native-language lookup series.
        lookup_language_native_name: Named-axis data.LookupLanguageNativeName series over language coordinates, providing the native-name lookup column.
        lookup_language_english_name: Named-axis data.LookupLanguageEnglishName series over language coordinates, providing the English-name return column.

    Returns:
        The matched English language name as a str, or the Excel error code as a string if the lookup fails.
    """
    data.LOOKUP_LANGUAGE_NATIVE_NAME_SCHEMA.validate(lookup_language_native_name)
    data.LOOKUP_LANGUAGE_ENGLISH_NAME_SCHEMA.validate(lookup_language_english_name)
    _start_debt_sustainability_analysis_table_0 = lazy_table(((lambda: lookup_language_native_name['English'], lambda: lookup_language_english_name['English']), (lambda: lookup_language_native_name['French'], lambda: lookup_language_english_name['French']), (lambda: lookup_language_native_name['Portuguese'], lambda: lookup_language_english_name['Portuguese']), (lambda: lookup_language_native_name['Spanish'], lambda: lookup_language_english_name['Spanish'])))
    try:
        return as_measure(xl_vlookup(start_working_language, _start_debt_sustainability_analysis_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_M_CELLS)
def start_debt_sustainability_analysis_m(*, start_debt_sustainability_analysis: str) -> int | str:
    """Map a Debt Sustainability Analysis language label to its integer code.

    Resolves the START single-cell anchor for the LIC-DSF extraction surface.

    Args:
        start_debt_sustainability_analysis: Language label for the Debt Sustainability Analysis (START) single-cell anchor, expressed as a scalar string such as 'English', 'French', or 'Portuguese'.

    Returns:
        Integer language code (0 for 'English', 1 for 'French', 2 for 'Portuguese', otherwise 3) or the Excel error code string if evaluation fails.
    """
    try:
        return as_measure((0 if xl_eq(start_debt_sustainability_analysis, 'English') else (1 if xl_eq(start_debt_sustainability_analysis, 'French') else (2 if xl_eq(start_debt_sustainability_analysis, 'Portuguese') else 3))), 'int')
    except XlError as error:
        return error.code

