@publish(data.TRANSLATION_INTEREST_RATE_DOMESTIC_DEBT_SCHEMA, cells=data.TRANSLATION_INTEREST_RATE_DOMESTIC_DEBT_CELLS)
def translation_interest_rate_domestic_debt(*, translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt: data.TranslationInput3MacroDebtDataDmxInterestRateOnDomesticDebt) -> data.TranslationInterestRateDomesticDebt:
    """Return the translated series of interest rates on domestic debt.

    Resolves the per-language domestic-debt interest-rate labels from the Input 3 macro-debt translation block into the canonical domestic-debt interest-rate series.

    Args:
        translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt: data.TranslationInput3MacroDebtDataDmxInterestRateOnDomesticDebt series holding the interest rate on domestic debt keyed by the template language columns.

    Returns:
        data.TranslationInterestRateDomesticDebt series of interest rates on domestic debt keyed by the canonical column labels.
    """
    data.TRANSLATION_INPUT_3_MACRO_DEBT_DATA_DMX_INTEREST_RATE_ON_DOMESTIC_DEBT_SCHEMA.validate(translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt)
    def formula(variant: str) -> str | None:
        if variant == 'non-residents':
            return as_measure(translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt['English'], 'str')
        elif variant == 'Non-résidents':
            return as_measure(translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt['French'], 'str')
        elif variant == 'não residentes':
            return as_measure(translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt['Portuguese'], 'str')
        return as_measure(translation_input_3_macro_debt_data_dmx_interest_rate_on_domestic_debt['Spanish'], 'str')

    return data.TranslationInterestRateDomesticDebt.collect(evaluate(formula, data.TRANSLATION_INTEREST_RATE_DOMESTIC_DEBT_REQUIRED))

@publish(data.TRANSLATION_ST_DEBT_SCHEMA, cells=data.TRANSLATION_ST_DEBT_CELLS)
def translation_st_debt(*, translation_labels_short_term_debt: data.TranslationLabelsShortTermDebt) -> data.TranslationStDebt:
    """Build the short-term debt translation series from translated maturity labels.

    Compute short-term debt (translation) using authored coordinate identities over the workbook label series.

    Args:
        translation_labels_short_term_debt: Typed data series of short-term debt translation labels, keyed by column labels from row 494 and used as the source labels for the returned translation series.

    Returns:
        A typed data.TranslationStDebt series of short-term debt (translation), keyed by column labels from row 494.
    """
    data.TRANSLATION_LABELS_SHORT_TERM_DEBT_SCHEMA.validate(translation_labels_short_term_debt)
    def formula(variant: str) -> str | None:
        if variant == 'Maturity':
            return as_measure(translation_labels_short_term_debt['English'], 'str')
        elif variant == 'Échéance':
            return as_measure(translation_labels_short_term_debt['French'], 'str')
        elif variant == 'Vencimento':
            return as_measure(translation_labels_short_term_debt['Portuguese'], 'str')
        return as_measure(translation_labels_short_term_debt['Spanish'], 'str')

    return data.TranslationStDebt.collect(evaluate(formula, data.TRANSLATION_ST_DEBT_REQUIRED))

@publish(data.LEFTOVER_EXCHANGE_RATE_PA_SCHEMA, cells=data.LEFTOVER_EXCHANGE_RATE_PA_CELLS)
def leftover_exchange_rate_pa(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> data.LeftoverExchangeRatePa:
    """Compute leftover exchange rate PA from macro-debt exchange rate and scenario leftovers.

    Produce the DSA scenario-sheet leftover exchange rate PA series keyed by SCENARIO, sourcing Baseline and B2_mkt values from the macro-debt exchange rate series and other scenarios from existing leftovers.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Macro-debt exchange rate national currency per USD series used to populate Baseline and B2_mkt entries.

    Returns:
        Leftover exchange rate PA series keyed by SCENARIO, with Baseline/B2_mkt values taken from the macro-debt exchange rate and remaining scenario values from the existing leftover series.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('B2_mkt', 'Baseline'):
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])
        return as_measure(leftover_exchange_rate_pa['B2_mkt', time_period])

    leftover_exchange_rate_pa = CoordinateReader('leftover_exchange_rate_pa', data.LEFTOVER_EXCHANGE_RATE_PA_REQUIRED, formula)
    return data.LeftoverExchangeRatePa.collect((coord, leftover_exchange_rate_pa[coord]) for coord in data.LEFTOVER_EXCHANGE_RATE_PA_REQUIRED)

@publish(data.CUSTOM_PUB_PERIOD_SCHEMA, cells=data.CUSTOM_PUB_PERIOD_CELLS)
def custom_pub_period(*, pv_resfin_pub_opening_stock_period: int | str, pv_resfin_pub_discount_period: data.PvResfinPubDiscountPeriod) -> data.CustomPubPeriod:
    """Compute the customized public-period series from opening-stock and discount-period measures.

    Resolve internal LIC-DSF custom public-period values via authored coordinate identities for downstream debt-sustainability calculations.

    Args:
        pv_resfin_pub_opening_stock_period: Scalar opening-stock period value, supplied as an integer or string, used when the requested time period is the opening year.
        pv_resfin_pub_discount_period: Named-axis tensor over catalog coordinates holding external MLT debt discount-period values by time period; supplies the fallback measure for non-opening periods.

    Returns:
        A `data.CustomPubPeriod` series mapping required custom public periods to their computed integer or string measure; this internal series is graph-coverage chrome (section title, footnote, or lookup token) rather than a public series.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(pv_resfin_pub_opening_stock_period, 'int')
        return as_measure(pv_resfin_pub_discount_period['External MLT debt', time_period], 'int')

    return data.CustomPubPeriod.collect(evaluate(formula, data.CUSTOM_PUB_PERIOD_REQUIRED))

