@publish(data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR_SCHEMA, cells=data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR_CELLS)
def custom_pub_avg_real_interest_rate_by_year(*, custom_pub_avg_real_interest_rate: float | str) -> data.CustomPubAvgRealInterestRateByYear:
    """Build the custom public average real interest rate series by year.

    Resolve the custom public average real interest rate for each required year by anchoring the 2025 value and carrying it forward.

    Args:
        custom_pub_avg_real_interest_rate: Base custom public average real interest rate as a scalar float or string; it sets the 2025 value and later years reuse the prior year's value.

    Returns:
        A data.CustomPubAvgRealInterestRateByYear series mapping each required catalog year to the custom public average real interest rate.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(custom_pub_avg_real_interest_rate)
        return as_measure(custom_pub_avg_real_interest_rate_by_year[time_period - 1])

    custom_pub_avg_real_interest_rate_by_year = CoordinateReader('custom_pub_avg_real_interest_rate_by_year', data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR_REQUIRED, formula)
    return data.CustomPubAvgRealInterestRateByYear.collect((coord, custom_pub_avg_real_interest_rate_by_year[coord]) for coord in data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR_REQUIRED)

