@publish(data.C4_MARKET_INSTRUMENTS_SCHEMA, cells=data.C4_MARKET_INSTRUMENTS_CELLS)
def c4_market_instruments(*, input4_grace_period: data.Input4GracePeriod, input4_loan_maturity: data.Input4LoanMaturity) -> data.C4MarketInstruments:
    """Assemble C4 commercial-loan market instruments from grace-period and loan-maturity inputs.

    Provide the C4 market-instrument terms used by downstream debt-sustainability calculations.

    Args:
        input4_grace_period: Grace-period input as a data.Input4GracePeriod named-axis series over commercial-loan instrument coordinates, supplying the 2023 values for each C4 instrument.
        input4_loan_maturity: Loan-maturity input as a data.Input4LoanMaturity named-axis series over commercial-loan instrument coordinates, supplying the non-2023 values for each C4 instrument.

    Returns:
        A data.C4MarketInstruments dataclass of C4 commercial-loan market-instrument series keyed by instrument and time period, combining grace-period values at 2023 with loan-maturity values otherwise.
    """
    data.INPUT4_GRACE_PERIOD_SCHEMA.validate(input4_grace_period)
    data.INPUT4_LOAN_MATURITY_SCHEMA.validate(input4_loan_maturity)
    def formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2023:
            return as_measure(input4_grace_period[instrument], 'int')
        return as_measure(input4_loan_maturity[instrument], 'int')

    return data.C4MarketInstruments.collect(evaluate(formula, data.C4_MARKET_INSTRUMENTS_REQUIRED))

