@publish(data.INPUT6_STANDARD_PARAMS_2_SCHEMA, cells=data.INPUT6_STANDARD_PARAMS_2_CELLS)
def input6_standard_params_2(*, in6opt_standard_inflation_elasticity_default: float | str, in6opt_standard_addl_borrowing_cost_default: float | str, in6opt_standard_gdp_exports_elasticity_default: float | str, in6opt_standard_fx_passthrough_default: float | str, in6opt_standard_nx_elasticity_default: float | str, in6opt_standard_us_inflation_default: float | str) -> data.Input6StandardParams2:
    """Build the Input 6 standard-parameter bundle from the supplied default scalars.

    Resolve the residual Input 6 standard stress-test default fields into a typed coordinate series for the IDA21 LIC-DSF template.

    Args:
        in6opt_standard_inflation_elasticity_default: Scalar default for the standardized inflation-elasticity assumption (b1 real GDP growth row); a float value or template string placeholder.
        in6opt_standard_addl_borrowing_cost_default: Scalar default for the additional borrowing-cost assumption (b2 primary balance row); a float value or template string placeholder.
        in6opt_standard_gdp_exports_elasticity_default: Scalar default for the GDP-export elasticity assumption (b3 exports row); a float value or template string placeholder.
        in6opt_standard_fx_passthrough_default: Scalar default for the FX passthrough assumption (b5 depreciation row 1); a float value or template string placeholder.
        in6opt_standard_nx_elasticity_default: Scalar default for the net-export elasticity assumption (b5 depreciation row 2); a float value or template string placeholder.
        in6opt_standard_us_inflation_default: Scalar default for the US inflation assumption (b5 depreciation row 3); a float value or template string placeholder.

    Returns:
        A data.Input6StandardParams2 dataclass of typed series for the required Input 6 standard-parameter coordinates, with each coordinate resolved from the corresponding default scalar.
    """
    def formula(parameter: str, variant: str) -> float | str | None:
        if parameter == 'b1_real_gdp_growth':
            return as_measure(in6opt_standard_inflation_elasticity_default)
        elif parameter == 'b2_primary_balance':
            return as_measure(in6opt_standard_addl_borrowing_cost_default)
        elif parameter == 'b3_exports':
            return as_measure(in6opt_standard_gdp_exports_elasticity_default)
        elif parameter == 'b5_depreciation_1':
            return as_measure(in6opt_standard_fx_passthrough_default)
        elif parameter == 'b5_depreciation_2':
            return as_measure(in6opt_standard_nx_elasticity_default)
        elif parameter == 'b5_depreciation_3':
            return as_measure(in6opt_standard_us_inflation_default)
        elif parameter == 'b6_combination':
            return as_measure(input6_standard_params_2['b1_real_gdp_growth', variant])
        elif parameter == 'real_overvaluation_eba':
            return as_measure(input6_standard_params_2['b5_depreciation_1', variant])
        return as_measure(input6_standard_params_2['b5_depreciation_2', variant])

    input6_standard_params_2 = CoordinateReader('input6_standard_params_2', data.INPUT6_STANDARD_PARAMS_2_REQUIRED, formula)
    return data.Input6StandardParams2.collect((coord, input6_standard_params_2[coord]) for coord in data.INPUT6_STANDARD_PARAMS_2_REQUIRED)

