@publish(data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW_SCHEMA, cells=data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW_CELLS)
def custom_ext_average_interest_rate_new_debt_by_row(*, in7_resfin_ext_mlt_effective: data.In7ResfinExtMltEffective) -> data.CustomExtAverageInterestRateNewDebtByRow:
    """Compute custom external average interest rate on new debt by row.

    Maps Input 7 external financing assumptions into a row-keyed series of average interest rate on new debt and related terms.

    Args:
        in7_resfin_ext_mlt_effective: Keyword-only data.In7ResfinExtMltEffective series providing Input 7 residual financing external multilateral effective assumptions, including average nominal interest rate on new borrowing in USD, USD discount rate, average grace period, and average maturity including grace period.

    Returns:
        A data.CustomExtAverageInterestRateNewDebtByRow series of average interest rate on new debt, keyed by row labels.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Average interest rate on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. nominal interest rate on new borrowing in USD'])
        elif indicator == 'USD Discount rate':
            return as_measure(in7_resfin_ext_mlt_effective[indicator])
        elif indicator == 'Average grace period on new debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
        return as_measure(in7_resfin_ext_mlt_effective['Avg. maturity (incl. grace period)'])

    return data.CustomExtAverageInterestRateNewDebtByRow.collect(evaluate(formula, data.CUSTOM_EXT_AVERAGE_INTEREST_RATE_NEW_DEBT_BY_ROW_REQUIRED))

