@publish(data.LEFTOVER_REAL_INTEREST_RATE_SCHEMA, cells=data.LEFTOVER_REAL_INTEREST_RATE_CELLS)
def leftover_real_interest_rate(*, input6_standard_params_2: data.Input6StandardParams2, input6_tailored_params_3: data.Input6TailoredParams3) -> data.LeftoverRealInterestRate:
    """Compute the leftover real interest rate for DSA scenarios.

    Derive scenario-specific residual real interest rates from standard and tailored stress parameter series.

    Args:
        input6_standard_params_2: Standard-scenario parameter series supplying real GDP growth and depreciation fields used to derive residual real interest rates.
        input6_tailored_params_3: Tailored-scenario parameter series supplying disaster-related export growth and revenue drop shocks used to derive residual real interest rates.

    Returns:
        data.LeftoverRealInterestRate series of residual real interest rates keyed by SCENARIO.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'B1':
            return as_measure(input6_standard_params_2['b1_real_gdp_growth', 'default'])
        elif scenario == 'B5':
            return as_measure(input6_standard_params_2['b5_depreciation_1', 'default'])
        elif scenario == 'C2':
            return as_measure(input6_tailored_params_3['disaster_export_growth_shock'])
        return as_measure(input6_tailored_params_3['disaster_revenue_drop'])

    return data.LeftoverRealInterestRate.collect(evaluate(formula, data.LEFTOVER_REAL_INTEREST_RATE_REQUIRED))

@publish(data.C4_MKT_FIN_NET_NON_DEBT_CREATING_FLOWS_FDI_GDP_RATIO_BY_ROW_SCHEMA, cells=data.C4_MKT_FIN_NET_NON_DEBT_CREATING_FLOWS_FDI_GDP_RATIO_BY_ROW_CELLS)
def c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row(*, input6_tailored_params_2: data.Input6TailoredParams2) -> data.C4MktFinNetNonDebtCreatingFlowsFdiGdpRatioByRow:
    """Compute the market-financing net non-debt-creating flows FDI-to-GDP ratio by row from tailored Input 6 parameters.

    Maps tailored stress assumptions to the by-row FDI-to-GDP ratio series used for internal graph coverage.

    Args:
        input6_tailored_params_2: A data.Input6TailoredParams2 series of tailored stress assumptions for Input 6, including new-maturity rules for original maturities above and below five years.

    Returns:
        A data.C4MktFinNetNonDebtCreatingFlowsFdiGdpRatioByRow series containing the FDI-to-GDP ratio by row; this is internal graph-coverage chrome, not a public output.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'If original maturity is greater than 5 years, new maturity is':
            return as_measure(input6_tailored_params_2['new_maturity_if_gt_5y_1'])
        elif indicator == 'If original maturity is less than 5 years, new maturity is shortened by':
            return as_measure(input6_tailored_params_2['new_maturity_if_gt_5y_2'])
        return as_measure(input6_tailored_params_2['new_maturity_if_gt_5y_3'])

    return data.C4MktFinNetNonDebtCreatingFlowsFdiGdpRatioByRow.collect(evaluate(formula, data.C4_MKT_FIN_NET_NON_DEBT_CREATING_FLOWS_FDI_GDP_RATIO_BY_ROW_REQUIRED))

