def input6_tailored_params(*, input6_tailored_params_fuel_label: str) -> data.Input6TailoredParams:
    """Build the tailored stress-test parameter set for a fuel label.

    Resolve Input 6 tailored-tests fields into the LIC-DSF tailored parameter dataclass.

    Args:
        input6_tailored_params_fuel_label: Scalar fuel label identifying the Input 6 tailored-tests field from which the remaining parameter values are collected.

    Returns:
        A data.Input6TailoredParams dataclass containing the tailored-test parameter series keyed by lic_dsf field names.
    """
    def formula(parameter: str) -> float | str | None:
        return as_measure(input6_tailored_params_fuel_label)

    return data.Input6TailoredParams.collect(evaluate(formula, data.INPUT6_TAILORED_PARAMS_REQUIRED))

