    data.CHART_RISK_LABELS_SCHEMA.validate(chart_risk_labels)
    _fiscal_risk_rating_signal_table_0 = lazy_table(((lambda: chart_numeric_risk_rating['Low'], lambda: chart_risk_labels['Low']), (lambda: chart_numeric_risk_rating['Moderate'], lambda: chart_risk_labels['Moderate']), (lambda: None, lambda: None), (lambda: None, lambda: None), (lambda: chart_numeric_risk_rating['High'], lambda: chart_risk_labels['High'])))
