            return as_measure((xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IMF']) if xl_gt(xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IMF']), 0) else 0), 'int')
