@publish(data.PV_BASE_OUTPUT_AMORTIZATION_SCHEMA, cells=data.PV_BASE_OUTPUT_AMORTIZATION_CELLS)
def pv_base_output_amortization(*, pv_base_block_grace: data.PvBaseBlockGrace, pv_base_block_maturity: data.PvBaseBlockMaturity, pv_base_discount_post_grace_cumulative: data.PvBaseDiscountPostGraceCumulative, pv_base_discount_post_maturity_cumulative: data.PvBaseDiscountPostMaturityCumulative) -> data.PvBaseOutputAmortization:
    """Derive baseline output amortization per instrument from cumulative post-grace and post-maturity discounts spread over the post-grace block.

    Lifts the 28-instrument Amortization series on pv_base.new_loan_output so downstream baseline calculations read a single catalog-aligned output series.

    Args:
        pv_base_block_grace: Per-instrument grace-period length over the catalog coordinates, used as the denominator offset of the post-grace block.
        pv_base_block_maturity: Per-instrument block maturity over the catalog coordinates, supplying the terminating endpoint of the amortization window.
        pv_base_discount_post_grace_cumulative: Instrument- and TIME_PERIOD-indexed cumulative discount amounts accumulated after the grace period, forming the starting stock for the difference.
        pv_base_discount_post_maturity_cumulative: Instrument- and TIME_PERIOD-indexed cumulative discount amounts accumulated after maturity, subtracted from the post-grace cumulative to isolate the block to amortize.

    Returns:
        A data.PvBaseOutputAmortization named-axis series over instrument x TIME_PERIOD, holding the per-instrument amortization values.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IMF', time_period], pv_base_discount_post_maturity_cumulative['IMF', time_period]), xl_sub(pv_base_block_maturity['IMF'], pv_base_block_grace['IMF'])))
        elif instrument == 'IDA - regular':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA - regular', time_period], pv_base_discount_post_maturity_cumulative['IDA - regular', time_period]), xl_sub(pv_base_block_maturity['IDA - regular'], pv_base_block_grace['IDA - regular'])))
        elif instrument == 'IDA - 50Y loans':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA - 50Y loans', time_period], pv_base_discount_post_maturity_cumulative['IDA - 50Y loans', time_period]), xl_sub(pv_base_block_maturity['IDA - 50Y loans'], pv_base_block_grace['IDA - 50Y loans'])))
        elif instrument == 'IDA - SML':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA - SML', time_period], pv_base_discount_post_maturity_cumulative['IDA - SML', time_period]), xl_sub(pv_base_block_maturity['IDA - SML'], pv_base_block_grace['IDA - SML'])))
        elif instrument == 'IDA NEW 40-year credits':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA NEW 40-year credits', time_period], pv_base_discount_post_maturity_cumulative['IDA NEW 40-year credits', time_period]), xl_sub(pv_base_block_maturity['IDA NEW 40-year credits'], pv_base_block_grace['IDA NEW 40-year credits'])))
        elif instrument == 'IDA NEW Regular':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA NEW Regular', time_period], pv_base_discount_post_maturity_cumulative['IDA NEW Regular', time_period]), xl_sub(pv_base_block_maturity['IDA NEW Regular'], pv_base_block_grace['IDA NEW Regular'])))
        elif instrument == 'IDA NEW Blend floating':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA NEW Blend floating', time_period], pv_base_discount_post_maturity_cumulative['IDA NEW Blend floating', time_period]), xl_sub(pv_base_block_maturity['IDA NEW Blend floating'], pv_base_block_grace['IDA NEW Blend floating'])))
        elif instrument == 'IDA NEW 60-year credits':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['IDA NEW 60-year credits', time_period], pv_base_discount_post_maturity_cumulative['IDA NEW 60-year credits', time_period]), xl_sub(pv_base_block_maturity['IDA NEW 60-year credits'], pv_base_block_grace['IDA NEW 60-year credits'])))
        elif instrument == 'MULTI1':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['MULTI1', time_period], pv_base_discount_post_maturity_cumulative['MULTI1', time_period]), xl_sub(pv_base_block_maturity['MULTI1'], pv_base_block_grace['MULTI1'])))
        elif instrument == 'MULTI2':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['MULTI2', time_period], pv_base_discount_post_maturity_cumulative['MULTI2', time_period]), xl_sub(pv_base_block_maturity['MULTI2'], pv_base_block_grace['MULTI2'])))
        elif instrument == 'OTH_MULTI1':
            return as_measure(xl_div(xl_sub(pv_base_discount_post_grace_cumulative['OTH_MULTI1', time_period], pv_base_discount_post_maturity_cumulative['OTH_MULTI1', time_period]), xl_sub(pv_base_block_maturity['OTH_MULTI1'], pv_base_block_grace['OTH_MULTI1'])))
