@publish(data.PV_BASE_IDA_TERMS_SCHEDULE_COLUMN_INDEX_SCHEMA, cells=data.PV_BASE_IDA_TERMS_SCHEDULE_COLUMN_INDEX_CELLS)
def pv_base_ida_terms_schedule_column_index(*, pv_base_ida_scale_new_product_count: int | str) -> data.PvBaseIdaTermsScheduleColumnIndex:
    """Return the PV_Base IDA terms schedule column index for each projection year.

    Derives the per-year PV_Base column offset used to lay out the IDA terms schedule.

    Args:
        pv_base_ida_scale_new_product_count: Initial IDA terms scale new-product count as an integer or string-encoded integer, used to seed the first projection year's column index.

    Returns:
        A typed data.PvBaseIdaTermsScheduleColumnIndex series keyed by projection years, mapping each year to its PV_Base IDA terms schedule column index.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2025:
            return as_measure(xl_add(pv_base_ida_scale_new_product_count, 1), 'int')
        return as_measure(xl_add(pv_base_ida_terms_schedule_column_index[time_period - 1], 1), 'int')

