        return as_measure((xl_sub(pv_base_block_index_fx['Bonds (beyond 7 years)-FX', 'residents', time_period], pv_base_block_maturity_fx['Bonds (beyond 7 years)-FX', 'residents']) if xl_gt(xl_sub(pv_base_block_index_fx['Bonds (beyond 7 years)-FX', 'residents', time_period], pv_base_block_maturity_fx['Bonds (beyond 7 years)-FX', 'residents']), 0) else 0), 'int')

