@publish(data.PV_BASE_OUTPUT_PV_OF_DEBT_FX_SCHEMA, cells=data.PV_BASE_OUTPUT_PV_OF_DEBT_FX_CELLS)
def pv_base_output_pv_of_debt_fx(*, pv_base_block_interest_fx: data.PvBaseBlockInterestFx, pv_base_block_discount_fx: data.PvBaseBlockDiscountFx, pv_base_discount_pv_of_debt_fx: data.PvBaseDiscountPvOfDebtFx, pv_base_output_new_forex_borrowing_gross_usd_fx: data.PvBaseOutputNewForexBorrowingGrossUsdFx, pv_base_output_total_debt_service_in_usd_fx: data.PvBaseOutputTotalDebtServiceInUsdFx, pv_base_output_amortization_fx: data.PvBaseOutputAmortizationFx) -> data.PvBaseOutputPvOfDebtFx:
    """Derive the PV of debt series from block interest and discount rates plus debt-service components.

    Reconstructs `pv_base_output_pv_of_debt_fx` for each instrument–holder pair using the template's period-by-period balance identity.

    Args:
        pv_base_block_interest_fx: Series of block interest rates over instrument and holder coordinates, compared against the block discount rate to select the compounding branch.
        pv_base_block_discount_fx: Series of block discount rates over instrument and holder coordinates, compared against the block interest rate to select the compounding branch.
        pv_base_discount_pv_of_debt_fx: Series of discount PV-of-debt factors over instrument, holder, and time_period coordinates, applied as a percentage in the multiplicative branch.
        pv_base_output_new_forex_borrowing_gross_usd_fx: Series of gross new foreign-currency borrowing amounts in USD over instrument, holder, and time_period coordinates.
        pv_base_output_total_debt_service_in_usd_fx: Series of total debt service amounts in USD over instrument, holder, and time_period coordinates, subtracted in the service-based branch.
        pv_base_output_amortization_fx: Series of amortization amounts over instrument, holder, and time_period coordinates, subtracted from the prior-period PV.

    Returns:
        Series of PV-of-debt values over instrument, holder, and time_period coordinates.
    """
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((pv_base_output_new_forex_borrowing_gross_usd_fx[instrument, holder, time_period] if xl_ge(pv_base_block_interest_fx[instrument, holder], pv_base_block_discount_fx[instrument, holder]) else xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx[instrument, holder, time_period], pv_base_discount_pv_of_debt_fx[instrument, holder, time_period]), 100)))
        elif time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx[instrument, holder, time_period - 1], pv_base_output_amortization_fx[instrument, holder, time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx[instrument, holder, time_period]) if xl_ge(pv_base_block_interest_fx[instrument, holder], pv_base_block_discount_fx[instrument, holder]) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx[instrument, holder, time_period - 1], xl_add(1, pv_base_block_discount_fx[instrument, holder])), pv_base_output_total_debt_service_in_usd_fx[instrument, holder, time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx[instrument, holder, time_period], pv_base_discount_pv_of_debt_fx[instrument, holder, 2024]), 100))))
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'non-residents' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period - 1], pv_base_output_amortization_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (1 to 3 years)-FX', 'non-residents'], pv_base_block_discount_fx['Bonds (1 to 3 years)-FX', 'non-residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (1 to 3 years)-FX', 'non-residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'non-residents', 2024]), 100))))
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'non-residents' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period - 1], pv_base_output_amortization_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (4 to 7 years)-FX', 'non-residents'], pv_base_block_discount_fx['Bonds (4 to 7 years)-FX', 'non-residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (4 to 7 years)-FX', 'non-residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'non-residents', 2024]), 100))))
        elif instrument == 'Bonds (beyond 7 years)-FX' and holder == 'non-residents' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period - 1], pv_base_output_amortization_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (beyond 7 years)-FX', 'non-residents'], pv_base_block_discount_fx['Bonds (beyond 7 years)-FX', 'non-residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (beyond 7 years)-FX', 'non-residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'non-residents', 2024]), 100))))
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'residents' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'residents', time_period - 1], pv_base_output_amortization_fx['Bonds (1 to 3 years)-FX', 'residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (1 to 3 years)-FX', 'residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (1 to 3 years)-FX', 'residents'], pv_base_block_discount_fx['Bonds (1 to 3 years)-FX', 'residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (1 to 3 years)-FX', 'residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (1 to 3 years)-FX', 'residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (1 to 3 years)-FX', 'residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (1 to 3 years)-FX', 'residents', 2024]), 100))))
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'residents' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'residents', time_period - 1], pv_base_output_amortization_fx['Bonds (4 to 7 years)-FX', 'residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (4 to 7 years)-FX', 'residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (4 to 7 years)-FX', 'residents'], pv_base_block_discount_fx['Bonds (4 to 7 years)-FX', 'residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (4 to 7 years)-FX', 'residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (4 to 7 years)-FX', 'residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (4 to 7 years)-FX', 'residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (4 to 7 years)-FX', 'residents', 2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'residents', time_period - 1], pv_base_output_amortization_fx['Bonds (beyond 7 years)-FX', 'residents', time_period]), pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (beyond 7 years)-FX', 'residents', time_period]) if xl_ge(pv_base_block_interest_fx['Bonds (beyond 7 years)-FX', 'residents'], pv_base_block_discount_fx['Bonds (beyond 7 years)-FX', 'residents']) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'residents', time_period - 1], xl_add(1, pv_base_block_discount_fx['Bonds (beyond 7 years)-FX', 'residents'])), pv_base_output_total_debt_service_in_usd_fx['Bonds (beyond 7 years)-FX', 'residents', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd_fx['Bonds (beyond 7 years)-FX', 'residents', time_period], pv_base_discount_pv_of_debt_fx['Bonds (beyond 7 years)-FX', 'residents', 2024]), 100))))

    pv_base_output_pv_of_debt_fx = CoordinateReader('pv_base_output_pv_of_debt_fx', data.PV_BASE_OUTPUT_PV_OF_DEBT_FX_REQUIRED, formula)
