@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_SCHEMA, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_CELLS)
def pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd(*, pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd: data.PvBaseAddCostMktOutputNewForexBorrowingGrossUsd, pv_base_add_cost_mkt_output_amortization: data.PvBaseAddCostMktOutputAmortization) -> data.PvBaseAddCostMktOutputStockOfNewForexDebtInUsd:
    """Compute the stock of new forex debt in USD from gross borrowing and amortization.

    Roll the prior-period stock of new forex debt forward by adding gross new forex borrowing and subtracting amortization for each instrument along the projection years.

    Args:
        pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd: Gross new forex borrowing in USD as a named-axis data series over the instrument and time-period catalog coordinates, covering the COM3, COM4, COM5, Commecial Bank, and Eurobond instruments.
        pv_base_add_cost_mkt_output_amortization: Amortization of new forex debt in USD as a named-axis data series over the same instrument and time-period coordinates, subtracted from the carried-forward stock.

    Returns:
        The stock of new forex debt in USD as a data.PvBaseAddCostMktOutputStockOfNewForexDebtInUsd series over the instrument and time-period catalog coordinates, spanning the COM3, COM4, COM5, Commecial Bank, and Eurobond instruments.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['Eurobond', time_period]), pv_base_add_cost_mkt_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]), pv_base_add_cost_mkt_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM3', time_period]), pv_base_add_cost_mkt_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_base_add_cost_mkt_output_amortization['COM4', time_period]))
        elif instrument == 'COM5' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM5', time_period]), pv_base_add_cost_mkt_output_amortization['COM5', time_period]))
        elif time_period == 2024:
            return as_measure(xl_sub(None, pv_base_add_cost_mkt_output_amortization[instrument, time_period]))
        elif time_period == 2025:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd[instrument, time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd[instrument, time_period]), pv_base_add_cost_mkt_output_amortization[instrument, time_period]))
        elif instrument == 'Eurobond' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM4', time_period]))
        return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM5', time_period]))

    pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd = CoordinateReader('pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd', data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_REQUIRED, formula)
    return data.PvBaseAddCostMktOutputStockOfNewForexDebtInUsd.collect((coord, pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd[coord]) for coord in data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_REQUIRED)

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST_SCHEMA, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST_CELLS)
def pv_base_add_cost_mkt_output_interest(*, pv_base_add_cost_mkt_discount_interest_rate: data.PvBaseAddCostMktDiscountInterestRate, pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd: data.PvBaseAddCostMktOutputStockOfNewForexDebtInUsd) -> data.PvBaseAddCostMktOutputInterest:
    """Compute market-cost interest accrued on new forex debt, per instrument and time period.

    Derive interest accruals by applying per-instrument discount interest rates to prior-period stocks of new forex debt in USD.

    Args:
        pv_base_add_cost_mkt_discount_interest_rate: Discount interest rate series over the five instruments (Eurobond, Commecial Bank, COM3, COM4, COM5).
        pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd: Stock of new forex debt denominated in USD series, read at the previous time period for each instrument.

    Returns:
        Interest series over the instrument and time-period coordinates of the market-cost output block.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['Eurobond'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['Commecial Bank'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM3'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM4'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM5'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1]))

    return data.PvBaseAddCostMktOutputInterest.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST_REQUIRED))

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION_SCHEMA, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION_CELLS)
def pv_base_add_cost_mkt_output_amortization(*, pv_base_add_cost_mkt_grace: data.PvBaseAddCostMktGrace, pv_base_add_cost_mkt_maturity: data.PvBaseAddCostMktMaturity, pv_base_add_cost_mkt_discount_post_grace_cumulative: data.PvBaseAddCostMktDiscountPostGraceCumulative, pv_base_add_cost_mkt_discount_post_maturity_cumulative: data.PvBaseAddCostMktDiscountPostMaturityCumulative) -> data.PvBaseAddCostMktOutputAmortization:
    """Compute per-instrument market-cost amortization from cumulative discount balances.

    Derive the amortization series used in the PV base add-cost market output.

    Args:
        pv_base_add_cost_mkt_grace: Grace period by instrument, as a named-axis data series over catalog coordinates.
        pv_base_add_cost_mkt_maturity: Maturity by instrument, as a named-axis data series over catalog coordinates.
        pv_base_add_cost_mkt_discount_post_grace_cumulative: Cumulative discount from the grace date onward, by instrument and time period, as a named-axis data series over catalog coordinates.
        pv_base_add_cost_mkt_discount_post_maturity_cumulative: Cumulative discount from the maturity date onward, by instrument and time period, as a named-axis data series over catalog coordinates.

    Returns:
        Amortization by instrument and time period, as a data.PvBaseAddCostMktOutputAmortization series over catalog coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['Eurobond', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['Eurobond', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['Eurobond'], pv_base_add_cost_mkt_grace['Eurobond'])))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['Commecial Bank', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['Commecial Bank', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['Commecial Bank'], pv_base_add_cost_mkt_grace['Commecial Bank'])))
        elif instrument == 'COM3':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM3', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM3', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM3'], pv_base_add_cost_mkt_grace['COM3'])))
        elif instrument == 'COM4':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM4', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM4', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM4'], pv_base_add_cost_mkt_grace['COM4'])))
        return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM5', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM5', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM5'], pv_base_add_cost_mkt_grace['COM5'])))

    return data.PvBaseAddCostMktOutputAmortization.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION_REQUIRED))

@dataclass(frozen=True, slots=True)
class ScanPvLcNr1TermsFxPaGrowthResult:
    """Complete named results of one recurrence group evaluation."""
    pv_lc_nr1_terms_fx_pa_growth: data.PvLcNr1TermsFxPaGrowth
    pv_lc_nr1_terms_fx_pa_growth_avg: float | str
    pv_lc_nr1_terms_fx_pa: data.PvLcNr1TermsFxPa

def scan_pv_lc_nr1_terms_fx_pa_growth(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.MacroDebtExchangeRateNationalCurrencyPerUSDollarNc) -> ScanPvLcNr1TermsFxPaGrowthResult:
    """Evaluate the recurrence group `pv_lc_nr1_terms_fx_pa_growth`, `pv_lc_nr1_terms_fx_pa_growth_avg`, `pv_lc_nr1_terms_fx_pa` and publish complete tensors."""
    def pv_lc_nr1_terms_fx_pa_growth_formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(xl_div(pv_lc_nr1_terms_fx_pa[instrument, holder, time_period], pv_lc_nr1_terms_fx_pa[instrument, holder, time_period - 1]), 1))

    pv_lc_nr1_terms_fx_pa_growth = CoordinateReader('pv_lc_nr1_terms_fx_pa_growth', data.PV_LC_NR1_TERMS_FX_PA_GROWTH_REQUIRED, pv_lc_nr1_terms_fx_pa_growth_formula)
    def pv_lc_nr1_terms_fx_pa_growth_avg_formula() -> float | str:
        return as_measure(xl_average(view(pv_lc_nr1_terms_fx_pa_growth, cols={'INSTRUMENT': data.INSTRUMENT_AXIS_42.keys, 'HOLDER': data.HOLDER_AXIS.keys, 'TIME_PERIOD': data.TIME_PERIOD_AXIS_63.keys})))

    pv_lc_nr1_terms_fx_pa_growth_avg = CoordinateReader('pv_lc_nr1_terms_fx_pa_growth_avg', Domain.product(), pv_lc_nr1_terms_fx_pa_growth_avg_formula)
    def pv_lc_nr1_terms_fx_pa_formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if time_period <= 2044:
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])
        return as_measure(xl_mul(pv_lc_nr1_terms_fx_pa[instrument, holder, time_period - 1], xl_add(1, pv_lc_nr1_terms_fx_pa_growth_avg[()])))

    pv_lc_nr1_terms_fx_pa = CoordinateReader('pv_lc_nr1_terms_fx_pa', data.PV_LC_NR1_TERMS_FX_PA_REQUIRED, pv_lc_nr1_terms_fx_pa_formula)
    return ScanPvLcNr1TermsFxPaGrowthResult(
        pv_lc_nr1_terms_fx_pa_growth=data.PvLcNr1TermsFxPaGrowth.collect((coord, pv_lc_nr1_terms_fx_pa_growth[coord]) for coord in data.PV_LC_NR1_TERMS_FX_PA_GROWTH_REQUIRED),
        pv_lc_nr1_terms_fx_pa_growth_avg=pv_lc_nr1_terms_fx_pa_growth_avg[()],
        pv_lc_nr1_terms_fx_pa=data.PvLcNr1TermsFxPa.collect((coord, pv_lc_nr1_terms_fx_pa[coord]) for coord in data.PV_LC_NR1_TERMS_FX_PA_REQUIRED),
    )

@publish(data.PV_LC_NR1_TERMS_PROJECTION_YEAR_SCHEMA, cells=data.PV_LC_NR1_TERMS_PROJECTION_YEAR_CELLS)
def pv_lc_nr1_terms_projection_year(*, macro_debt_data: int | str) -> data.PvLcNr1TermsProjectionYear:
    """Build the pv_lc NR1 terms projection-year coordinate series.

    Derive the projection-year values for local-currency PV terms from a macro-debt-data anchor and return them as a catalog-coordinate tensor.

    Args:
        macro_debt_data: Scalar int or str base value used as the 2024 projection-year anchor; each subsequent time period is computed by incrementing the prior period by one.

    Returns:
        A data.PvLcNr1TermsProjectionYear typed series mapping pv_lc coordinates to projection-year values, lifted from the pv_lc.terms internal series for Bonds (1 to 3 years)-LC held by non-residents.
    """
    def formula(instrument: str, holder: str, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(xl_add(pv_lc_nr1_terms_projection_year[instrument, holder, time_period - 1], 1), 'int')

    pv_lc_nr1_terms_projection_year = CoordinateReader('pv_lc_nr1_terms_projection_year', data.PV_LC_NR1_TERMS_PROJECTION_YEAR_REQUIRED, formula)
    return data.PvLcNr1TermsProjectionYear.collect((coord, pv_lc_nr1_terms_projection_year[coord]) for coord in data.PV_LC_NR1_TERMS_PROJECTION_YEAR_REQUIRED)

@publish(data.PV_LC_NR1_TERMS_FX_EOP_SCHEMA, cells=data.PV_LC_NR1_TERMS_FX_EOP_CELLS)
def pv_lc_nr1_terms_fx_eop(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.MacroDebtExchangeRateNationalCurrencyPerUSDollar, pv_lc_nr1_terms_fx_pa_growth_avg: float | str) -> data.PvLcNr1TermsFxEop:
    """Compute the end-of-period FX rate for the PV of local-currency non-resident 1–3 year bond terms.

    Derive the end-of-period FX series by taking the macro exchange rate through 2044 and rolling it forward with an average growth rate.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: The macro-debt exchange-rate series expressed in national currency per U.S. dollar, providing the base end-of-period FX rate by time period.
        pv_lc_nr1_terms_fx_pa_growth_avg: The average annual growth rate applied to carry the end-of-period FX value forward after 2044, supplied as a scalar or string.

    Returns:
        A data.PvLcNr1TermsFxEop series of end-of-period FX rates over the required instrument, holder, and time-period coordinates.
    """
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if time_period <= 2044:
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(xl_mul(pv_lc_nr1_terms_fx_eop[instrument, holder, time_period - 1], xl_add(1, pv_lc_nr1_terms_fx_pa_growth_avg)))

    pv_lc_nr1_terms_fx_eop = CoordinateReader('pv_lc_nr1_terms_fx_eop', data.PV_LC_NR1_TERMS_FX_EOP_REQUIRED, formula)
    return data.PvLcNr1TermsFxEop.collect((coord, pv_lc_nr1_terms_fx_eop[coord]) for coord in data.PV_LC_NR1_TERMS_FX_EOP_REQUIRED)

@publish(data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY_SCHEMA, cells=data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY_CELLS)
def pv_lc_terms_interest_rate_local_currency(*, input5_internal_interest_rate_on_domestic_debt: data.Input5InternalInterestRateOnDomesticDebt) -> data.PvLcTermsInterestRateLocalCurrency:
    """Derives local-currency PV terms interest rate series from Input 5 domestic debt interest rates.

    Reindexes the Input 5 internal interest rate on domestic debt onto the PV_LC terms coordinate set, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3.

    Args:
        input5_internal_interest_rate_on_domestic_debt: data.Input5InternalInterestRateOnDomesticDebt series holding internal interest rates on domestic debt by instrument and holder over time periods, read on the 'non-residents' holder axis.

    Returns:
        data.PvLcTermsInterestRateLocalCurrency series of local-currency PV terms interest rates keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3.
    """
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC':
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (1 to 3 years)-LC', 'non-residents', time_period])
        elif instrument == 'Bonds (4 to 7 years)-LC':
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (4 to 7 years)-LC', 'non-residents', time_period])
        return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (beyond 7 years)-LC', 'non-residents', time_period])

    return data.PvLcTermsInterestRateLocalCurrency.collect(evaluate(formula, data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY_REQUIRED))

