@publish(data.PV_LC_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_SCHEMA, cells=data.PV_LC_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_CELLS)
def pv_lc_output_total_debt_service_in_usd(*, pv_lc_output_interest_in_usd: data.PvLcOutputInterestInUsd, pv_lc_output_amortization_in_usd: data.PvLcOutputAmortizationInUsd) -> data.PvLcOutputTotalDebtServiceInUsd:
    """Compute total PV_LC debt service in USD as the per-instrument sum of interest and amortization.

    Combine the interest and amortization output series into a single total debt-service series for the LIC-DSF public debt charts.

    Args:
        pv_lc_output_interest_in_usd: Named-axis series of PV_LC interest paid in USD, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, PV_LC_NR3.
        pv_lc_output_amortization_in_usd: Named-axis series of PV_LC principal amortization paid in USD, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, PV_LC_NR3.

    Returns:
        Named-axis series of total debt service in USD, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, PV_LC_NR3.
    """
    def formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> float | str | None:
        if issuance_year == 2024:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2024, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2024, time_period]))
        elif issuance_year == 2025:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2025, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2025, time_period]))
        elif issuance_year == 2026:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2026, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2026, time_period]))
        elif issuance_year == 2027:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2027, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2027, time_period]))
        elif issuance_year == 2028:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2028, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2028, time_period]))
        elif issuance_year == 2029:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2029, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2029, time_period]))
        elif issuance_year == 2030:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2030, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2030, time_period]))
        elif issuance_year == 2031:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2031, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2031, time_period]))
        elif issuance_year == 2032:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2032, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2032, time_period]))
        elif issuance_year == 2033:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2033, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2033, time_period]))
        elif issuance_year == 2034:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2034, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2034, time_period]))
        elif issuance_year == 2035:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2035, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2035, time_period]))
        elif issuance_year == 2036:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2036, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2036, time_period]))
        elif issuance_year == 2037:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2037, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2037, time_period]))
        elif issuance_year == 2038:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2038, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2038, time_period]))
        elif issuance_year == 2039:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2039, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2039, time_period]))
        elif issuance_year == 2040:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2040, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2040, time_period]))
        elif issuance_year == 2041:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2041, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2041, time_period]))
        elif issuance_year == 2042:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2042, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2042, time_period]))
        elif issuance_year == 2043:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2043, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2043, time_period]))
        return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2044, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2044, time_period]))

