@publish(key=('INSTRUMENT',), domain=None, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_USD_DISCOUNT_RATE_CELLS)
def pv_resfin_add_assumptions_usd_discount_rate(*, discount_rate: float | str) -> float | str:
    """USD discount rate assumption for PV resfin add-assumptions (External MLT debt).

    Provide the scalar discount rate for the PV resfin add-assumptions calculation, coercing it to a measure and returning the error code on failure.

    Args:
        discount_rate: Raw USD discount rate value as a scalar number or string; coerced to a numeric measure.

    Returns:
        The discount rate as a float measure, or the XlError code as a string if coercion fails.
    """
    try:
        return as_measure(discount_rate)
    except XlError as error:
        return error.code

@publish(data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD_SCHEMA, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD_CELLS)
def pv_resfin_add_assumptions_avg_maturity_incl_grace_period(*, in7_resfin_dom_mlt_effective: data.In7ResfinDomMltEffective, in7_resfin_ext_mlt_effective: data.In7ResfinExtMltEffective) -> data.PvResfinAddAssumptionsAvgMaturityInclGracePeriod:
    """Compute residual-financing add-assumptions average maturity including grace period.

    Derives the average maturity including grace period for domestic and external MLT debt under residual financing assumptions.

    Args:
        in7_resfin_dom_mlt_effective: Effective domestic MLT debt as a named-axis data tensor over catalog coordinates, supplying the Avg. maturity (incl. grace period) values that are rounded down to whole years.
        in7_resfin_ext_mlt_effective: Effective external MLT debt as a named-axis data tensor over catalog coordinates, supplying the Avg. maturity (incl. grace period) values used directly.

    Returns:
        A typed data.PvResfinAddAssumptionsAvgMaturityInclGracePeriod series over the required instruments, containing average maturity including grace period for Domestic MLT debt (rounded down) and External MLT debt.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. maturity (incl. grace period)'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. maturity (incl. grace period)'], 0))

    return data.PvResfinAddAssumptionsAvgMaturityInclGracePeriod.collect(evaluate(formula, data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD_REQUIRED))

@publish(data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD_SCHEMA, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD_CELLS)
def pv_resfin_add_assumptions_avg_grace_period(*, in7_resfin_dom_mlt_effective: data.In7ResfinDomMltEffective, in7_resfin_ext_mlt_effective: data.In7ResfinExtMltEffective) -> data.PvResfinAddAssumptionsAvgGracePeriod:
    """Assembles the residual-financing addition-assumptions average grace period series for domestic and external MLT debt instruments.

    Lifts each instrument's average grace period from the Input 7 residual-financing effectiveness series so the addition-assumptions block exposes a single two-instrument average grace period series.

    Args:
        in7_resfin_dom_mlt_effective: Domestic MLT debt residual-financing effectiveness series on Input 7; its `Avg. grace period` coordinate is read and truncated toward zero to whole years.
        in7_resfin_ext_mlt_effective: External MLT debt residual-financing effectiveness series on Input 7; its `Avg. grace period` coordinate is read as-is, without rounding.

    Returns:
        `data.PvResfinAddAssumptionsAvgGracePeriod` series of average grace period values keyed by the two MLT debt instruments (Domestic MLT debt, External MLT debt).
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. grace period'], 0))

    return data.PvResfinAddAssumptionsAvgGracePeriod.collect(evaluate(formula, data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD_REQUIRED))

@publish(data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX_SCHEMA, cells=data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX_CELLS)
def pv_resfin_add_projection_years_period_index(*, pv_resfin_add_opening_stock_period_seed: int | str) -> data.PvResfinAddProjectionYearsPeriodIndex:
    """Compute the PV_ResFin-add projection-years period index.

    Derive the period-index coordinate series from the opening-stock period seed.

    Args:
        pv_resfin_add_opening_stock_period_seed: Opening stock period seed as an integer or string.

    Returns:
        A `data.PvResfinAddProjectionYearsPeriodIndex` series containing the period-index axis (0, 1, …) for PV_ResFin-add projection years.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 1:
            return as_measure(xl_add(pv_resfin_add_opening_stock_period_seed, 1), 'int')
        return as_measure(xl_add(pv_resfin_add_projection_years_period_index[time_period - 1], 1), 'int')

    pv_resfin_add_projection_years_period_index = CoordinateReader('pv_resfin_add_projection_years_period_index', data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX_REQUIRED, formula)
    return data.PvResfinAddProjectionYearsPeriodIndex.collect((coord, pv_resfin_add_projection_years_period_index[coord]) for coord in data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX_REQUIRED)

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW_SCHEMA, cells=data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW_CELLS)
def pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window(*, pv_resfin_add_output_stock_of_new_forex_debt_in_usd: data.PvResfinAddOutputStockOfNewForexDebtInUsd, pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window: data.PvResfinAddIntCostMktAmortizationBeyondProjectionWindow) -> data.PvResfinAddIntCostMktStockOfNewForexDebtBeyondProjectionWindow:
    """Compute the stock of new external PPG medium- and long-term forex debt beyond the projection window by rolling forward an initial stock and subtracting amortization beyond the projection window.

    Supports residual-financing calculations for external PPG medium- and long-term debt under the Bounds Test 2: Primary Balance Shock for Market Access Countries scenario.

    Args:
        pv_resfin_add_output_stock_of_new_forex_debt_in_usd: Residual-output series of the stock of new external PPG medium- and long-term forex debt in USD under the Bounds Test 2: Primary Balance Shock for Market Access Countries scenario.
        pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window: Series of interest-cost market amortization beyond the projection window for external PPG medium- and long-term debt under the Bounds Test 2: Primary Balance Shock for Market Access Countries scenario.

    Returns:
        data.PvResfinAddIntCostMktStockOfNewForexDebtBeyondProjectionWindow series containing the recursively accumulated stock of new external PPG medium- and long-term forex debt beyond the projection window, after subtracting amortization beyond the projection window.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if time_period == 26:
            return as_measure(xl_sub(xl_add(pv_resfin_add_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period + 2023], None), pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))
        return as_measure(xl_sub(xl_add(pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period - 1], None), pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))

    pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window = CoordinateReader('pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window', data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW_REQUIRED, formula)
    return data.PvResfinAddIntCostMktStockOfNewForexDebtBeyondProjectionWindow.collect((coord, pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window[coord]) for coord in data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW_REQUIRED)

