@publish(data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS_SCHEMA, cells=data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS_CELLS)
def pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years(*, pv_resfin_add_assumptions_additional_borrowing_costs_domestic: float | str, pv_resfin_add_assumptions_deviation_in_pb_ppt: data.PvResfinAddAssumptionsDeviationInPbPpt) -> data.PvResfinAddIntCostMktAdditionalDomesticInterestRateShockYears:
    """Derive the additional domestic interest-rate cost of a market-financing shock from the additional domestic borrowing-cost assumption and the primary-balance deviation shock path.

    Scale the additional domestic borrowing-cost assumption by each Bounds Test 2/6 primary-balance deviation to produce the per-period market-shock interest-cost series.

    Args:
        pv_resfin_add_assumptions_additional_borrowing_costs_domestic: Additional domestic borrowing-cost assumption, given either as a numeric scalar or a string sentinel; treated as a basis-point rate and divided by 10,000 to yield the decimal multiplier applied to each deviation value.
        pv_resfin_add_assumptions_deviation_in_pb_ppt: Deviation in primary balance (percentage points) as a data series over the catalog coordinates, supplying the per-scenario, per-period shock magnitudes for the four Bounds Test 2 and Bounds Test 6 variants.

    Returns:
        A typed data series of additional domestic interest-rate costs for the market-financing shock, indexed by instrument (domestic medium and long-term) and scenario (Bounds Test 2 primary-balance shocks and Bounds Test 6 combined shocks, both market-access and non-market-access) across the unified time periods.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Bounds Test 2: Primary Balance Shock for Market Access Countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))
        elif scenario == 'Bounds Test 2: Primary Balance Shock for non-market access countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 6: Combined Shock for Market Access Countries', time_period]))
        return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]))

    return data.PvResfinAddIntCostMktAdditionalDomesticInterestRateShockYears.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS_REQUIRED))

@publish(data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION_SCHEMA, cells=data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION_CELLS)
def pv_resfin_add_output_t_m_condition(*, pv_resfin_add_assumptions_avg_maturity_incl_grace_period: data.PvResfinAddAssumptionsAvgMaturityInclGracePeriod, pv_resfin_add_opening_stock_period_seed: int | str, pv_resfin_add_projection_years_period_index: data.PvResfinAddProjectionYearsPeriodIndex) -> data.PvResfinAddOutputTMCondition:
    """Compute the t-m condition for the residual financing add-on.

    Derives the t-m condition output from average maturity including grace period, opening stock period seed, and projection-year period index.

    Args:
        pv_resfin_add_assumptions_avg_maturity_incl_grace_period: Named-axis data series of average maturity including grace period assumptions, indexed by instrument (domestic MLT debt and external PPG MLT debt), used to offset opening-stock seeds and projection-year period indices.
        pv_resfin_add_opening_stock_period_seed: Scalar opening-stock period seed, either int or str, serving as the base value from which average maturity including grace period is subtracted for 2024 conditions.
        pv_resfin_add_projection_years_period_index: Named-axis data series of projection-year period indices over catalog coordinates, indexed by the offset from 2024 for projection years from 2025 onward.

    Returns:
        Typed data.PvResfinAddOutputTMCondition result containing the t-m condition across instruments, stress-test scenarios, and projection periods, including the bounding rectangle cells on member rows.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        if instrument == 'External PPG medium and long-term' and scenario in ('Bounds Test 2: Primary Balance Shock for Market Access Countries', 'Bounds Test 6: Combined Shock for Market Access Countries') and time_period == 2024:
            return as_measure((xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']) if xl_gt(xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']), 0) else 0), 'int')
        elif instrument == 'Domestic medium and long-term' and time_period == 2024:
            return as_measure((xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period['Domestic MLT debt']) if xl_gt(xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period['Domestic MLT debt']), 0) else 0), 'int')
        elif instrument == 'External PPG medium and long-term' and scenario in ('Bounds Test 2: Primary Balance Shock for Market Access Countries', 'Bounds Test 6: Combined Shock for Market Access Countries') and time_period >= 2025:
            return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']) if xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']), 0) else 0), 'int')
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['Domestic MLT debt']) if xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['Domestic MLT debt']), 0) else 0), 'int')

    return data.PvResfinAddOutputTMCondition.collect(evaluate(formula, data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION_REQUIRED))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW_SCHEMA, cells=data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW_CELLS)
def pv_resfin_add_int_cost_mkt_t_m_condition_beyond_projection_window(*, pv_resfin_add_assumptions_avg_maturity_incl_grace_period: data.PvResfinAddAssumptionsAvgMaturityInclGracePeriod, pv_resfin_add_projection_years_period_index: data.PvResfinAddProjectionYearsPeriodIndex) -> data.PvResfinAddIntCostMktTMConditionBeyondProjectionWindow:
    """Lift the interest-cost t-m condition beyond the projection window into a named-axis series.

    Derive the beyond-projection-window condition by comparing the projection-year period index against average maturity including grace period, clamped to a non-negative integer.

    Args:
        pv_resfin_add_assumptions_avg_maturity_incl_grace_period: Named-axis tensor over catalog coordinates holding the average maturity including grace period for the External MLT debt instrument, used as the maturity offset in the projection-year comparison.
        pv_resfin_add_projection_years_period_index: Named-axis tensor over catalog coordinates holding the projection-year period index, whose per-period values are compared against average maturity to test whether the horizon extends beyond the projection window.

    Returns:
        Named-axis tensor over catalog coordinates holding the t-m condition beyond the projection window as an integer per instrument, scenario, and time period, equal to the positive projection-year-minus-maturity offset and zero when that offset is not positive.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']) if xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']), 0) else 0), 'int')

    return data.PvResfinAddIntCostMktTMConditionBeyondProjectionWindow.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW_REQUIRED))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE_SCHEMA, cells=data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE_CELLS)
def pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_two_year_average(*, pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years: data.PvResfinAddIntCostMktAdditionalDomesticInterestRateShockYears) -> data.PvResfinAddIntCostMktAdditionalDomesticInterestRateTwoYearAverage:
    """Computes the two-year average additional domestic interest rate shock for domestic medium and long-term debt.

    Aggregates 2025 and 2026 additional domestic interest rate shock values into a two-year average series for market-financing cost calculations.

    Args:
        pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years: Additional domestic interest rate shock years series for domestic medium and long-term debt, represented as a named-axis data.PvResfinAddIntCostMktAdditionalDomesticInterestRateShockYears tensor over scenario and TIME_PERIOD coordinates.

    Returns:
        A data.PvResfinAddIntCostMktAdditionalDomesticInterestRateTwoYearAverage series containing the 2025–2026 average additional domestic interest rate shock per scenario.
    """
    def formula(scenario: str) -> float | str | None:
        return as_measure(xl_average(pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years['Domestic medium and long-term', scenario, 2025], pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years['Domestic medium and long-term', scenario, 2026]))

    return data.PvResfinAddIntCostMktAdditionalDomesticInterestRateTwoYearAverage.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE_REQUIRED))

