@publish(data.PV_BASELINE_COM_PV_DEBT_SCHEMA, cells=data.PV_BASELINE_COM_PV_DEBT_CELLS)
def pv_baseline_com_pv_debt(*, pv_baseline_com_output_pv_of_debt: data.PvBaselineComOutputPvOfDebt) -> data.PvBaselineComPvDebt:
    """Aggregates the PV of public and publicly guaranteed debt under the baseline commercial scenario.

    Sums the individual commercial creditor series into the consolidated PV-of-debt series used by the baseline commercial debt accumulation engine.

    Args:
        pv_baseline_com_output_pv_of_debt: `data.PvBaselineComOutputPvOfDebt` series of per-creditor PV-of-debt amounts over catalog coordinates, whose instrument components are summed across time periods.

    Returns:
        `data.PvBaselineComPvDebt` series holding the total PV of debt for the commercial instrument set, expressed as a named-axis tensor over catalog coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_baseline_com_output_pv_of_debt['Eurobond', time_period], pv_baseline_com_output_pv_of_debt['Commecial Bank', time_period]), pv_baseline_com_output_pv_of_debt['COM3', time_period]), pv_baseline_com_output_pv_of_debt['COM4', time_period]), pv_baseline_com_output_pv_of_debt['COM5', time_period]))

    return data.PvBaselineComPvDebt.collect(evaluate(formula, data.PV_BASELINE_COM_PV_DEBT_REQUIRED))

@publish(data.PV_BASELINE_COM_TOTAL_DEBT_SERVICE_SCHEMA, cells=data.PV_BASELINE_COM_TOTAL_DEBT_SERVICE_CELLS)
def pv_baseline_com_total_debt_service(*, pv_baseline_com_output_total_debt_service_in_usd: data.PvBaselineComOutputTotalDebtServiceInUsd) -> data.PvBaselineComTotalDebtService:
    """Compute baseline total commercial debt service in USD.

    Aggregate baseline commercial debt-service output components into the LIC-DSF total commercial debt-service series.

    Args:
        pv_baseline_com_output_total_debt_service_in_usd: Typed data.PvBaselineComOutputTotalDebtServiceInUsd series holding baseline commercial output total debt service in USD by instrument and time period.

    Returns:
        Typed data.PvBaselineComTotalDebtService series of total commercial debt service in USD, keyed by time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_baseline_com_output_total_debt_service_in_usd['Eurobond', time_period], pv_baseline_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), pv_baseline_com_output_total_debt_service_in_usd['COM3', time_period]), pv_baseline_com_output_total_debt_service_in_usd['COM4', time_period]), pv_baseline_com_output_total_debt_service_in_usd['COM5', time_period]))

    return data.PvBaselineComTotalDebtService.collect(evaluate(formula, data.PV_BASELINE_COM_TOTAL_DEBT_SERVICE_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_PERIOD_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_PERIOD_CELLS)
def pv_baseline_com_discount_period(*, pv_baseline_com_discount_schedule_period: int | str) -> data.PvBaselineComDiscountPeriod:
    """Compute the baseline commercial PV discount-period series.

    Derives the discount-period schedule used for PV baseline commercial discounting from an initial discount schedule period.

    Args:
        pv_baseline_com_discount_schedule_period: Keyword-only scalar discount schedule period, as an int or str, supplying the initial Eurobond period that anchors the baseline commercial discount-period sequence.

    Returns:
        The computed data.PvBaselineComDiscountPeriod series keyed by instrument and period, with the Eurobond discount period laddering forward by one each year from the supplied anchor and the other commercial instruments mapping to the corresponding Eurobond period.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond' and time_period == 2024:
            return as_measure(pv_baseline_com_discount_schedule_period, 'int')
        elif instrument == 'Eurobond' and time_period == 2025:
            return as_measure(xl_add(pv_baseline_com_discount_period[instrument, time_period - 1], 1), 'int')
        elif instrument == 'Eurobond' and time_period >= 2026:
            return as_measure(xl_add(pv_baseline_com_discount_period['Eurobond', time_period - 1], 1), 'int')
        return as_measure(pv_baseline_com_discount_period['Eurobond', time_period], 'int')

    pv_baseline_com_discount_period = CoordinateReader('pv_baseline_com_discount_period', data.PV_BASELINE_COM_DISCOUNT_PERIOD_REQUIRED, formula)
    return data.PvBaselineComDiscountPeriod.collect((coord, pv_baseline_com_discount_period[coord]) for coord in data.PV_BASELINE_COM_DISCOUNT_PERIOD_REQUIRED)

