@publish(data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION_CELLS)
def pv_baseline_com_discount_amortization(*, pv_baseline_com_discount_period: data.PvBaselineComDiscountPeriod, pv_baseline_com_grace: data.PvBaselineComGrace, pv_baseline_com_maturity: data.PvBaselineComMaturity, pv_baseline_com_opening_percent_of_face: data.PvBaselineComOpeningPercentOfFace) -> data.PvBaselineComDiscountAmortization:
    """Computes baseline commercial discount-schedule amortization across the five instruments and projection time periods.

    Derive each instrument's straight-line amortization of the opening percent of face over its discounting window, zero outside that window.

    Args:
        pv_baseline_com_discount_period: data.PvBaselineComDiscountPeriod named-axis series over the (instrument, time_period) coordinates; supplies each instrument's discount period used to offset the amortization window against the 2024 base year.
        pv_baseline_com_grace: data.PvBaselineComGrace per-instrument series giving the grace period, in periods, before amortization begins.
        pv_baseline_com_maturity: data.PvBaselineComMaturity per-instrument series giving the maturity period that bounds the end of the amortization window.
        pv_baseline_com_opening_percent_of_face: data.PvBaselineComOpeningPercentOfFace per-instrument series giving the opening percent of face amortized evenly over the discounted periods between grace and maturity.

    Returns:
        A data.PvBaselineComDiscountAmortization named-axis series over the (instrument, time_period) coordinates of the discount schedule: zero before grace and at/after maturity, and the per-period percent-of-face amortization within the window.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE_SCHEMA.validate(pv_baseline_com_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_grace['Eurobond']) else (xl_div(pv_baseline_com_opening_percent_of_face['Eurobond'], xl_sub(pv_baseline_com_maturity['Eurobond'], pv_baseline_com_grace['Eurobond'])) if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_maturity['Eurobond']) else 0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_grace['Commecial Bank']) else (xl_div(pv_baseline_com_opening_percent_of_face['Commecial Bank'], xl_sub(pv_baseline_com_maturity['Commecial Bank'], pv_baseline_com_grace['Commecial Bank'])) if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_maturity['Commecial Bank']) else 0)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_grace['COM3']) else (xl_div(pv_baseline_com_opening_percent_of_face['COM3'], xl_sub(pv_baseline_com_maturity['COM3'], pv_baseline_com_grace['COM3'])) if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_maturity['COM3']) else 0)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_grace['COM4']) else (xl_div(pv_baseline_com_opening_percent_of_face['COM4'], xl_sub(pv_baseline_com_maturity['COM4'], pv_baseline_com_grace['COM4'])) if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_maturity['COM4']) else 0)))
        return as_measure((0 if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_grace['COM5']) else (xl_div(pv_baseline_com_opening_percent_of_face['COM5'], xl_sub(pv_baseline_com_maturity['COM5'], pv_baseline_com_grace['COM5'])) if xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_maturity['COM5']) else 0)))

    return data.PvBaselineComDiscountAmortization.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE_CELLS)
def pv_baseline_com_discount_discount_rate(*, input4_discount_rate: data.Input4DiscountRate) -> data.PvBaselineComDiscountDiscountRate:
    """Build the baseline commercial discount-rate series for the PV baseline COM block from Input 4 discount-rate assumptions.

    Evaluate the authored coordinate identity that maps each required instrument’s Input 4 discount rate to the corresponding pv_baseline_com.terms Discount rate series.

    Args:
        input4_discount_rate: data.Input4DiscountRate named-axis input series containing discount-rate assumptions by instrument (COM3, COM4, COM5, Commecial Bank, Eurobond).

    Returns:
        data.PvBaselineComDiscountDiscountRate typed series giving the baseline commercial discount rate for each required instrument on pv_baseline_com.terms.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(input4_discount_rate[instrument])

    return data.PvBaselineComDiscountDiscountRate.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_INTEREST_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_INTEREST_CELLS)
def pv_baseline_com_discount_interest(*, pv_baseline_com_discount_debt_stock: data.PvBaselineComDiscountDebtStock, pv_baseline_com_discount_interest_rate: data.PvBaselineComDiscountInterestRate) -> data.PvBaselineComDiscountInterest:
    """Compute baseline commercial discount interest from debt stock and interest rate.

    Calculates per-instrument interest on the prior-period discount debt stock using the corresponding discount interest rate.

    Args:
        pv_baseline_com_discount_debt_stock: Typed data series of discount debt stock (data.PvBaselineComDiscountDebtStock) keyed by instrument (COM3, COM4, COM5, Commecial Bank, Eurobond) and time period.
        pv_baseline_com_discount_interest_rate: Typed data series of discount interest rates (data.PvBaselineComDiscountInterestRate) keyed by instrument.

    Returns:
        Typed data series of computed interest (data.PvBaselineComDiscountInterest) keyed by instrument and time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Eurobond'], pv_baseline_com_discount_debt_stock['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Commecial Bank'], pv_baseline_com_discount_debt_stock['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM3'], pv_baseline_com_discount_debt_stock['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM4'], pv_baseline_com_discount_debt_stock['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM5'], pv_baseline_com_discount_debt_stock['COM5', time_period - 1]))

    return data.PvBaselineComDiscountInterest.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_INTEREST_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE_CELLS)
def pv_baseline_com_discount_total_debt_service(*, pv_baseline_com_discount_amortization: data.PvBaselineComDiscountAmortization, pv_baseline_com_discount_interest: data.PvBaselineComDiscountInterest) -> data.PvBaselineComDiscountTotalDebtService:
    """Compute baseline commercial discount total debt service.

    Adds baseline commercial discount amortization and interest per instrument, yielding the total debt service series.

    Args:
        pv_baseline_com_discount_amortization: Baseline commercial discount amortization series over instrument and time-period catalog coordinates.
        pv_baseline_com_discount_interest: Baseline commercial discount interest series over instrument and time-period catalog coordinates.

    Returns:
        Total debt service data series for the baseline commercial discount schedule, covering the five instruments over catalog coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Eurobond', time_period], pv_baseline_com_discount_interest['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Commecial Bank', time_period], pv_baseline_com_discount_interest['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM3', time_period], pv_baseline_com_discount_interest['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM4', time_period], pv_baseline_com_discount_interest['COM4', time_period]))
        return as_measure(xl_add(pv_baseline_com_discount_amortization['COM5', time_period], pv_baseline_com_discount_interest['COM5', time_period]))

    return data.PvBaselineComDiscountTotalDebtService.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT_CELLS)
def pv_baseline_com_discount_pv_of_debt(*, pv_baseline_com_discount_debt_stock: data.PvBaselineComDiscountDebtStock, pv_baseline_com_discount_interest_rate: data.PvBaselineComDiscountInterestRate, pv_baseline_com_discount_discount_rate: data.PvBaselineComDiscountDiscountRate, pv_baseline_com_discount_total_debt_service: data.PvBaselineComDiscountTotalDebtService) -> data.PvBaselineComDiscountPvOfDebt:
    """Computes the present value of debt for the baseline commercial discount schedule.

    Derives per-instrument PV of debt by using debt stock when the interest rate covers the discount rate and otherwise discounting remaining total debt service.

    Args:
        pv_baseline_com_discount_debt_stock: Baseline commercial discount debt stock series by instrument and time period.
        pv_baseline_com_discount_interest_rate: Baseline commercial discount interest rate series by instrument.
        pv_baseline_com_discount_discount_rate: Baseline commercial discount discount rate series by instrument.
        pv_baseline_com_discount_total_debt_service: Baseline commercial discount total debt service series by instrument and time period, used for remaining-horizon NPV calculations.

    Returns:
        A data.PvBaselineComDiscountPvOfDebt series giving the per-instrument, per-period present value of debt under the baseline commercial discount schedule.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure((pv_baseline_com_discount_debt_stock[instrument, time_period] if xl_ge(pv_baseline_com_discount_interest_rate[instrument], pv_baseline_com_discount_discount_rate[instrument]) else xl_npv(pv_baseline_com_discount_discount_rate[instrument], view(pv_baseline_com_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS_60, time_period + 1, 2063)))))

    return data.PvBaselineComDiscountPvOfDebt.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_T_G_0_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_T_G_0_CELLS)
def pv_baseline_com_discount_t_g_0(*, pv_baseline_com_discount_period: data.PvBaselineComDiscountPeriod, pv_baseline_com_grace: data.PvBaselineComGrace) -> data.PvBaselineComDiscountTG0:
    """Computes the non-negative excess of each instrument's discount period over its grace period, per catalog coordinate.

    Derives the t-g>0 discount remainder used by the baseline commercial discount schedule when the grace period is shorter than the discount period.

    Args:
        pv_baseline_com_discount_period: Named-axis tensor of discount periods indexed by instrument and time period across the commercial discount schedule catalog coordinates.
        pv_baseline_com_grace: Named-axis tensor of grace periods indexed by instrument, aligned to the same instrument catalog as the discount schedule.

    Returns:
        A data.PvBaselineComDiscountTG0 series over instruments and time periods holding the per-cell discount remainder where the discount period exceeds the grace period, and zero otherwise.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']) if xl_gt(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']), 0) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']) if xl_gt(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']), 0) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']) if xl_gt(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']), 0) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']) if xl_gt(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']), 0) else 0), 'int')
        return as_measure((xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']) if xl_gt(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']), 0) else 0), 'int')

    return data.PvBaselineComDiscountTG0.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_T_G_0_REQUIRED))

@publish(data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_G_0_SCHEMA, cells=data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_G_0_CELLS)
def pv_baseline_com_discount_cumulative_selected_by_t_g_0(*, pv_baseline_com_discount_t_g_0: data.PvBaselineComDiscountTG0, pv_baseline_com_output_cumulative: data.PvBaselineComOutputCumulative) -> data.PvBaselineComDiscountCumulativeSelectedByTG0:
    """Select cumulative baseline commercial discount values for instruments with t-g greater than zero.

    Map each instrument's positive t-g discount factor to its cumulative output value, yielding the selected cumulative discount series.

    Args:
        pv_baseline_com_discount_t_g_0: Named-axis series over instrument and time-period coordinates holding the per-period baseline commercial discount factors; a zero discards the entry, otherwise the value selects the corresponding cumulative output year.
        pv_baseline_com_output_cumulative: Named-axis series over instrument and projection-year coordinates supplying the cumulative output totals from which the per-instrument value is selected.

    Returns:
        Named-axis series of the selected cumulative discount amounts indexed by instrument and time period, aligned to the LIC-DSF baseline commercial discount schedule.
    """
