@publish(data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION_SCHEMA, cells=data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION_CELLS)
def pv_stress_com_discount_t_m_condition(*, pv_stress_com_discount_period: data.PvStressComDiscountPeriod, pv_stress_com_maturity: data.PvStressComMaturity) -> data.PvStressComDiscountTMCondition:
    """Compute the non-negative discount-period-minus-maturity condition for each community instrument.

    Derive the t-m condition series used by the PV stress common discount schedule by subtracting maturity from the discount period and flooring at zero.

    Args:
        pv_stress_com_discount_period: Named-axis series over community instruments and projection time periods supplying the discount-period coordinate values.
        pv_stress_com_maturity: Named-axis maturity series over community instruments, matched against the discount-period instrument coordinates for the subtraction.

    Returns:
        A `data.PvStressComDiscountTMCondition` named-axis series over instrument and time period giving the floored-at-zero integer difference between the discount period and maturity for COM3, COM4, COM5, Commecial Bank, and Eurobond.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_maturity['Eurobond']) if xl_gt(xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_maturity['Eurobond']), 0) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_maturity['Commecial Bank']) if xl_gt(xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_maturity['Commecial Bank']), 0) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_maturity['COM3']) if xl_gt(xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_maturity['COM3']), 0) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_maturity['COM4']) if xl_gt(xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_maturity['COM4']), 0) else 0), 'int')
        return as_measure((xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_maturity['COM5']) if xl_gt(xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_maturity['COM5']), 0) else 0), 'int')

    return data.PvStressComDiscountTMCondition.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION_REQUIRED))

@publish(data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION_SCHEMA, cells=data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION_CELLS)
def pv_stress_com_discount_cumulative_selected_by_t_m_condition(*, pv_stress_com_discount_t_m_condition: data.PvStressComDiscountTMCondition, pv_stress_com_output_cumulative: data.PvStressComOutputCumulative) -> data.PvStressComDiscountCumulativeSelectedByTMCondition:
    """Select cumulative discount-schedule values per instrument by t-m condition.

    Produces the cumulative discount series for each instrument, zeroing any instrument whose t-m condition is zero and otherwise choosing the cumulative output entry at the condition index.

    Args:
        pv_stress_com_discount_t_m_condition: Per-instrument, per-time-period t-m condition series used to select an entry from the cumulative output series; a condition equal to zero forces the selected value to zero.
        pv_stress_com_output_cumulative: Per-instrument cumulative output series over time periods whose entries are selected by the corresponding t-m condition value.

    Returns:
        A typed data.PvStressComDiscountCumulativeSelectedByTMCondition series holding, for each of the five instruments (COM3, COM4, COM5, Commecial Bank, Eurobond) and each time period, the cumulative discount value selected by t-m condition.
    """
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0 = view(pv_stress_com_output_cumulative, rows=('Eurobond',), cols=data.TIME_PERIOD_AXIS_61.keys)
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1 = view(pv_stress_com_output_cumulative, rows=('Commecial Bank',), cols=data.TIME_PERIOD_AXIS_61.keys)
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2 = view(pv_stress_com_output_cumulative, rows=('COM3',), cols=data.TIME_PERIOD_AXIS_61.keys)
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3 = view(pv_stress_com_output_cumulative, rows=('COM4',), cols=data.TIME_PERIOD_AXIS_61.keys)
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4 = view(pv_stress_com_output_cumulative, rows=('COM5',), cols=data.TIME_PERIOD_AXIS_61.keys)
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_eq(pv_stress_com_discount_t_m_condition['Eurobond', time_period], 0) else xl_choose_range(pv_stress_com_discount_t_m_condition['Eurobond', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0)), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_eq(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], 0) else xl_choose_range(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1)), 'int')
        elif instrument == 'COM3':
            return as_measure((0 if xl_eq(pv_stress_com_discount_t_m_condition['COM3', time_period], 0) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM3', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2)), 'int')
        elif instrument == 'COM4':
            return as_measure((0 if xl_eq(pv_stress_com_discount_t_m_condition['COM4', time_period], 0) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM4', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3)), 'int')
        return as_measure((0 if xl_eq(pv_stress_com_discount_t_m_condition['COM5', time_period], 0) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM5', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4)), 'int')

    return data.PvStressComDiscountCumulativeSelectedByTMCondition.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION_REQUIRED))

@publish(data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD_CELLS)
def pv_stress_com_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal) -> data.PvStressComOutputNewForexBorrowingGrossUsd:
    """Lift gross new forex borrowing (USD) by instrument into the PV-stress COM output series.

    Reindex external new-disbursement amounts onto the PV-stress COM new-loan-output coordinates.

    Args:
        ext_debt_new_disbursements_external: data.ExtDebtNewDisbursementsExternal series of external new disbursements over instrument (COM3, COM4, COM5, Commercial Bank, Eurobond) and time period, providing the gross new forex borrowing values to be copied.

    Returns:
        data.PvStressComOutputNewForexBorrowingGrossUsd series of gross new forex borrowing (USD) keyed by instrument and time period, with the Eurobond, Commercial Bank, and COM3–COM5 entries mirrored from the input.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PvStressComOutputNewForexBorrowingGrossUsd.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD_REQUIRED))

@publish(data.PV_STRESS_COM_OUTPUT_CUMULATIVE_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_CUMULATIVE_CELLS)
def pv_stress_com_output_cumulative(*, pv_stress_com_output_new_forex_borrowing_gross_usd: data.PvStressComOutputNewForexBorrowingGrossUsd) -> data.PvStressComOutputCumulative:
    """Compute cumulative new foreign-currency borrowing by instrument and projection year from the gross new forex borrowing series.

    Accumulate gross new foreign-currency borrowing over the LIC-DSF projection horizon to produce the cumulative borrowing path.

    Args:
        pv_stress_com_output_new_forex_borrowing_gross_usd: Gross new foreign-currency borrowing in USD as a typed data.PvStressComOutputNewForexBorrowingGrossUsd series over instrument (COM3, COM4, COM5, Commecial Bank, Eurobond) and TIME_PERIOD coordinates; each instrument row is summed from 2025 through the year preceding the target period, with the span length growing by one year per projection year.

    Returns:
        A data.PvStressComOutputCumulative series over the same instrument and TIME_PERIOD coordinates, holding each instrument's cumulative gross new foreign-currency borrowing in USD.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and time_period == 2028:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 1))))
        elif instrument == 'Eurobond' and time_period == 2029:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 2))))
        elif instrument == 'Eurobond' and time_period == 2030:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 3))))
        elif instrument == 'Eurobond' and time_period == 2031:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 4))))
        elif instrument == 'Eurobond' and time_period == 2032:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 5))))
        elif instrument == 'Eurobond' and time_period == 2033:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 6))))
        elif instrument == 'Eurobond' and time_period == 2034:
            return as_measure(xl_sum(view(pv_stress_com_output_new_forex_borrowing_gross_usd, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS_42, 2025, time_period - 7))))
