@publish(data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_CELLS)
def pv_stress_com_output_stock_of_new_forex_debt_in_usd(*, pv_stress_com_output_new_forex_borrowing_gross_usd: data.PvStressComOutputNewForexBorrowingGrossUsd, pv_stress_com_output_amortization: data.PvStressComOutputAmortization) -> data.PvStressComOutputStockOfNewForexDebtInUsd:
    """Compute the stock of new forex debt in USD from gross new forex borrowing and amortization.

    Roll forward each instrument's prior-period new forex debt stock by adding gross new forex borrowing and subtracting amortization across the projection horizon.

    Args:
        pv_stress_com_output_new_forex_borrowing_gross_usd: Gross new forex borrowing in USD, a named-axis data series over instruments and projection periods.
        pv_stress_com_output_amortization: Amortization in USD, a named-axis data series over instruments and projection periods.

    Returns:
        A data.PvStressComOutputStockOfNewForexDebtInUsd series giving the stock of new forex debt in USD for each instrument and period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_stress_com_output_amortization['COM4', time_period]))
        elif instrument == 'COM5' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]), pv_stress_com_output_amortization['COM5', time_period]))
        elif time_period == 2024:
            return as_measure(xl_sub(None, pv_stress_com_output_amortization[instrument, time_period]))
        elif time_period == 2025:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd[instrument, time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]), pv_stress_com_output_amortization[instrument, time_period]))
        elif instrument == 'Eurobond' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], None), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], None), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], None), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], None), pv_stress_com_output_amortization['COM4', time_period]))
        return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], None), pv_stress_com_output_amortization['COM5', time_period]))

    pv_stress_com_output_stock_of_new_forex_debt_in_usd = CoordinateReader('pv_stress_com_output_stock_of_new_forex_debt_in_usd', data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_REQUIRED, formula)
    return data.PvStressComOutputStockOfNewForexDebtInUsd.collect((coord, pv_stress_com_output_stock_of_new_forex_debt_in_usd[coord]) for coord in data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD_REQUIRED)

@publish(data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT_CELLS)
def pv_stress_com_output_pv_of_debt(*, pv_stress_com_discount_interest_rate: data.PvStressComDiscountInterestRate, pv_stress_com_discount_discount_rate: data.PvStressComDiscountDiscountRate, pv_stress_com_discount_pv_of_debt: data.PvStressComDiscountPvOfDebt, pv_stress_com_output_new_forex_borrowing_gross_usd: data.PvStressComOutputNewForexBorrowingGrossUsd, pv_stress_com_output_total_debt_service_in_usd: data.PvStressComOutputTotalDebtServiceInUsd, pv_stress_com_output_amortization: data.PvStressComOutputAmortization) -> data.PvStressComOutputPvOfDebt:
    """Roll forward the PV of debt per instrument for the PV Stress COM block.

    Compute the projected PV of debt by instrument from amortization, new gross forex borrowing, and total debt service under either the interest-rate or discount-rate regime.

    Args:
        pv_stress_com_discount_interest_rate: Discount interest rate over the instrument axis, compared against the discount rate to choose the interest-versus-discount roll-forward branch.
        pv_stress_com_discount_discount_rate: Discount rate over the instrument axis; when it falls below the discount interest rate the prior-period stock is capitalized at this rate.
        pv_stress_com_discount_pv_of_debt: Base-year (2024) PV of debt per instrument, the discount factor applied to new forex borrowing gross in later years.
        pv_stress_com_output_new_forex_borrowing_gross_usd: New gross external (forex) borrowing in USD for the period, added to the rolled-forward stock in the discount-rate branch.
        pv_stress_com_output_total_debt_service_in_usd: Total debt service in USD for the period, subtracted from the discounted roll-forward when the discount-rate branch applies.
        pv_stress_com_output_amortization: Amortization per instrument for the period, netted out of the prior-period PV of debt.

    Returns:
        A `data.PvStressComOutputPvOfDebt` named-axis series of PV of debt over the catalog coordinates, giving the projected path for each instrument (COM3, COM4, COM5, Commecial Bank, Eurobond).
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], pv_stress_com_output_amortization['Eurobond', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]) if xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period], pv_stress_com_discount_pv_of_debt['Eurobond', 2024]), 100))))
        elif instrument == 'Commecial Bank' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], pv_stress_com_output_amortization['Commecial Bank', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]) if xl_ge(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_discount_rate['Commecial Bank']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Commecial Bank'])), pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period], pv_stress_com_discount_pv_of_debt['Commecial Bank', 2024]), 100))))
        elif instrument == 'COM3' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], pv_stress_com_output_amortization['COM3', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]) if xl_ge(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_discount_rate['COM3']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM3'])), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period], pv_stress_com_discount_pv_of_debt['COM3', 2024]), 100))))
        elif instrument == 'COM4' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], pv_stress_com_output_amortization['COM4', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]) if xl_ge(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_discount_rate['COM4']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM4'])), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period], pv_stress_com_discount_pv_of_debt['COM4', 2024]), 100))))
        elif instrument == 'COM5' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], pv_stress_com_output_amortization['COM5', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]) if xl_ge(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_discount_discount_rate['COM5']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM5'])), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period], pv_stress_com_discount_pv_of_debt['COM5', 2024]), 100))))
        elif time_period == 2024:
            return as_measure((None if xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument]) else xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt[instrument, time_period]), 100)))
        elif time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt[instrument, time_period - 1], pv_stress_com_output_amortization[instrument, time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]) if xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument]) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt[instrument, time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate[instrument])), pv_stress_com_output_total_debt_service_in_usd[instrument, time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_stress_com_discount_pv_of_debt[instrument, 2024]), 100))))
        elif instrument == 'Eurobond' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], pv_stress_com_output_amortization['Eurobond', time_period]), None) if xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['Eurobond', 2024]), 100))))
        elif instrument == 'Commecial Bank' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], pv_stress_com_output_amortization['Commecial Bank', time_period]), None) if xl_ge(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_discount_rate['Commecial Bank']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Commecial Bank'])), pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['Commecial Bank', 2024]), 100))))
        elif instrument == 'COM3' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], pv_stress_com_output_amortization['COM3', time_period]), None) if xl_ge(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_discount_rate['COM3']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM3'])), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM3', 2024]), 100))))
        elif instrument == 'COM4' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], pv_stress_com_output_amortization['COM4', time_period]), None) if xl_ge(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_discount_rate['COM4']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM4'])), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM4', 2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], pv_stress_com_output_amortization['COM5', time_period]), None) if xl_ge(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_discount_discount_rate['COM5']) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM5'])), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM5', 2024]), 100))))

    pv_stress_com_output_pv_of_debt = CoordinateReader('pv_stress_com_output_pv_of_debt', data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT_REQUIRED, formula)
    return data.PvStressComOutputPvOfDebt.collect((coord, pv_stress_com_output_pv_of_debt[coord]) for coord in data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT_REQUIRED)

@publish(data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_CELLS)
def pv_stress_com_output_total_debt_service_in_usd(*, pv_stress_com_output_interest: data.PvStressComOutputInterest, pv_stress_com_output_amortization: data.PvStressComOutputAmortization) -> data.PvStressComOutputTotalDebtServiceInUsd:
    """Sums interest and amortization into per-instrument total debt service in USD.

    Produces the PV stress COM total debt service series needed by the LIC-DSF debt service projections.

    Args:
        pv_stress_com_output_interest: Interest payments in USD as a named-axis data series over instrument and time-period coordinates, covering COM3, COM4, COM5, Commercial Bank, and Eurobond.
        pv_stress_com_output_amortization: Amortization payments in USD as a named-axis data series over the same instrument and time-period coordinates.

    Returns:
        A data.PvStressComOutputTotalDebtServiceInUsd series giving, for each instrument and time period, the USD sum of interest and amortization.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_stress_com_output_interest['Eurobond', time_period], pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_stress_com_output_interest['Commecial Bank', time_period], pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_stress_com_output_interest['COM3', time_period], pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_stress_com_output_interest['COM4', time_period], pv_stress_com_output_amortization['COM4', time_period]))
        return as_measure(xl_add(pv_stress_com_output_interest['COM5', time_period], pv_stress_com_output_amortization['COM5', time_period]))

    return data.PvStressComOutputTotalDebtServiceInUsd.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_REQUIRED))

@publish(data.PV_STRESS_COM_OUTPUT_INTEREST_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_INTEREST_CELLS)
def pv_stress_com_output_interest(*, pv_stress_com_discount_interest_rate: data.PvStressComDiscountInterestRate, pv_stress_com_output_stock_of_new_forex_debt_in_usd: data.PvStressComOutputStockOfNewForexDebtInUsd) -> data.PvStressComOutputInterest:
    """Compute PV stress COM interest from prior-period new forex debt stock and per-instrument discount rates.

    Populate the PV stress commercial external debt interest output across the five COM instruments.

    Args:
        pv_stress_com_discount_interest_rate: A `data.PvStressComDiscountInterestRate` series of per-instrument discount interest rates indexed by instrument.
        pv_stress_com_output_stock_of_new_forex_debt_in_usd: A `data.PvStressComOutputStockOfNewForexDebtInUsd` series of the prior-period stock of new foreign-currency debt in USD, indexed by instrument and time period.

    Returns:
        A `data.PvStressComOutputInterest` series of computed interest amounts indexed by instrument and time period for COM3, COM4, COM5, Commecial Bank, and Eurobond.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1]))

    return data.PvStressComOutputInterest.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_INTEREST_REQUIRED))

@publish(data.PV_STRESS_COM_OUTPUT_AMORTIZATION_SCHEMA, cells=data.PV_STRESS_COM_OUTPUT_AMORTIZATION_CELLS)
def pv_stress_com_output_amortization(*, pv_stress_com_grace: data.PvStressComGrace, pv_stress_com_maturity: data.PvStressComMaturity, pv_stress_com_discount_cumulative_selected_by_t_g_0: data.PvStressComDiscountCumulativeSelectedByTG0, pv_stress_com_discount_cumulative_selected_by_t_m_condition: data.PvStressComDiscountCumulativeSelectedByTMCondition) -> data.PvStressComOutputAmortization:
    """Compute the PV Stress commercial-loan amortization output from grace, maturity, and cumulative discount-factor series.

    Derive each instrument's amortization as the grace-to-maturity ratio of two cumulative discount selections, collected into a coordinate-indexed output series.

    Args:
        pv_stress_com_grace: Named-axis series over catalog instrument coordinates giving each instrument's contractual grace period.
        pv_stress_com_maturity: Named-axis series over catalog instrument coordinates giving each instrument's contractual maturity.
        pv_stress_com_discount_cumulative_selected_by_t_g_0: Named-axis series over instrument and time-period coordinates giving the cumulative discount factor selected by time period under the g-equals-zero condition.
        pv_stress_com_discount_cumulative_selected_by_t_m_condition: Named-axis series over instrument and time-period coordinates giving the cumulative discount factor selected by time period under the maturity condition.

    Returns:
        A data.PvStressComOutputAmortization series holding the computed amortization per instrument and time period, lifted from the five internal Amortization series on pv_stress_com.new_loan_output (COM3, COM4, COM5, Commecial Bank, Eurobond).
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['Eurobond', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['Eurobond', time_period]), xl_sub(pv_stress_com_maturity['Eurobond'], pv_stress_com_grace['Eurobond'])))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['Commecial Bank', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['Commecial Bank', time_period]), xl_sub(pv_stress_com_maturity['Commecial Bank'], pv_stress_com_grace['Commecial Bank'])))
        elif instrument == 'COM3':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM3', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM3', time_period]), xl_sub(pv_stress_com_maturity['COM3'], pv_stress_com_grace['COM3'])))
        elif instrument == 'COM4':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM4', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM4', time_period]), xl_sub(pv_stress_com_maturity['COM4'], pv_stress_com_grace['COM4'])))
        return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM5', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM5', time_period]), xl_sub(pv_stress_com_maturity['COM5'], pv_stress_com_grace['COM5'])))

    return data.PvStressComOutputAmortization.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_AMORTIZATION_REQUIRED))

@publish(data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT_SCHEMA, cells=data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT_CELLS)
def pv_stress_average_interest_rate_new_debt(*, in7_resfin_ext_mlt_override: data.In7ResfinExtMltOverride, c4_mkt_fin_average_residual_interest: float | str) -> data.PvStressAverageInterestRateNewDebt:
    """Compute the average interest rate on new debt under PV Stress.

    Selects the historical-average new-borrowing rate from Input 7 overrides or falls back to residual market financing interest across PV stress scenarios.

    Args:
        in7_resfin_ext_mlt_override: Typed data.In7ResfinExtMltOverride series over catalog coordinates holding Input 7 residual-financing external multi-scenario overrides; the 'Avg. nominal interest rate on new borrowing in USD' coordinate supplies the historical-average scenario value.
        c4_mkt_fin_average_residual_interest: Scalar interest rate, supplied as a float or string, for average residual market financing when the historical-average scenario is not active.

    Returns:
        data.PvStressAverageInterestRateNewDebt series giving the average interest rate on new debt under PV Stress, keyed across paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. nominal interest rate on new borrowing in USD'])
        return as_measure(c4_mkt_fin_average_residual_interest)

    return data.PvStressAverageInterestRateNewDebt.collect(evaluate(formula, data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT_REQUIRED))

@publish(data.PV_STRESS_USD_DISCOUNT_RATE_SCHEMA, cells=data.PV_STRESS_USD_DISCOUNT_RATE_CELLS)
def pv_stress_usd_discount_rate(*, in7_resfin_ext_mlt_override: data.In7ResfinExtMltOverride) -> data.PvStressUsdDiscountRate:
    """Build the PV Stress USD discount rate series keyed across paste-block copies.

    Resolve the USD discount rate used by the PV Stress block to a single typed series, taking historical-average values from the Input 7 residual-financing external-multiplier override and all other scenarios from the shared PV Stress anchor.

    Args:
        in7_resfin_ext_mlt_override: data.In7ResfinExtMltOverride series of keyword-only Input 7 residual-financing external-multiplier override values, supplying the 'Key variables at historical average' USD Discount rate entries; non-historical scenarios ignore it and fall back to the PV Stress anchor.

    Returns:
        data.PvStressUsdDiscountRate series giving the USD discount rate on PV Stress, keyed across paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['USD Discount rate'])
        return as_measure(pv_stress_usd_discount_rate['Key variables at historical average'])

    pv_stress_usd_discount_rate = CoordinateReader('pv_stress_usd_discount_rate', data.PV_STRESS_USD_DISCOUNT_RATE_REQUIRED, formula)
    return data.PvStressUsdDiscountRate.collect((coord, pv_stress_usd_discount_rate[coord]) for coord in data.PV_STRESS_USD_DISCOUNT_RATE_REQUIRED)

@publish(data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT_SCHEMA, cells=data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT_CELLS)
def pv_stress_average_maturity_of_new_debt(*, in7_resfin_ext_mlt_override: data.In7ResfinExtMltOverride, c4_mkt_fin_average_residual_terms: data.C4MktFinAverageResidualTerms) -> data.PvStressAverageMaturityOfNewDebt:
    """Return PV Stress average maturity of new debt by scenario.

    Selects the average maturity source for the historical-average scenario versus the market-financing residual-terms fallback, returning a typed PV Stress series.

    Args:
        in7_resfin_ext_mlt_override: Keyword-only data.In7ResfinExtMltOverride series supplying the average maturity including grace period override for the historical-average scenario.
        c4_mkt_fin_average_residual_terms: Keyword-only data.C4MktFinAverageResidualTerms series supplying the rounded maturity term from the market-financing average residual terms.

    Returns:
        A data.PvStressAverageMaturityOfNewDebt typed series of average maturity of new debt on PV Stress, keyed across paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. maturity (incl. grace period)'])
        return as_measure(c4_mkt_fin_average_residual_terms['Maturity\n(rounded)'])

    return data.PvStressAverageMaturityOfNewDebt.collect(evaluate(formula, data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT_REQUIRED))

@publish(data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT_SCHEMA, cells=data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT_CELLS)
def pv_stress_average_grace_period_new_debt(*, in7_resfin_ext_mlt_override: data.In7ResfinExtMltOverride, c4_mkt_fin_average_residual_terms: data.C4MktFinAverageResidualTerms) -> data.PvStressAverageGracePeriodNewDebt:
    """Compute the PV Stress average grace period on new debt.

    Resolve the scenario-dependent grace period used to amortize new debt in PV Stress calculations.

    Args:
        in7_resfin_ext_mlt_override: Typed data.In7ResfinExtMltOverride series covering Input 7 residual-financing external multilateral override coordinates, including the historical-average grace period used for the designated scenario.
        c4_mkt_fin_average_residual_terms: Typed data.C4MktFinAverageResidualTerms series covering market-financing average residual-term coordinates, including the rounded grace period used for non-historical scenarios.

    Returns:
        Typed data.PvStressAverageGracePeriodNewDebt series of average grace periods on new debt, keyed across PV Stress paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. grace period'])
        return as_measure(c4_mkt_fin_average_residual_terms['Grace\n(rounded)'])

    return data.PvStressAverageGracePeriodNewDebt.collect(evaluate(formula, data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT_REQUIRED))

@publish(data.PV_STRESS_PV_OF_NEW_FOREX_DEBT_SCHEMA, cells=data.PV_STRESS_PV_OF_NEW_FOREX_DEBT_CELLS)
def pv_stress_pv_of_new_forex_debt(*, pv_stress_discount_pv_of_debt: data.PvStressDiscountPvOfDebt, pv_stress_average_interest_rate_new_debt: data.PvStressAverageInterestRateNewDebt, pv_stress_usd_discount_rate: data.PvStressUsdDiscountRate, pv_stress_new_forex_borrowing_gross_usd: data.PvStressNewForexBorrowingGrossUsd, pv_stress_total_debt_service: data.PvStressTotalDebtService, pv_stress_amortization: data.PvStressAmortization, pv_stress_new_forex_borrowing_gross_usd_scenario: data.PvStressNewForexBorrowingGrossUsdScenario) -> data.PvStressPvOfNewForexDebt:
    """Computes the PV Stress present value of new foreign-currency debt in USD.

    Projects the discounted stock of new forex borrowing across the PV Stress scenario ladder, applying either plain or interest-rate-discounted accumulation depending on whether the average new-debt rate exceeds the USD discount rate.

    Args:
        pv_stress_discount_pv_of_debt: PV Stress discount factor series applied to the PV of debt, expressed as a data.PvStressDiscountPvOfDebt series over PV Stress scenario and time-period coordinates.
        pv_stress_average_interest_rate_new_debt: PV Stress series of average interest rates on new debt, expressed as a data.PvStressAverageInterestRateNewDebt series over PV Stress scenario and time-period coordinates.
        pv_stress_usd_discount_rate: PV Stress USD discount rate series, expressed as a data.PvStressUsdDiscountRate series over PV Stress scenario and time-period coordinates.
        pv_stress_new_forex_borrowing_gross_usd: PV Stress gross new foreign-currency borrowing in USD, expressed as a data.PvStressNewForexBorrowingGrossUsd series over PV Stress scenario and time-period coordinates.
        pv_stress_total_debt_service: PV Stress total debt service series, expressed as a data.PvStressTotalDebtService series over PV Stress scenario and time-period coordinates.
        pv_stress_amortization: PV Stress amortization series, expressed as a data.PvStressAmortization series over PV Stress scenario and time-period coordinates.
        pv_stress_new_forex_borrowing_gross_usd_scenario: PV Stress gross new foreign-currency borrowing in USD under the customized scenario, expressed as a data.PvStressNewForexBorrowingGrossUsdScenario series over PV Stress scenario and time-period coordinates.

    Returns:
        A data.PvStressPvOfNewForexDebt series holding the PV of new forex debt in USD, keyed across paste-block copies on PV Stress scenario and time-period coordinates.
    """
    data.PV_STRESS_NEW_FOREX_BORROWING_GROSS_USD_SCENARIO_SCHEMA.validate(pv_stress_new_forex_borrowing_gross_usd_scenario)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Market financing stress test / primary' and time_period == 2024:
            return as_measure((pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period] if xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary']) else xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period], pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario == 'Market financing stress test / primary' and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), pv_stress_new_forex_borrowing_gross_usd[scenario, time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2024:
            return as_measure((pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period] if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period], pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd_scenario[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario in ('Key variables at historical average', 'Tailored Stress Test 3. Commodity Price shock -External') and time_period == 2024:
            return as_measure((pv_stress_new_forex_borrowing_gross_usd[scenario, time_period] if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario in ('Key variables at historical average', 'Tailored Stress Test 3. Commodity Price shock -External') and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), pv_stress_new_forex_borrowing_gross_usd[scenario, time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / primary' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], pv_stress_amortization['Market financing stress test / primary', time_period]), pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / primary', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / primary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], pv_stress_amortization['Market financing stress test / secondary', time_period]), pv_stress_new_forex_borrowing_gross_usd_scenario['Market financing stress test / secondary', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd_scenario['Market financing stress test / secondary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / primary' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], pv_stress_amortization['Market financing stress test / primary', time_period]), pv_stress_new_forex_borrowing_gross_usd_scenario['Market financing stress test / primary', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd_scenario['Market financing stress test / primary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], pv_stress_amortization['Market financing stress test / secondary', time_period]), pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / secondary', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / secondary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Key variables at historical average' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Key variables at historical average', time_period - 1], pv_stress_amortization['Key variables at historical average', time_period]), pv_stress_new_forex_borrowing_gross_usd['Key variables at historical average', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Key variables at historical average', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Key variables at historical average', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Key variables at historical average', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Tailored Stress Test 3. Commodity Price shock -External', time_period - 1], pv_stress_amortization['Tailored Stress Test 3. Commodity Price shock -External', time_period]), pv_stress_new_forex_borrowing_gross_usd['Tailored Stress Test 3. Commodity Price shock -External', time_period]) if xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average']) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Tailored Stress Test 3. Commodity Price shock -External', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Tailored Stress Test 3. Commodity Price shock -External', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Tailored Stress Test 3. Commodity Price shock -External', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))

    pv_stress_pv_of_new_forex_debt = CoordinateReader('pv_stress_pv_of_new_forex_debt', data.PV_STRESS_PV_OF_NEW_FOREX_DEBT_REQUIRED, formula)
    return data.PvStressPvOfNewForexDebt.collect((coord, pv_stress_pv_of_new_forex_debt[coord]) for coord in data.PV_STRESS_PV_OF_NEW_FOREX_DEBT_REQUIRED)

@publish(data.PV_STRESS_TOTAL_DEBT_SERVICE_SCHEMA, cells=data.PV_STRESS_TOTAL_DEBT_SERVICE_CELLS)
def pv_stress_total_debt_service(*, pv_stress_interest: data.PvStressInterest, pv_stress_amortization: data.PvStressAmortization, pv_stress_interest_scenario: data.PvStressInterestScenario) -> data.PvStressTotalDebtService:
    """Compute total debt service on PV Stress across paste-block copies.

    Sums interest and amortization into a per-scenario total debt service series for the PV Stress framework.

    Args:
        pv_stress_interest: Interest series on PV Stress, a data.PvStressInterest named-axis tensor keyed by scenario and time period.
        pv_stress_amortization: Amortization series on PV Stress, a data.PvStressAmortization named-axis tensor keyed by scenario and time period.
        pv_stress_interest_scenario: Scenario-keyed interest series supplying the market-financing stress branches, a data.PvStressInterestScenario named-axis tensor.

    Returns:
        Total debt service in USD on PV Stress as a data.PvStressTotalDebtService named-axis series keyed across paste-block copies by scenario and time period.
    """
    data.PV_STRESS_INTEREST_SCENARIO_SCHEMA.validate(pv_stress_interest_scenario)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Market financing stress test / primary' and time_period == 2024:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2024:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))
        elif scenario == 'Key variables at historical average' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Key variables at historical average', time_period], pv_stress_amortization['Key variables at historical average', time_period]))
        elif scenario == 'Tailored Stress Test 3. Commodity Price shock -External' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Tailored Stress Test 3. Commodity Price shock -External', time_period], pv_stress_amortization['Tailored Stress Test 3. Commodity Price shock -External', time_period]))
        elif scenario == 'Market financing stress test / primary' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        return as_measure(xl_add(pv_stress_interest['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))

    return data.PvStressTotalDebtService.collect(evaluate(formula, data.PV_STRESS_TOTAL_DEBT_SERVICE_REQUIRED))

@publish(data.PV_STRESS_T_G_0_SCHEMA, cells=data.PV_STRESS_T_G_0_CELLS)
def pv_stress_t_g_0(*, pv_stress_calendar_period: data.PvStressCalendarPeriod, pv_stress_average_grace_period_new_debt: data.PvStressAverageGracePeriodNewDebt) -> data.PvStressTG0:
    """Compute the PV Stress t−g>0 series.

    Derive the non-negative PV Stress t−g measure by subtracting the scenario-appropriate average grace period for new debt from the calendar period and flooring at zero.

    Args:
        pv_stress_calendar_period: Calendar-period values as a data.PvStressCalendarPeriod series over PV Stress coordinates; supplies the per-period term in the t−g calculation.
        pv_stress_average_grace_period_new_debt: Average grace-period values for new debt as a data.PvStressAverageGracePeriodNewDebt series, with scenario-keyed entries including the market-financing primary and historical-average cases.

    Returns:
        A data.PvStressTG0 series of non-negative integer t−g values, keyed by PV Stress scenario and time period across paste-block copies.
    """
    def formula(scenario: str, time_period: int) -> int | str | None:
        if scenario == 'Market financing stress test / primary':
            return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Market financing stress test / primary']) if xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Market financing stress test / primary']), 0) else 0), 'int')
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']) if xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']), 0) else 0), 'int')

    return data.PvStressTG0.collect(evaluate(formula, data.PV_STRESS_T_G_0_REQUIRED))

@publish(data.PV_STRESS_T_M_CONDITION_SCHEMA, cells=data.PV_STRESS_T_M_CONDITION_CELLS)
def pv_stress_t_m_condition(*, pv_stress_calendar_period: data.PvStressCalendarPeriod, pv_stress_average_maturity_of_new_debt: data.PvStressAverageMaturityOfNewDebt) -> data.PvStressTMCondition:
    """Compute the PV Stress time-to-maturity condition series.

    Derives each scenario's non-negative time-to-maturity condition by subtracting average maturity of new debt from the PV Stress calendar period, flooring the result at zero.

    Args:
        pv_stress_calendar_period: PV Stress calendar-period series indexed by time-period coordinate, supplying the period used in the t-m subtraction.
        pv_stress_average_maturity_of_new_debt: PV Stress average-maturity-of-new-debt series keyed by scenario label, supplying the maturity offset for the selected stress scenario.

    Returns:
        A data.PvStressTMCondition series of integer time-to-maturity condition values, floored at zero, aligned to the required scenario and time-period coordinates and replicated across paste-block copies.
    """
    def formula(scenario: str, time_period: int) -> int | str | None:
        if scenario == 'Market financing stress test / primary':
            return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Market financing stress test / primary']) if xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Market financing stress test / primary']), 0) else 0), 'int')
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']) if xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']), 0) else 0), 'int')

    return data.PvStressTMCondition.collect(evaluate(formula, data.PV_STRESS_T_M_CONDITION_REQUIRED))
